window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[6]=[{"i":18462,"n":"זאב הירש מנאגי-שימוני","b":"רב בנאגי-שימוני-תקנה."},{"i":18463,"n":"זאב הכהן מפינסק וירושלים","b":"חתם-תרכב עם ראשי הכוללות בירושלים על כתב שליחות ר נתן נטע נאטקין."},{"i":18464,"n":"זאב וולף הכהן מטושין","b":"רב בטושין. חתן ר סיני ספיר"},{"i":18465,"n":"זאב וולף הכהן מלאסק","f":"יחיאל מיכל מזאלושין","k":"וועלויל חריף","bp":"לאסק(=לוסק)","dt":"תקצח - יד שבט","dp":"לאסק","b":"נכד ר שמואל לסקר מלוסק. מחכמי זאלושין, וארשא (עסק בתורה בחברת כמה מגדולי הדור ובהם בעל \"חמדת שלמה\" ור אלעזר הכהן בעל חידושי מהרא\"ך - קרוב משפחתו (שאביו שכרו ללמוד עמו). רב בלוסק על מקום ר מאיר צילך, ור משה יהודה ליב זילברשטין על מקומו אחריו. בנו - ר נתן מזאלושין, נכדו - ר אשר גרינס מוילטשין. גיסו - ר משה מזאלושין."},{"i":18466,"n":"זאב וולף הכהן מלבוב","f":"משה מרדכי מברעזן","dt":"שצט - ח חשון","dp":"לבוב","b":"רב ור\"מ בלבוב. חתן ר יעקב קופל הכהן. בנו - ר יהודה ליב יאליש כץ-חתנו של ר מרדכי יאליש מקראקא. (אולי המדובר בשני רבנים שונים)."},{"i":18467,"n":"זאב וולף הכהן מלומזה","f":"אריה ליב בן משה כץ","b":"רב בלאמזה, בריסק-תע. חתן ר אברהם אבא מארי מנוברדוק, חתן ר ישראל איסרל מבריסק (בזיוו\"ש?). בנו ר צבי הירש הכהן, חתנו ר יעקב הלפרין בעל \"בית יעקב\"."},{"i":18468,"n":"זאב וולף הכהן ממאדלי","f":"צבי הירש הכהן","b":"רב במאדלי-תק\"ל. חתן ר משה גינזבורג."},{"i":18469,"n":"זאב וולף הלוי מזיטומיר","k":"בעל אור המאיר","dt":"תקנז - ה סיון","b":"תלמיד המגיד ממזריטש. בזיוו\"ש חתן ר צבי הירש מרגליות ממזריטש. מגיד מישרים בזיטומיר. תלמידו ר אליעזר הלוי מזיטומיר - כתב את ספר רבו. מתולדותיו בקובץ \"שפתי צדיקים\". בניו ר ישרא דב בער, ר מנחם מנדל מברדיטשוב, ר צבי הירש, ר יוסף, ובניו מזיוו\"ש ר דוד, ר יחיאל מיכל, ר פנחס מקאלק-חתן ר צבי אריה מאליק. (באוצר תאריך הפטירה יד אדר תקס)."},{"i":18470,"n":"זאב וולף הלוי מזיטל","f":"יהודה","k":"בעל עמק הלכה","b":"רב בזיטל-ת\"ר. חיבר \"עמק הלכה\" וילנא תרז. חתנו - ר משה אברהם מבריסק-רבה הראשון של אילוקסט."},{"i":18471,"n":"זאב וולף הלוי משערשוב","b":"רב בשארשוב."},{"i":18472,"n":"זאב וולף הללס ממוהילוב","b":"רב במאהילוב-תק\"נ"},{"i":18473,"n":"זאב וולף מאליק","f":"זאב וולף-חתן המהרש\"?","k":"נכד המהרש\"ל?","dt":"תלא - יז אדר","b":"בנו של ר זאב וולף חתן המהרש\"ל. רב באליק, (באוצר הרבנים מופיע חתן המהרש\"ל - וכנראה טעות כי נפטר כ-100 שנה אחרי המהרש\"ל - וכנראה היה נכדו). בנו ר אלחנן מסטרי, ולפי פעסיס בנו גם - ר דוד פרנס. אצל פעסיס מופיע - חתן ר שלמה ר ליבוש'ס מפולנאה הנקרא בשם מהרש\"ל השני-רבו של בעל השל\"ה."},{"i":18474,"n":"זאב וולף מברוד","f":"יצחק","b":"רב בברודי. חתם עם הרש\"ק על גב\"ע."},{"i":18475,"n":"זאב וולף מדויד הורודוק","f":"שמואל מקאשיווקא","k":"אדמור מדויד הורודוק","dt":"תריט","b":"אחיו של ר יחיאל מיכל גינצבורג מקאשיווקא. חתן נכדת ר לוי יצחק מברדיטשוב."},{"i":18476,"n":"זאב וולף מדויד הורודוק","f":"ישראל יוסף מדויד הור","k":"אדמור מדויד הורודוק","dt":"תרפ א- ג אד\"א","b":"אדמור בדויד הורודוק על מקום אביו."},{"i":18477,"n":"זאב וולף מדויד הורודוק ארה\"ב","f":"לוי יצחק מדויד הורוד","k":"אדמור מדויד הורודוק","b":"אדמור בדויד הורודוק, נסע לארה\"ב וחזר. כנראה נספה בשואה."},{"i":18478,"n":"זאב וולף מדולינא","b":"תלמיד ר מנחם מנדל מקוסוב. ר יצחק מראדויל העיד עליו \"אדמור שיש לו חסידים כאלה עלינו לנהוג בו דרך ארץ\"."},{"i":18479,"n":"זאב וולף מדעסוי","f":"אברהם","k":"בעל פשר דבר","dt":"תקמד - כ אלול","b":"מחכמי דעסוי, מקורב למנדלסון. חיבר באור לאיוב בשם \"פשר דבר\" - תקלט, \"גרונזעטצע דער יידישער רעליגיאן\" (עיקרי דת היהודים)."},{"i":18480,"n":"זאב וולף מדעסוי","f":"יוסף","k":"בעל יסוד הלמוד","bt":"תקכב","bp":"דעסוי","dt":"תקפו - ז אד\"ב","dp":"דעסוי","b":"למד בברלין, מחכמי דעסוי, מורה בביה\"ס - יחד עם ר משה פיליפזון, ר משה זלמן הלוי (גוטהולד זלמן), סופר ונאמן הקהל. פעל אצל השלטונות לטובת הקהלה והצליח לבטל את מס ה\"לייבצאלט\"-1804. דרש בלשון אשכנז-1808 במעמד מושלי העיר (והיה הדרוש הראשון בלעז באשכנז). תרגם מהתנ\"ך ללשון אשכנז. חיבר \"יסוד הלמוד\" עם חברו ר זלמן הלוי, פרסם מאמרים ב\"השולמית\"."},{"i":18481,"n":"זאב וולף מהוסקוב","f":"יעקב משה מנחם מנדל","b":"רב בהוסקוב-תקנט, פרמישלא."},{"i":18482,"n":"זאב וולף מהורדנא","b":"תלמיד המגיד ממזריטש ורושם תורתו, ונדפס ב\"מגיד דבריו ליעקב\"."},{"i":18483,"n":"זאב וולף מהילדסהים","b":"רב בהילדסהים, בנו ר ישראל אשכנזי"},{"i":18484,"n":"זאב וולף מהרובשוב","dt":"תקו - כ אב","b":"רב בהרובאשוב, בנו ר שאול ונכדו ר חיים ליב מטרמבובלא"},{"i":18485,"n":"זאב וולף מוארדיש","b":"רב בוורדיש(=וראדיש)-תקע\"ה"},{"i":18486,"n":"זאב וולף מוילנא","f":"יחזקאל פיבל מוילנא","b":"חתן ר אליעזר בעל \"שיח השדה\". דרשן, מגיד בוילנא-תרי. חתנו - ר אליהו שיק מקוברין."},{"i":18487,"n":"זאב וולף מוילנא","f":"פסח","dt":"תקסד - טז אדר","dp":"וילנא","b":"מחכמי וילנא."},{"i":18488,"n":"זאב וולף מוילנא וירושלים","dt":"תרטו - ל כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":18489,"n":"זאב וולף מוישניצה","b":"דיין בוישניצה עם ר נתן אהרן. תשובה אליהם בחת\"ס."},{"i":18490,"n":"זאב וולף מזולקוא","f":"יהושע השל","b":"אב\"ד זולקוא על מקום ר יצחק לנדא, הסכים על שו\"ע - זולקוא תצט, \"ראשית חכמה\" - זולקוא תק, \"זהר\" פפד\"א תק."},{"i":18491,"n":"זאב וולף מטוקום ואילוקסט","bp":"טוקום","b":"יסד את ביהמ\"ד הראשון באילוקסט-תרה."},{"i":18492,"n":"זאב וולף מטיטשא","b":"רב בטיטשא-תרנ\"ו"},{"i":18493,"n":"זאב וולף מטעהר","b":"תלמיד ר פנחס מקוריץ."},{"i":18494,"n":"זאב וולף מטשרני אוסטרהא","f":"נפתלי צבי","r":"אב\"ד טשארני אוסטרהא","bt":"לפני תקטו","dt":"תקפג - ה אדר","dp":"טבריה","b":"תלמיד המגיד ממזריטש, ר זוסיא(=זושא) מאניפולי. מדברי תורתו בספר \"אור צדיקים\", בספר \"מנורת הזהב\", בספר \"בית אהרן\" לר אהרן מקרלין. נתפרסם מכתב שנשלח אל ר זאב מאת ר אשר סטולין. תלמידו הוא ר דוד שלמה אבד סירוקה, בעל \"לבושי שרד\" ו\"ערבי נחל\". רב בטשרני-אוסטרהא. עלה לארץ-ערב ר\"ה תקנט - התישב תחילה בחיפה (ואצלו התאכסן ר נחמן מברסלב כששהה בחיפה), ואח\"כ עבר לטבריה, ותלמידו ר מנחם מנדל מקוסוב על מקומו אחריו כמנהיג עדת חסידים, וחליפת מכתבים התנהלה ביניהם. בספר \"תורת חיים\" לר חיים מקוסוב נדפס מכתב שכתב ר זאב לר מנדל (נדפס בספר \"עשר צחצחות\"), ר זאב שלח לו מארץ ישראל שני חלוקים (חאלאטים), שעברו בירושה לאדמורי בית קוסוב. הקים את כולל גליציה-וואהלין בארץ ישראל. ראש הישוב בטבריה-תקע על מקום ר אברהם מקאליסק. מתורתו ב\"תקיפא דארעא ישראל\". בניו ר אברהם נפתלי, ור שלמה. חתנו ר ישראל אברהם בן ר משולם זוסיא מאניפולי על מקומו אחריו בטשרני-אוסטרהא. במכתב מספר ר ראובן פאפירש על מאסרו.","bk":[["מנורת זהב",""],["תקיפא דארעא דישראל",""]]},{"i":18495,"n":"זאב וולף מיאנוב","f":"יצחק - פני יצחק זוטא","b":"רב ביאנוב על מקום אביו-שנות התק'. חתם על מסמך של הקהלה-תקכד (מתחת לחתימת אביו-תקו)."},{"i":18496,"n":"זאב וולף מיוזפוף","b":"תלמיד החוזה מלובלין, ור חיים מאיר יחיאל ממוגלניצא."},{"i":18497,"n":"זאב וולף מלבוב","f":"אפרים פישל מלבוב","b":"רב-שנת ת\"מ, בנו ר שמואל מקראקא שהו\"ל קול הרמ\"ז."},{"i":18498,"n":"זאב וולף מלבוב","f":"ראובן זליג ר מייקיש","dt":"תכה - א אלול","dp":"לבוב","b":"רב בלודמיר?, דיין ור\"מ בלבוב, חתם-תכד עם בעל הט\"ז על קיום עדות, חתם-תמז ביריד ירוסלב כראש מדינה דגליל לבוב. (יש רשמו שם אביו חיים זליג - לדעת בובר בטעות)."},{"i":18499,"n":"זאב וולף מלבוב","f":"פנחס","b":"רב בלבוב, חתם-תסא על תקנת קהלת זולקוא, הסכים בירוסלב-תנג על \"בית יעקב\"."},{"i":18500,"n":"זאב וולף מלבוב","f":"יוסף בן אליקים גץ","b":"נכד(-אבי אמו) מהר\"ם מלובלין. מחכמי לבוב, נזכר בפנקס הקהל-תקא. אחיו - ר אריה ליב. גיסיו: ר משה בן דוד סגל, ר נחמן רפפורט מדובנא."},{"i":18501,"n":"זאב וולף מלבוב","f":"מנחם מנדל","b":"מראשי קהלת לבוב, חתם-תקל בפנקס הקהל."},{"i":18502,"n":"זאב וולף מלובלין","dt":"תעא - יז אדר","dp":"לובלין","b":"מראשי הקהילה בלובלין."},{"i":18503,"n":"זאב וולף מלובלין","f":"יעקב","b":"שמש ביה\"ד בלובלין-תקמט, אח\"כ דיין בלובלין. חיבר חדושי תורה - בכת\"י."},{"i":18504,"n":"זאב וולף מלובלין ופרג ופוזנא","b":"חתן המהרש\"ל. רב בלובלין בזמן מהר\"ם מלובלין - והיה מחלוקת ביניהם, אב\"ד פרג, פוזנא. בנו ר זאב וולף מאליק."},{"i":18505,"n":"זאב וולף מלוברטוב","dt":"תקצא - כט תמוז","dp":"לובלין","b":"דיין בלוברטוב."},{"i":18506,"n":"זאב וולף מלומזה","b":"רב בלאמז,בריסק-שנת ת'. חתן השר ר שאול ואהל"},{"i":18507,"n":"זאב וולף מלומזה ובריסק","b":"חתן השר ר שאול וייל. רב בלומזה, בריסק."},{"i":18508,"n":"זאב וולף מלונטשיץ","b":"רב בלונטשיץ. חתנו ר בנימין זילברברג מקוטנא"},{"i":18509,"n":"זאב וולף מליזנסק","f":"אלעזר","k":"בעל לשון הזהב","bt":"תמ","dt":"תקנג","b":"תלמיד ר יעקב יצחק סגל חריף מדוקלא. רבה של ליזנסק(=לינסק) בזמן הנועם אלימלך והיה מחסידיו. נפטר בגיל 113. חיבר \"לשון הזהב\" וארשא תרנט."},{"i":18510,"n":"זאב וולף מלמברג","f":"צבי הירש","b":"חתן ר אריה ליב"},{"i":18511,"n":"זאב וולף מלנדסברג","k":"בעל זאב יטרוף","b":"תלמיד ר דוד פרנקל בעל \"קרבן העדה\". רב בולשטיין, לנדסברג, מיושבי ביהמ\"ד של ר זכריה ור אליהו פרנקל בברלין. חיבר \"זאב יטרוף\" תקנג - ובו יוצא כנגד \"בשמים ראש\" לר שאול בן ר צבי הירש מברלין."},{"i":18512,"n":"זאב וולף ממוהילוב","f":"משה","b":"מצאצאי ר משה מעשילס-מצאצאי הרמב\"ם. רב במוהילוב."},{"i":18513,"n":"זאב וולף ממינסק","f":"משה","b":"ספרא ודיינא במינסק-תר בערך."},{"i":18514,"n":"זאב וולף ממינסק","f":"דוד","dt":"תקלא - י חשון","dp":"מינסק","b":"רב במינסק."},{"i":18515,"n":"זאב וולף ממינסק","f":"משה","dt":"תרח - ב אב","dp":"מינסק","b":"סו\"ד במינסק כ-32 שנה."},{"i":18516,"n":"זאב וולף מניישטטל","b":"רב בניישטטל-תק\"צ"},{"i":18517,"n":"זאב וולף מסוחוואילע","f":"יעקב","b":"מ\"מ ומו\"צ בסוחוואילע. הסכים-תקצג על \"אבות דרבי נתן\" לר אליהו בן אברהם מדליטיץ."},{"i":18518,"n":"זאב וולף מסקאלט","b":"רב בסקאליט-תק\"ג. חתן ר יצחק מקראקא וברודי. בנו ר יצחק ישכר בר מברודי"},{"i":18519,"n":"זאב וולף מסקאליט","b":"תלמיד ר משולם פיבש מזבאריז. הניח חדושים בכת\"י."},{"i":18520,"n":"זאב וולף מערלוי","b":"דיין בצפת-תרלט אצל ר שמואל הלר"},{"i":18521,"n":"זאב וולף מפרוזין וסלונים","b":"תלמיד ר דוד משארשוב בעל \"חומות ירושלים\". רב בפורזין, סלונים. פגש את הגר\"א יחד עם רבו."},{"i":18522,"n":"זאב וולף מקאוולי","b":"אב\"ד קאוולי-שנות ה-ש'-ת'. נספד מאת ר אברהם רפפורט ב\"איתן האזרחי\"."},{"i":18523,"n":"זאב וולף מקולומיאה","f":"אפרים","dt":"תרכה - א סיון","b":"תלמיד החוות דעת. רב בקולומיאה אצל ר גרשון אשכנזי."},{"i":18524,"n":"זאב וולף מקראקא","f":"מרדכי מזלאטיפאלי","b":"רב בקרקא-תר\"ע. חתן ר יהושע רוקח מבלז"},{"i":18525,"n":"זאב וולף מקראקא ומגנדורף","b":"רב במגנדורף-תקנ\"ט"},{"i":18526,"n":"זאב וולף משטאמפן","f":"יעקב חייט","b":"מראשי קהלת שטאמפי-תקו יצג את קהלת שטאמפי בבוררות עם קהלות פרשבורג וסערדהאלי. חתנו - ר קויפמן קליש בנו של ר יצחק קליש - רבה של שטאמפי."},{"i":18527,"n":"זאב וולף סגל מטרנופול","b":"רב בטרנופול-שנות ה-תק'. נזכר ב\"מאיר נתיבים\"."},{"i":18528,"n":"זאב וולף קאלוש מלבוב","b":"חתם בלבוב-שפג על תקנות קהלת זולקווא."},{"i":18529,"n":"זאב וולף קיצעס ממזבוז","r":"תלמיד הבעש\"ט","dt":"תקמט - יב חשון","dp":"מזבוז","b":"תלמיד הבעשט, ומראשי חבורת החסידים הראשונים במזבוז, ונאמן ביתו של הבעשט, ונטמן לצדו. יש האומרים כי הוא זה שביטל את מחשבת החרם בברודי כנגד הבעשט. מתורתו ב\"משנת חכמים\". בנו ר נחמן."},{"i":18530,"n":"זאב וילינקעס מויטבסק","b":"תלמיד ר שניאור זלמן בעל התניא."},{"i":18531,"n":"זאב חריף מזלישטשיק","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":18532,"n":"זאב יהושע מסטרטין","b":"שו\"ב מסטרטין. תשובה אליו - \"אמרי דוד\"-תרץ."},{"i":18533,"n":"זאב יצחק","b":"רב ביוזעפוף גדול"},{"i":18534,"n":"זאב מאוזראן","b":"אדמו\"ר באוזראן-תר\"ל. חתנו - ר חיים דוד מנסון."},{"i":18535,"n":"זאב מואדיסלב","b":"רב בוואדיסלב-שנת ת'"},{"i":18536,"n":"זאב מערפערט","f":"נתן","b":"גביר מפערעיאסלאוו-תריג, רכש אדמה בפלך חרסון והושיב שם חמישים משפחות יהודיות שעבדו בחקלאות - ועל כך קיבל מהממשלה תואר \"אזרח נכבד\" לדורות. חתן ר גבריאל יעקב בן נפתלי הירץ גינצבורג."},{"i":18537,"n":"זאב מפינטשוב","f":"גד","dt":"תכב - ג תמוז","dp":"פינטשוב או ואדיסלב","b":"אב\"ד בפינטשוב כ-22 שנה."},{"i":18538,"n":"זאב סגל","dt":"תשג","b":"רב בוועד הרבנים בווילנה"},{"i":18539,"n":"זאב צבי מזבארז","f":"המגיד מזלוטשוב","b":"רב בזבארז-תק\"ס"},{"i":18540,"n":"זאבאלי, יהודה ממרוקו","dt":"תקמ","dp":"לקצר(מרוקו)"},{"i":18541,"n":"זאבארו, יוסף מאזמיר","f":"אברהם","b":"דיין באזמיר-תל אצל ר אברהם דוגוזו."},{"i":18542,"n":"זאבארו, יוסף מברצלונה","f":"מאיר","k":"בעל ספר שעשועים","b":"תלמיד ר יוסף קמחי. רופא ומשורר מחכמי ברצלונה. חיבר גם \"בתי הנפש\"."},{"i":18543,"n":"זאבארו, יוסף מברצלונה","f":"בנבנשת","b":"מחכמי ברצלונה, חתם על מכתב החרם של הרשב\"א-ה'סח."},{"i":18544,"n":"זאבארו, משה מספרד","f":"יעקב","k":"בעל מלאכת סופר","b":"סופר מחכמי קשטיליה-רלב והעתיק הגהות על המסורה, ונזכרו בהגהות יעב\"ץ. לאחר הגירוש עבר לפאס. חיבר גם \"רמזי הלכות ספר תורה\" בכת\"י (בספריה הלאומית)."},{"i":18545,"n":"זאבי, אברהם חיים ישראל","f":"חייא","k":"בעל הגהות על הזהר","b":"רב בחברון, חתום בשנת תקכג על מכתב לר אברהם גאטיניו, ועל אגרת שליחות ר רחמים בג'איו ור יצחק זאבי, בשנת תקנב חתם על מכתב יהודי חברון. הדפיס ספר \"ימין משה\" לר חיים משה קריגל עם הוספות בשם \"באר מים חיים\" (האג תקלז). חיבר \"הגהות על זהר\" ליוורנו תקנא. מכתב שליחותו נדפס (חמד תקמב). בשליחות באיטליה."},{"i":18546,"n":"זאבי, אברהם חיים ישראל מחבר","f":"בנימין","k":"בעל אורים גדולים","bt":"תטו","dt":"תצא - אייר","dp":"חברון","b":"מחכמי חברון - תסא, נכדו של ר אברהם אזולאי בעל חסד לאברהם (לפי רוזניס היה תלמיד זקנו ר יצחק אזולאי - ולא אברהם). חתן ר אברהם קונקי בעל \"אבק סופרים\". בשנת תנב נתמנה לראש רבני חברון, בשליחות בקושטא שנת תמה נפגש עם חכם צבי, חותנו של ר אברהם יצחק רבה של ירושלים. חיבר ספר \"אור גדול, ו\"אור לישרים\" (אזמיר תקיח תקכו)","bk":[["אורים גדולים [שו\"ת]",""],["אור לישרים [עה\"ת]",""],["אורים גדולים – על ד' טורים",""]]},{"i":18547,"n":"זאבי, בנימין","f":"ישראל זאבי"},{"i":18548,"n":"זאבי, בנימין מחברון","b":"מחכמי חברון, בשנת תכא חתם על אגרת שליחות ר חייא דיין. כתב יד שלו מצוי בספריה הלאומית.(1010). בנו - ר אברהם ישראל בעל \"אורים גדולים\". חתנו של ר אברהם אזולאי (ולפי רוזניס חתן ר יצחק אזולאי, ובנו - ר אברהם)."},{"i":18549,"n":"זאבי, ברוך","b":"מחכמי חברון, בשנת תקמח חתם על כתב שליחות ר שמואל הכהן, באותה שנה חתם על בקשת עזרה של קהילת חברון."},{"i":18550,"n":"זאבי, ברוך מחברון","b":"רב בחברון-תקמ\"ח"},{"i":18551,"n":"זאבי, חייא מחברון","dt":"תקלה בערך","b":"מחכמי חברון,-תקל בשליחות הקהלה באירופה בשנת תפט היה בברלין, בשנת תקד בתורכיה, בשנת תקיד הסכים בחברון על ספר \"שער יוסף\" לחידא. בשנת תקיח הסכים על ספר \"אורים גדולים\" לר אברהם זאבי. בשנת תקכג חתם על בקשת עזרה לקהילת חברון. לאחר פטירת ר אהרן אלפנדרי היה ראש רבני חברון, חתם על כתב שליחות החידא בשנת תקיג."},{"i":18552,"n":"זאבי, חיים ישראל","b":"יצא בשליחות חברון לאשכנז ולהולנד-תקל\"ד,יצא שוב לאירופה-תקמ\"ב,יצא לארצות ערב ולהודו-תק\"ס"},{"i":18553,"n":"זאבי, חיים מרדכי מחברון וירושל","f":"חייא","b":"מחכמי חברון וירושלים, בשנת תמז הסכים בחברון על הספר \"שער אפרים\" לר אפרים מבודון, בשנת תנז חתם בחברון על הסכמה, הסכים על פסק דין של ר יוסף קובו, בשנת תס היה בירושלים, בשליחות בתורכיה-תנד, בהיותו בבלגרד אישר יחד עם ר נסים רוזיליו שליח חברון את פסק דינו של ר יצחק בן משה אב\"ד העיר בדבר סכסוך בקהלה. בהיותו בשליחות תיקן תקנות במקומות שליחותו."},{"i":18554,"n":"זאבי, חיים שלמה מחברון","b":"מחכמי חברון. בשנת תקד חתם על כתב שליחות ר אברהם גדיליה, ועל אגרת שליחות ר רחמים באג'יו ור יצחק זאבי בשנת תקכג."},{"i":18555,"n":"זאבי, יוסף חי מחברון","b":"מגדולי רבני חברון-תק\"צ, בשליחות חברון במרוקו. בנו ר רפאל יצחק עזריה גם הוא בשליחות חברון במרוקו."},{"i":18556,"n":"זאבי, יצחק מחברון","f":"אברהם ישראל","b":"לאחר שנתייתם גדל אצל ר חיים יהודה גומץ פאטו בחברון. למד בישיבת \"חסד לאברהם\". מחכמי חברון. בשנת תקד חתם על כתב שליחות ר אברהם גדיליה. בתקיח בשליחות חברון והדפיס באזמיר את ספר אביו \"אורים גדולים\". לאחר פטירת אביו גדל אצל ר יהודה גומץ פאטו. בשנת תקכג בשליחות עם ר חיים רחמים באג'יו (היה באזמיר ובאיטליה ועוד). השאיר כתבים שלא נדפסו. בהיותו בונציה הסכים על \"נהר שלום\"-תקלה."},{"i":18557,"n":"זאבי, ישראל מירושלים","b":"מרבני ירושלים-ש\"כ"},{"i":18558,"n":"זאבי, ישראל משלוניקי","f":"עזריה","bt":"שכז","bp":"שלוניקי","dt":"תה - אחרי","b":"עלה לירושלים וכיהן כרב-תו. חתם עם רבני ירושלים בשנת תו, מוזכר ב\"חורבות ירושלים\" כאחד הסובלים בפרעות אבן פארוך. בשנת תיא בשליחות בקושטא-תיא, ואחר כך באיטליה. היה בקשרי מכתבים עם ר יוסף מטרני. בנו - ר עזריה."},{"i":18559,"n":"זאבי, ישראל משלוניקי וירושלים","b":"מגדולי רבני שלוניקי,עלה לירושלים-ש\"מ"},{"i":18560,"n":"זאבי, מנחם יוסף חיים מחברון","b":"מחכמי חברון, בשנת תקמב חתם על אגרת הקהלה."},{"i":18561,"n":"זאבי, עזריה משלוניקי","f":"ישראל","bt":"שט","dt":"שפט","b":"מחכמי שלוניקי-שמט, שעלה לירושלים, חתנו של ר שמואל אבן סיד, נאסר בימי פרעות אבן פארוך בשנת שפה ואביו ר ישראל נאלץ לשלם סכום גדול לפדותו. למד אצל ר יצחק גאון, שאלה את ר שמואל ויטאל בדמשק. היה חותנם של ר מאיר פאפירש ור נתן גוטה. בנו - ר ישראל."},{"i":18562,"n":"זאבי, רפאל יצחק עזריה מחברון","f":"יוסף חי בן רפאל","dt":"תרנה - אחרי","dp":"חברון?","b":"מחכמי חברון. דיין אצל ר אליהו מני. בשליחות עצמו-תרד, וחתמו על המלצה לסייע לו בגלל מצבו הקשה - ר יום טוב אליקים, ר ברוך תורג'י מאן, ר אברהם שלמה קאריו, ועוד. בשליחות חברון במרוקו-תריח. דיין אצל ר אליהו מני בחברון, והיה מחלוקת ביניהם. חתם על החרם כנגד קהלת פונה שבהודו על שהדפיסו זהר בערבית."},{"i":18563,"n":"זאבלא","b":"רב-שנת ש\"פ"},{"i":18564,"n":"זאברזיר, אברהם מזולקווא","f":"דוד","k":"בעל ברכת אברהם","b":"נכד ר אברהם בן חיים לוסקער. מ\"מ בזאמושט, רב בזברז-תק. מתורתו ב\"פלפולא חריפתא\" - זולקווא תצו."},{"i":18565,"n":"זאהן, משה זאב","bt":"1876","bp":"קובנא","dt":"1946","dp":"רחובות","b":"מחנך ועסקן ציוני מראשוני חובבי ציון. תלמיד ישיבת סלובודקה. מראשוני המורים העבריים בקובנא. עלה לארץ-1936 והתישב ברחובות."},{"i":18566,"n":"זאהן, שלום שכנא מניו יורק","k":"בעל עטרת יעקב","b":"ר\"מ בישיבת \"תורה ודעת\" בניו יורק-תשיט. פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג."},{"i":18567,"n":"זאווי, שלום ממרוקו","dt":"תקעב - כט כסלו","dp":"רבאט-מרוקו","b":"מצדיקי רבאט-מרוקו. מלומד בנסים ורבים פקדו את קברו."},{"i":18568,"n":"זאווי, שמואל ממרוקו","b":"שו\"ב, וסופר בי\"ד במרוקו - שנות ה-תק', והיתה מחלוקת בקשר לשחיטתו, ובין המתנגדים לו ר שמואל קארו מסאלי. נתמנה לדיין בסאלי בעזרת רבני פאס ומכנאס, והיה מחלוקת בינו לבית הדין בסאלי של ר\"י צרפתי, ר\"ש כהן ור\"ש קארו, ולבסוף התחרטו רבני פאס ומכנאס ובראשם היעב\"ץ, וניסו להורידו מהדיינות."},{"i":18569,"n":"זאזון ן, יהודה מלעראייס-מרוקו","b":"רב בלעראייס-מרוקו-תקפא, חתם בפס\"ד-תקצה עם ר רפאל גזלאן."},{"i":18570,"n":"זאיית ן, יצחק","b":"מגדולי חכמי איטליה-ת\"פ"},{"i":18571,"n":"זאיית, יצחק מספרד","b":"מחכמי ספרד לפני הגירוש. היה במחלוקת עם מהר\"י די ליאון, ותשובות ממנו ב\"שבעה עינים\" כנגד מהר\"י די ליאון."},{"i":18572,"n":"זאכי, יצחק הכהן מביירות","b":"רב בביירות-לבנון, והקים שם תלמוד תורה."},{"i":18573,"n":"זאכרו, נסים מבגדד","f":"אלישע","bt":"תרז","bp":"בגדד","b":"מחכמי בגדד, עבר להודו וכיהן כראב\"ד בומבי-תרעד."},{"i":18574,"n":"זאלאמאן, אנעטע מאנגליה","b":"סופרת באנגליה. חיבר ספר באנגלית \"תוי הליכות דרך החיים\" - 1873 ובו הערות מוסריות מכתבי הקדש."},{"i":18575,"n":"זאלודוק, חיים אליעזר","dt":"תרצג - א תשרי","b":"מו\"צ בווילנה-תרמ\"ג"},{"i":18576,"n":"זאלמה, יצחק משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":18577,"n":"זאלמנס, אברהם צבי מנוברדוק","bt":"תרמב","bp":"מיר","dp":"תש..","b":"אביו היה דיין במיר. תלמיד ישיבת סלובודקא, למד בחברותא (את ספר קצות החושן) עם ר נפתלי אמשטרדם, ישיבת נוברדוק אצל הסבא מנוברדוק ונדד עם רבו ברחבי רוסיה. ראש ישיבת \"בית יוסף\" - נוברדוק בוארשא. תלמידו ר חיים זייציק הביא ממנו ועליו בספרו \"המאורות הגדולם\". נספה בשואה."},{"i":18578,"n":"זאלצער דוד","bt":"1841","dt":"ה'תרסח 1908","bk":[["דברי דוד",""]]},{"i":18579,"n":"זאמאטו, אלישע"},{"i":18580,"n":"זאמושט, דוד מברסלוי","f":"יוסף","k":"בעל אש דת","bt":"תקו","bp":"קעמפען","dt":"תרכד - כה ניסן","b":"מלמד בברסלוי, עסקן בקהלה. חיבר גם \"יסודות הדת\", פלגש בגבעה\", ועוד."},{"i":18581,"n":"זאמושט-בס, יעקב מפפד\"מ","f":"[משה]","k":"בעל חדות יעקב","dt":"תקז - יח אלול","dp":"פפד\"מ","b":"נקרא גם משה. דיין בפפד\"מ-תק. בניו: ר יצחק ור אליעזר הוציאו לאור את ספרו \"חדות יעקב\"-תקיא עם הוספות מהם."},{"i":18582,"n":"זאמושט-בס, יצחק מפפד\"מ","f":"יעקב - בעל חדות יעקב","dt":"תקלח - טו אב","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":18583,"n":"זאמושט-בס, מאיר מפפד\"מ","b":"דיין בפפד\"מ-תקנה - אצל ר מאיר שיף."},{"i":18584,"n":"זאמושט-בס, מנחם מנדל מפפד\"מ","f":"יצחק מפפד\"מ","dt":"תקעה - ח אב","dp":"פפד\"מ","b":"תלמיד ר ישראל ליפשיץ מקליווא. רב בפפד\"מ-תקל בערך, נזכר בספר רבו \"אור ישראל\". כונה בשם \"אח לחכמים ואב ליתומים\" על פעילותו הציבורית."},{"i":18585,"n":"זאמער, שמואל מפאפא","bt":"תקסח","dt":"תרט-יט","b":"תלמיד ר צבי הירש הלר בעל \"טיב גיטין\" בבאניהאד. רב בגיסינג,וורבוי, פאפא. (חברו של ר אברהם פריישטט מקומורן - שאל ממנו ספר ורשם זאת על השער)"},{"i":18586,"n":"זאמקוב, חיים יחיאל הכהן מהורדו","f":"מרדכי","dt":"תרמו - ח שבט","dp":"מינסק","b":"רב בהורדוק, עבר למינסק."},{"i":18587,"n":"זאפט, חיים מקעמפנא","b":"תלמיד החת\"ס, ור יהודה פולק ברודא מאויסע, ור יעקב משחה רעפיש מקעמפנא. רב בקעמפנא-תריח."},{"i":18588,"n":"ז'אק פאשה משלוניקי","f":"נסים דוד משלוניקי","b":"רופא יהודי בשלוניקי-בשנות ה-תר', למד בבית הספר הצבאי לרפואה בקושטא."},{"i":18589,"n":"זאקאן, יהודה אריה","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":18590,"n":"זאקאן, יצחק הכהן","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":18591,"n":"זאקאן, ישראל יצחק הכהן מזעלוב","b":"ר\"מ בישיבת \"בית ישראל\" (של חסידות אלכסנדר) בזעלוב. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":18592,"n":"זאקין, דוד ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":18593,"n":"זאקס, אברהם אלקנה מירושלים","f":"משה","b":"ממיסדי כולל הו\"ד בירושלים, דיין בירושלים, חתם-תרנד אחרי ר אריה ליב הורביץ."},{"i":18594,"n":"זאר (רבינוביץ), יצחק זליג","f":"אברהם","k":"בעל הסטטיקה והדינמיק","bt":"1884","bp":"קוריניץ-פלך וילנא","dt":"1957","b":"תלמיד ישיבות ליטא. ממנהיגי פועלי ציון וציר בקונגרס הציוני השמיני. עבר לניו יורק. פרסם מאמרים ביאוורייסקאיה ז'יזן\", ועוד. עורך \"אידישער קעמפער\" בנ\"י. חיבר גם \"המשק הלאומי והטריטוריה\", ועוד. ?? לא באוצר ??"},{"i":18595,"n":"זבדי ן, משה מפאס","b":"מחכמי פאס בזמן הרשב\"א, ונזכר בשות הרשב\"א. יתכן והוא בנו של ר דוד ן זבדי מפאס (נפטר מז - 1287) ושנזכר בכת\"י לר יוסף בן גליל."},{"i":18596,"n":"זבדיה הפייטן","b":"פייטן קדמון באיטליה-ד'תתק. חיבר סליחות ויוצרות."},{"i":18597,"n":"זבולון בן יעקב אבינו,","dt":"ז תשרי"},{"i":18598,"n":"זבולון מביאליסטוק","f":"צבי","dt":"תרנז","dp":"ירושלים","b":"מחכמי ירושלים חבר בבית הדין."},{"i":18599,"n":"זבולון מליטא","f":"יום טוב ליפמן","b":"נינו של ר יום טוב ליפמן מקרוז'. רב בדרשונישוק, גודלאווה, פיליפובה, קרוז', פולנגיאן - סביב תרי בערך. היה בקשרים עם ר צבי הירש קלישר."},{"i":18600,"n":"זבורויצר, צבי הירש מגורליץ","b":"רב בגולריץ, זמיגרוד. נכדו - ר אשר זליג לנדא."},{"i":18601,"n":"זבח, יצחק מקושטא","b":"רב בקושטא-שנות ה-ת'."},{"i":18602,"n":"זבלודבר, אהרן נפתלי מוארשא","dt":"תשג","b":"דומ\"צ בוארשא. פרסם מאמרים ב\"שערי תורה\" - וארשא תרסג."},{"i":18603,"n":"זבלודבר, צבי הירש מקלטשוב","dt":"תשג","b":"רב בקלעטשוב. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":18604,"n":"זבלודובסקי יחיאל מיכל בן חיים","bt":"1803","dt":"ה'תרכט 1869","bk":[["מי מיכל",""]]},{"i":18605,"n":"זבלודובסקי, יחיאל מיכל מביאליס","f":"חיים","k":"בעל מי מיכל","bt":"תקנה - בערך","b":"מחכמי ביאליסטוק. חיבר גם \"משען מים\" - וילנא תרכט."},{"i":18606,"n":"זבלודובר, שמואל דוד","bt":"תרלא","dt":"תשא - כח אב","b":"רב בציזוב-תרס\"ה"},{"i":18607,"n":"זבלצקי, משה","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":18608,"n":"זברסקה, גדליה הכהן","f":"יחיאל מיכל מברזובקה","k":"בעל חקרי לב - בכת\"י","bt":"תריב","b":"נכד ר מרדכי משארגראד. נסמך מאת: ר מרדכי דב מהורנסטייפל. רב בברזובקה-פלך חרסון-תרמז על מקום אביו, ונשיא ישיבת \"תורה אור\" בראשותם של ר זלמן שו\"ב ור משה קראקוב, ור שלמה לנגר (נוסדה ע\"י הגביר ר ראובן גרבר, ור יהושע השל)."},{"i":18609,"n":"זברסקה, יחיאל מיכל","b":"רב בבערזובקה-תרכ, ובנו ר גדליה על מקומו אחריו."},{"i":18610,"n":"זגדון, דוד מטריפולי","bt":"תע","dt":"תקם - בערך","b":"רב וסופר בטריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":18611,"n":"זגדון, יעקב מטריפולי","f":"אהרן","bt":"תם","dt":"תקי - בערך","b":"סופר דווקני בטריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":18612,"n":"זגול הלוי, חיים","k":"בעל דברי חז\"ל","b":"מרבני דמשק,עלה לירושלים,חיבר \"דברי חז\"ל\". ?? לא באוצר ??"},{"i":18613,"n":"זגון, יצחק","k":"בעל שדה יצחק","dt":"תשג","b":"רב בראדילישק. ?? לא באוצר ??"},{"i":18614,"n":"זגורי, דוד ממוגאדור","f":"מסעוד","k":"בעל לדוד להזכיר","bt":"תקסג","bp":"מוגאדור","dt":"תרנח","dp":"ליסבון","b":"תלמיד ר חיים פינטו, נרדף כנער בן 17 וישב בכלא, הקים ישיבה במראקש, לימד תורה בראבאט, הגיע לאיי פורטוגל בפונטה דל געדה, מו\"צ שם, חיבר \"לדוד להזכיר\", עבר לליסבון-תרלז"},{"i":18615,"n":"זגורי, יהודה ממראקש","dt":"תרט","b":"מחכמי מראקש, חכם כולל,מורה צדק"},{"i":18616,"n":"זגורסקי, אפרים מענקין מראסיין","f":"שלום ועגערער","k":"בעל תורת אל מות","bt":"תקעה","bp":"זאגר חדש","dt":"תרלא - יז טבת","dp":"וילנא","b":"מחכמי ראסיין ומלמד לתלמידים. חיבר \"תורת אל מות\" - בענין הנפש והשארתה."},{"i":18617,"n":"זגורסקי, אשר ליב","dt":"תרנו - כט אלול","dp":"וועליז-פלך ויטבסק","b":"נזכר בהצפירה-שנה כג."},{"i":18618,"n":"זגל, מנחם מנדל מלמברג","k":"בעל נר נשמה","b":"מחכמי ברודי. חיבר \"נר נשמה\" למברג תרכט, \"משניות אויף אידיש\" למברג תרכט. ?? לא באוצר ??"},{"i":18619,"n":"זגל, משה מלנצהוט","b":"רב בלאנצוט-תרפח, תשובה אליו \"אמרי דוד\"."},{"i":18620,"n":"זגנר, שלמה זלמן מדוקלא","f":"יצחק יונה","k":"בעל תל תלפיות","bt":"תריג","bp":"דוקלא","dt":"תרצב - יב שבט","b":"חסיד בלז ומלומד בשפות וחכמת המדעים. מחכמי סטריזוב ודוקלא. חיבר \"תל תלפיות\" למברג תרנב."},{"i":18621,"n":"זגרודסקי, ישראל חיים מניו יורק","k":"בעל דעס רמב\"מס לעבנס"},{"i":18622,"n":"זהריא, אברהם אבא יעקב","f":"יהודה ליב מברעסלאוו","dt":"תשא","b":"רב בלוזקי-תר\"ע,בברסלאוו(פולין)"},{"i":18623,"n":"זהריא, יהודה ליב מברעסלאוו","f":"יוסף זליג","bt":"תרי","b":"תלמיד ישיבת רמיילא(=מייליס) בוילנא אצל ר שמואל איסר ור סנדר, ר זליג מלוצין. נסמך מאת: ר הלל מסלנט, ר אברהם מפיקעלין, ר שאול זליג מדוינסק, ר אריהל יב מדוינסק. רב בליגמיאן-מחוז שוינציאן-תרלח, ראב\"ד בוויסאקי-ליטאווסק, ברסלוי(=ברעסלאוו)-פלך קובנא-תרנג. בנו - ר אברהם אבא יעקב מלוזקי, חתנו - ר אברהם זלמן הכהן משווערזנא(=שוורזנץ)-פלך מוהילוב."},{"i":18624,"n":"זהריא, יוסף זליג מדויג","bp":"לוצין-פלך ויטבסק","b":"תלמיד קרובו ר אבלי פאסוואלר מוילנא, ר מנשה מאיליא. התישב בדויג-פלך וילנא."},{"i":18625,"n":"זואנקין, דב","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":18626,"n":"זוארץ, בכור מטריפולי","b":"רב ומשורר בטריפולי, הו\"ל ותרגם לערבית חוברות במוסר והלכה כדי לזכות את הרבים, עלה לארץ וכיהן כרב במעברת \"מחנה ישראל\". עליו בכתב העת \"אגרת\"."},{"i":18627,"n":"זוארץ, יוסף משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":18628,"n":"זוארץ, פריג'א רפאל מטריפולי","f":"יצחק","bp":"טריפולי","dt":"תשנג","dp":"ישראל","b":"תלמיד ר חואתו לוזון. רב בכומס-לוב. מחנך ומשורר. נאסר ע\"י האיטלקים בזמן השואה, ושוחרר, עלה לארץ וכיהן כחבר כנסת מטעם \"הפועל המזרחי\". עורך \"חיינו - טריפולי תשט. חיבר מבוא ופירוש לפיוט \"שיר ידידות\" - ת\"א תשיז. מעורכי \"יהדות לוב\" תשך, פרסם מאמרים והו\"ל ספרים נוספים."},{"i":18629,"n":"זובער מקאוולא","b":"רב בקאוולא."},{"i":18630,"n":"זובער, יעקב ישראל מסטרשין","f":"מנחם מנדל","k":"בעל זכרון יעקב","bt":"תרנז","bp":"שצעדרין-פלך מינסק","b":"תלמיד ישיבות בוברויסק, לובאויטש. נסמך מאת: ר משה מרדכי פוגרלסקי מפאצעפ, ר מנחם מנדל פריידין בעל \"עליות מנחם\", ר מנחם מנדל ז\"ק מריגא. חתן נכדתר אברהם אוינסון מרבבינוביץ. רב בסטרעשין-פלך מוהילוב, סטשברי-גרוזיה, ריגא, שטוקהולם-שבדיה, בוסטון. עמד בראש ועד תקנות עגונות בסקנדינביה יחד עם ר שלמה דוד כהנא, ר יחזקאל אברמסקי מלונדון. בזמן השואה עסק בפעילות הצלה ובהם בני ישיבות מליטא לשנחאי-סין, בעזרת קונסול הולנד בשבדיה קיבל אשרות לקורסאו-שהיתה בשליטת הולנד, ופעל לטובת הפליטים שהגיעו לשבדיה. חבר אגודת ישראל באמריקה."},{"i":18631,"n":"זוברמן, אלקנה מיורדנוב","f":"צבי יהודה","bt":"תרסג","bp":"טרנוב","dt":"תשיט - א אלול","b":"חתן ר ישראל שרייבר. רב ביורדנוב לצד חותנו, ועל מקומו אחריו-תרפט. ברח מהשואה לסיביר והיה רב ליד טשקנט. רב בוולבזיך אחרי השואה. ועבר לארה\"ב-תשח שם כיהן כרב בברונזוויל. שימש כדיין בבית הדין של ר\"מ פיינשטיין. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"הלבנון\" - גורליץ תרפח, \"הנשר\" - טירנוי תרצג-תשד."},{"i":18632,"n":"זוברמן, יהושע מפוקשינוניצע","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":18633,"n":"זוזות, אליהו","f":"ברוך","k":"בעל האדם בשבחות","bt":"תרעו","bp":"מרוקו","dt":"תשנג - כז תמוז","b":"עלה לא\"י, רב מושב מחסיה, חיבר \"האדם בשבחות\""},{"i":18634,"n":"זוטא הנגיד ממצרים","b":"נגיד במצרים-ד'תתקף על מקום ר נתנאל אלנטע והרמב\"ם על מקומו אחריו."},{"i":18635,"n":"זוטא, חיים אריה","f":"שבתי דב","k":"בעל כתבי א. זוטא.","bt":"1868","bp":"קובנא","dt":"1938","dp":"ירושלים","b":"תלמיד ישיבות ליטא. ממיסדי ה\"חדר המתוקן\". אוני' ברלין. מורה בת\"ת בחרקוב, מורה בעברית בגימנסיה העברית ביקטרינוסלב. עלה לארץ-1904 ולימד ביפו וירושלים. מנהל ביה\"ס לדוגמא בירושלים."},{"i":18636,"n":"זויבר, יהושע אשר זליג מבוטשום","b":"תלמיד הכת\"ס. מחכמי בוטשום. נפטר בגיל 92."},{"i":18637,"n":"זויבר, קלמן","b":"תלמיד ר שמואל דוד יונגרייז. חתן ר מאיר רייניץ מיאטשיע. חדושים ממנו ב\"אוצר נחמד\" לגיסו. נפטר צעיר (אלמנתו נישאה בזיוו\"ש לר אשר ברייער מפעלעדיהאז)."},{"i":18638,"n":"זוין, שלמה יוסף מנובוזיבקוב","f":"אהרן מרדכי","r":"רב בקוזמירוב, קלימוב, מאגלין, ונובזיבקוב","bt":"תרמה","bp":"קאזימירוב","dt":"ה'תשלח","b":"נכד-אבי אמו ר שמואל אברהם מפאריטש-מחשובי חסידי חב\"ד. תלמיד ישיבת מיר. חתן ר יעקב יוסף לוין מפאריטש. נסמך מאת: ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ר יוסף רוזין הרוגצובר, ר שמריה נח שניאורסון מבוברויסק. רב בקויזמיסוב(=קאזימיראוו)-פלך מינסק, נובוזיבקוב-רוסיה (תחת השלטון הקומוניסטי). עלה לארץ-תרצה. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"בית מדרש\" - תל אביב תשא. עורך \"יגדיל תורה\" - בוברויסק תרפח, יחד עם ר יחזקאל אברמסקי - על מקום ר משה בנימין טומשוב שהיגר לניו יורק (והיה כתב העת היחידי שהופיע ברוסיה הקומוניסטית). פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\", \"המאור\" - תל אביב תרצה, \"המסלה\" - נ\"י תרצו, \"סיני\" - ירושלים תרצז, \"קול תורה\" - ירושלים תרץ-תשז, \"תבונה\" - קובנא תרפא, \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד.","bk":[["לאור ההלכה","מערכות"],["המועדים בהלכה","הלכה ומנהג - אחרונים"],["אישים ושיטות - מאמרים על אישי הלכה ושיטותיהם התורניות",""],["לאור ההלכה - בעיות ובירורים",""],["לשאלת הגיוס של בני הישיבות",""],["לתורה ומועדים - רסיסי הגיונות",""],["סופרים וספרים",""],["סיפורי חסידים",""]]},{"i":18639,"n":"זוכאוויץ, חיים משה מוילנא","dt":"תשג","b":"מרבני ווילנה"},{"i":18640,"n":"זוכוביצקי, פסח","f":"יוסף גרשון","bt":"תרכו","dt":"תשג","b":"מצאצאי הגר\"א, ור ישעיה זוכאויצער. ר\"מ בסלוצק, שמזבה(=שעמעזאווע)-פלך מינסק-תרסג, הנצביץ."},{"i":18641,"n":"זוכוביצקי, שרגא מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":18642,"n":"זוכובסקי, דב","b":"משגיח בישיבת \"כנסת ישראל\" בסלובודקה ובירושלים. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":18643,"n":"זוכמן, מאיר צבי הירש מקריסנפול","f":"נתן","k":"בעל חדושי תורה","bt":"תרי","bp":"קריסנפולי","dt":"תשא","b":"עבר לניו יורק-תרף. חיבר \"חדושי תורה\" מונקטש תרפט.","bk":[["אמרי ישרה",""],["חידושי תורה",""]]},{"i":18644,"n":"זוכרמן, יהושע מפקשיוניצא","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":18645,"n":"זולאר, יהודה מלונינעץ","f":"יצחק","bt":"תרכו","b":"מו\"צ בלעכוויטש-תרנד, רב בלונינעץ-פלך מינסק-תרנט. נסמך מאת: ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא."},{"i":18646,"n":"זולדוביץ, ברוך ממינסק","b":"גביר מראשי קהלת מינסק. מקורב ל\"גדול ממינסק\", עלה לירושלים."},{"i":18647,"n":"זולוטקוף, הלל ליאון","bt":"1865","bp":"וילנא","dt":"1938","b":"למד בסורבון בפאריס. פרסם מאמרים ב\"היום\" (בשם \"זקף גדול\"). היגר ללונדון הקים דפוס-1887. חיבר חוברת סוציאליסטית \"הגדה של פסח\". היגר לארה\"ב והתישב בשיקגו. עורך \"אידישער קוריער\", \"דאס אידישע פאלק\", ועוד."},{"i":18648,"n":"זולטי, דב בריש מטשקובה","b":"רב בטשקובה-תרסט. מחשובי חסידי רדומסק."},{"i":18649,"n":"זולטי, יוסף","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":18650,"n":"זולטי, יעקב בצלאל מירושלים","k":"בעל משנת יעב\"ץ","r":"רבה של ירושלים","bt":"תרף","dt":"תשמג","b":"דיין ורב ראשי בירושלים. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"קול תורה\" - ירושלים תרץ-תשז, \"שילה\" - ירושלים תשה, \"תבונה\" - ירושלים תשא-תשח.","bk":[["משנת יעבץ",""],["גנזי הספרי",""],["משנת יעבץ – רמב\"ם ושו\"ע",""]]},{"i":18651,"n":"זולטי, מיכל","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא, פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":18652,"n":"זוליצקי, אברהם הלל מבזל","b":"שו\"ב בבזל-שוייץ. פרסם מאמרים ב\"כרמנו\" - אלכסנדר-לודז תרצג, \"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":18653,"n":"זוליצקי, הלל מזדונסקא ואליא","b":"פרסם מאמרים ב\"עמק הלכה\" - וארשא תרפו."},{"i":18654,"n":"זולנפריינד, אברהם אבלי כץ מקאש","f":"חיים מאיר זאב רפפורט","k":"בעל פרס אבות","bt":"תקע - בערך","dt":"תרן - בערך","dp":"קאשוי?","b":"מצאצאי בעל הש\"ך. אביו - היה רבה של סעליש, זקנו - ר יצחק אברהם מפינטשוב בעל \"כתר כהונה. תלמיד וחתן דודו בעל \"שמן רוקח\" (והתגרשו), ר צבי הירש הלר. רב בקאשוי, זאלושיץ, חזר לקאשוי."},{"i":18655,"n":"זולצבך, זליגמן מפרשבורג","b":"תלמיד וחתן ר מאיר ברבי-אב\"ד פרשבורג. רב בפרשבורג-תקנ. הו\"ל ספר חותנו \"הלכות מהר\"ם ברבי\"."},{"i":18656,"n":"זולצבך, ליב","b":"דיין בדרמשטט,פונגשטט-תק\"צ"},{"i":18657,"n":"זולר, יעקב","dt":"תשד","b":"רב בלוניניעץ"},{"i":18658,"n":"זומביל, אברהם ממרוקו ואלטונא","f":"שמואל ממרוקו","dt":"תרד - ג תשרי","dp":"אלטונא","b":"עבר ממרוקו לאלטונא, נפטר ללא ילדים ובצוואתו הקים שתי ישיבות, האחת במרוקו והשניה באלטונא (הוקמה תריג) המיועדת ללומדים מבני ספרד והמכונה \"זומביל ישיבה\" ואחד הנאמנים היה ר יעקב עטלינגר. החכם הראשון שיש בה היה ר בנימין הכהן ממרוקו."},{"i":18659,"n":"זומרשטין, אברהם משה מיאנוב","b":"רב ביאנוב-תרלה."},{"i":18660,"n":"זונאנא דרומי, חיים מאדרינופול","f":"משה","k":"בעל רשמי עמל","bt":"תרנב","bp":"אדרינופול","b":"עלה לארץ-תרסט, תלמיד ביהמ\"ד לרבנים בירושלים, מורה בחברון, הרטוב, צפת, עכו. פרסם מאמרים ובהם זכרונות."},{"i":18661,"n":"זונאנא, ברוך מקושטא","b":"גביר מחכמי קושטא-שנות ה-תק'. אחיו - ר יעקב."},{"i":18662,"n":"זונאנא, ג'יליבי מקושטא","b":"שר מקורב למלכות בקושטא-תפג, סייע ליהודי ירושלים להיפטר מהצורר אבן פארוך-מושל ירושלים."},{"i":18663,"n":"זונאנא, דוד מקושטא","dt":"תקז","dp":"קושטא","b":"שר וגביר בקושטא, סייע לר יהודה נבון בהדפסת \"מחנה אפרים\" לאביו - ר אפרים נבון. בנו על מקומו אחריו כשר בקושטא."},{"i":18664,"n":"זונאנא, יוסף משלוניקי","b":"גביר בשלוניקי, וסייע במערכת המים לישיבה בשלוניקי-תקיב."},{"i":18665,"n":"זונאנא, יעקב מקושטא","b":"גביר מחכמי קושטא-שנות ה-תק'. אחיו - ר ברוך."},{"i":18666,"n":"זונאנא, יצחק מסופיה","b":"רב בסופיה-שנות ה-ת'."},{"i":18667,"n":"זונאנא, ישראל","b":"בשליחות-תקיד, מכתב המלצה אליו נשלח לר חיים מודעי באזמיר מאת ר ראובן בן יעקב מסופיה בשם רבו ר שלמה שלם בעל \"דברי שלמה\" והעביר דרכו את הספר לאזמיר."},{"i":18668,"n":"זונאנא, משה מקושטא","b":"דיין בקושטא-תקסה יחד ר חיים פריסקו ור יצחק הכהן."},{"i":18669,"n":"זונאנא, עובדיה מקושטא","b":"דיין בקושטא-תקץ בערך בבית הדין של עדת הסרסורים בקושטא."},{"i":18670,"n":"זונאנא, עמנואל מקושטא","b":"ממונה על איסור והיתר בקושטא-תקכח, דיין אצל ר אברהם מיוחס-תקכד. חתם על מכתב \"סרסורי פתחי הסוחרים\" הם המתווכים היהודים שעבדו בבתי המסחר של האירופאים בקושטא."},{"i":18671,"n":"זונאנא, שלמה הרופא משלוניקי","b":"רופא בשלוניקי, עבר לסופיה וחזר לשלוניקי-שס - בערך."},{"i":18672,"n":"זונדיל מראדושיץ","b":"תלמיד ר אלימלך מליזנסק. רב בראדושיץ. בן אחותו - ר ישכר דב מראדושיץ."},{"i":18673,"n":"זונדלביץ, אהרן","bt":"1852","bp":"קובנא","dt":"1923","b":"תלמיד ישיבת וילנא, סמרגון, מינסק. תלמיד ביהמ\"ד לרבנים בוילנא. הצטרף לתנועה המהפכנית (יחד עם חבריו ולדימיר יוחלסון, אהרן ליברמן, ואחרים שרובם סברו שהיהודים אינם אומה אלא קבוצה דתית), והיה בין מארגני נסיון ההתנקשות בחיי הצאר אלכסנדר השני. היגר ללונדון."},{"i":18674,"n":"זונה ישעיה","bt":"1887","dt":"ה'תשכ 1960","bk":[["לתולדות קהילת בולונייה",""]]},{"i":18675,"n":"זונטג, יחיאל הלוי","dt":"תרצ - כט תשרי","b":"רב בסקעמפא"},{"i":18676,"n":"זונטהיים, אלחנן","f":"משה טוביה","b":"מחכמי זונדהיים(=זונטהיים)."},{"i":18677,"n":"זונטהיים, משה טוביה","k":"בעל אור פני משה","bt":"תקיג","bp":"זונטהיים-ליד היילברון","dt":"תקצא - ד תשרי","b":"תלמיד קרובו ר נפתלי קצנלנבוגן מליימן בעל \"זכרון יוסף\" (ומזכירו בספרו). חתן נכדת ר הלל ממינץ ולייפניק. רב בהאנוי. היה בקשרי מכתבים עם הנודע ביהודה, ר עקיבא איגר, ועוד. נספד ע\"י קרובו - החת\"ס. הסכים על \"מחזורי ר וולף הידנהיים (למדו ביחד בישיבת בעל \"זכרון יוסף\"). בנו - ר אלחנן."},{"i":18678,"n":"זונין, חיים משלוניקי","b":"דיין בשלוניקי-שף."},{"i":18679,"n":"זוננבאנד, אברהם מנעשאווא","f":"רפאל","bt":"תרכב","b":"רב בזעלין-פלך פלאצק-תרמו, לוביטש-פלך פלאצק-תרנו, נעשאווא-פלך וארשא-תרסב."},{"i":18680,"n":"זוננבאנד, יהודה ליב מדברזין","f":"רפאל","k":"בעל וזאת ליהודה","bt":"תרכא","b":"תלמיד ר משה גרשון מפלונסק, ר בעריש מבענדין, נסמך מאת: ר פאלק אוירבך מפלאצק וברלין, ר מיכל בעל \"חשרת מים\". רב ביאנובה-פלך פלאצק-תרמח ,דברזין-פלך פלאצק. חיבר \"וזאת ליהודה\" על הש\"ס - בכת\"י."},{"i":18681,"n":"זוננבאנד, רפאל משה מטשכנוב","f":"בועז","k":"אדמור מטשכנוב","dt":"תרסה - י אייר","b":"נכד - מצד אמו - ר אברהם האדמור מטשכנוב, וגדל אצל זקנו. בסוף ימין אדמור בטשכנוב."},{"i":18682,"n":"זוננברג, זאב וולף - ב","dt":"תשג","b":"רב בביאלאוויש"},{"i":18683,"n":"זוננברג, זאב וולף זונדל מפטרבו","k":"זונדל הגדול","dt":"תריד - כד טבת","dp":"הורדנא","b":"גביר תלמיד חכם. הגיע לפטרבורג-תקעט והיה בועד היהודים שם."},{"i":18684,"n":"זוננה, עמנואל מאדרינופול","b":"תלמיד ישיבת ר אברהם מוטאל בשלוניקי ור אברהם הררי. רב קהלת הספרדים באדרינופול-שנות ה-ת' - בזמן ר חיים מבורך גליפפא."},{"i":18685,"n":"זוננפלד, אברהם אהרן מירושלים","f":"יוסף חיים","b":"עורך כתב העת \"אור תורה\" - ירושלים תרנז."},{"i":18686,"n":"זוננפלד, אברהם שלמה מווערבא","f":"שמואל נאדאש מיערגין","dt":"תריג - כה סיון","dp":"ווערבא","b":"תלמיד ר בנימין זאב וולף לעו מווערבא, והחת\"ס (כאביו לפניו). חתן ר אהרן בן חיים מווערבא והתגורר שם."},{"i":18687,"n":"זוננפלד, יוסף חיים מירושלים","f":"אברהם שלמה מוערבא","k":"בעל שלמת חיים","r":"השואל ר' שלמה סובל נפטר יג טבת תשל","bt":"תרט","bp":"וורבאו-סלובקיה","dt":"תרצב - יט אד\"ב","dp":"ירושלים","b":"תלמיד הכת\"ס, ור יהודה ליב לפלר מסעמניץ, ר חיים צבי מנהיימר מאונגוואר, ור אברהם שאג מקוברסדורף. חתן ר שלמה זלצר מקוברסדורף ועבר לשם. בזיוו\"ש חתן ר מנחם מנדל דייטש מטאפלטשן. עלה לירושלים-תרלג עם רבו ר אברהם שאג, למד אצל ר מאיר אוירבוך בעל \"אמרי בינה\", וכאשר עלה מהריל דיסקין הפך לנאמן ביתו, והרב מבריסק מינהו דיין בבית דינו. ולימים היה לראש הקהלה החרדית בירושלים, ועסק רבות בעניניי ציבור ואף בבנית שכונות בירושלים. ראש כולל אונגרין. רבה של ירושלים-תרף. חיבר \"תורת חיים\" ועוד. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\", \"שערי אורה\" - מיהאלביץ תרץ-תרצד.","bk":[["הנהגות ופסקים [הגרי\"ח זוננפלד]","הלכה ומנהג - אחרונים"],["תורת חיים [גרי\"ח זוננפלד]","שו\"ת - אחרונים"],["שלמת חיים","שו\"ת - אחרונים"],["סדר פורים המשולש",""],["שלמת חיים – שו\"ת",""],["תורת חיים – שו\"ת",""],["תורת חיים (גרי\"ח)",""]]},{"i":18688,"n":"זוננפלד, יעקב מאיר מירושלים","f":"יוסף חיים מירושלים"},{"i":18689,"n":"זוננפלד, שמעון מפרשבורג","b":"ממיסדי ביה\"ס בפרשבורג-תקף כנגד דעת החרדים."},{"i":18690,"n":"זוננשין, אברהם מניו יורק","b":"עסקן ציבור בניו יורק, ממיסדי בתי ספר עבריים לבנות-תרסט עם ר אפרים קפלן הכהן."},{"i":18691,"n":"זוננשין, אפרים מצורטקוב","b":"למד בביהמ\"ד בברלין-תרעב."},{"i":18692,"n":"זוננשין, יהודה צבי הירש","f":"מנחם","k":"בעל שער הקדש","bt":"תרי","dt":"תרע","b":"מחכמי הרימלוב. חיבר \"שער הקדש - מכתב ידידות\" למברג תרמו."},{"i":18693,"n":"זוננשין, משה מסטמארטון","k":"בעל צהר לבנון","b":"רב בסטמארטון-תקפ\"ז"},{"i":18694,"n":"זוננשין, פנחס ממיאווע","b":"חתן ר נתן נטע ברודא משוסבורג. חתנו - ר צבי הערצקא."},{"i":18695,"n":"זוננשין, צבי הירש מפודגורזע","f":"יעקב","bt":"תרע","bp":"פודגורזע","dt":"תשג","b":"חתן ר חיים ברייט מלינסק. החליף שו\"ת עם חכמי דורו. תשובה ממנו לר אלחנן הלפרין-תרצח."},{"i":18696,"n":"זוסלק, מאיר זאב וולף מסטניסלב","dt":"תרפז - בערך","b":"דיין בסטניסלב לפני מלחמת העולם הראשונה."},{"i":18697,"n":"זוסמן","b":"רב-שנת תק\"י"},{"i":18698,"n":"זוסמן, אבא צבי מאוסטרהא","f":"מאיר מאוסטרהא","dt":"תרמד - כג אלול","dp":"אוסטרהא","b":"גביר מחכמי אוסטרהא, כאביו וזקנו לפניו. מחברי הח\"ק-תריא, עסק בצרכי צבור ובעל צדקה גדול. חתן ר יעקב יהושע הורביץ מזלוזיץ ואשתו הצדקת היתה אשת צדקה וחסד מפורסמת. מבניו: ר אפרים זלמן, ר חיים מרדכי, ר יעקב יהושע, ר משה."},{"i":18699,"n":"זוסמן, אפרים זלמן מאוסטרהא","f":"אבא צבי מאוסטרהא","b":"גביר מחכמי אוסטרהא, כאביו וזקנו לפניו, עסק בצרכי צבור ובעל צדקה וחסד. מבניו: ר שלום חתן ר משה ברנשטין, ר מאיר-חתן הגיבר ר יעקב אטינגר מהומין, ר משה אהרן-חתן ר נתן הורביץ בן ר יעקב"},{"i":18700,"n":"זוסמן, אפרים פישל מאוסטרהא","f":"שלמה זלמן מאוסטרהא","b":"גביר באוסטרהא, בנו של הגביר ר שלמה זלמן בן הגביר ר מאיר. חתן קרובו-אבי גיסו הגביר ר שאול רוקח-חתנו של ר ירמיאל הורביץ. בעל בתי חרושת לפורצלן בואהלין ובהם עבדו והתפרנסו יהודים רבים."},{"i":18701,"n":"זוסמן, אפרים פישל מבודפשט","b":"רב בבודפשט-תרעד. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":18702,"n":"זוסמן, אשר דב מירושלים","b":"מחכמי ירושלים, חתם-תרסד עם רבני ירושלים."},{"i":18703,"n":"זוסמן, בנימין מזלוטשוב","f":"צבי","k":"בעל אונזער חנוך","bt":"תרמו","bp":"זלוטשוב","dt":"תשג","b":"מחנך ועסקן בזלוטשוב. נספה בשואה. חיבר \"אונזער חנוך\" למברג תרפב, ועוד."},{"i":18704,"n":"זוסמן, דב בריש מאוסטרהא","f":"מאיר מאוסטרהא","b":"גביר מאוסטרהא. חתן הגביר ר שמעון זימיל אפשטין מוארשא. נפטר צעיר."},{"i":18705,"n":"זוסמן, חיים מאוסטרהא","f":"מאיר מאוסטרהא","b":"גביר באוסטרהא-תרו. נפטר צעיר ללא ילדים."},{"i":18706,"n":"זוסמן, חיים מרדכי מאוסטרהא","f":"אבא צבי הכהן","dt":"תרמא - יז אייר","dp":"אוסטרהא","b":"חתן הגביר ר שלמה זלמן זוסמן מאוסטרהא. גביר תלמיד חכם מאוסטרהא. נטה לחסידות בניגוד לבני משפחתו ותמך בסתר בכמה מגדולי האדמורים ובהם ר אהרן מטשרנוביל, המגיד מטריסק. נפטר בחיי אביו. (היה טובל מדי יום וכדי להסתיר עצמו מבני משפחתו היה איש מיוחד בא מדי יום לפנות בוקר ומעירו והיה יוצא מבעד לחלון וטובל). מבניו: ר יהושע, ר שמלקא, ר נחום. חתנו ר מרדכי אטינגר."},{"i":18707,"n":"זוסמן, חיים משה מטרטקוב","b":"רב בטרטקוב לפני השואה."},{"i":18708,"n":"זוסמן, יהושע דובער מזאריק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":18709,"n":"זוסמן, יהושע מאוסטרהא","f":"חיים מרדכי מאוסטרהא","b":"גביר תלמיד חכם מאוסטרהא. חתן ר יצחק אהרן איטינגא בעל \"שו\"ת מהרי\"א\"."},{"i":18710,"n":"זוסמן, יואל מקאשוי","b":"רב בקאשוי, חתן ר יעקב פרנקפורטר מקאשוי. נ\"י תשלז."},{"i":18711,"n":"זוסמן, יונה מוארשא","f":"מאיר מאוסטרהא","b":"גביר בוארשא. חתן הגביר ר יקותיאל זיסל רפפורט בן ר חיים רפפורט מאוסטרהא."},{"i":18712,"n":"זוסמן, יוסף ליב מירושלים","b":"פרסם מאמרים ב\"תורה אור\" - ירושלים תשה."},{"i":18713,"n":"זוסמן, יעקב (יוקי) מאוסטרהא","f":"שלמה זלמן הכהן","dt":"תרטו - יח שבט","dp":"אוסטרהא","b":"גביר מחכמי אוסטרהא."},{"i":18714,"n":"זוסמן, יעקב יהושע מאוסטרהא","f":"אבא צבי מאוסטרהא","b":"גביר באוסטרהא. נפטר צעיר."},{"i":18715,"n":"זוסמן, יקותיאל זוסמן (זוסיא)","f":"שלמה זלמן מאוסטרהא","dt":"תריב - כו אב","dp":"אוסטרהא","b":"גביר מחכמי אוסטרהא. חתן הגביר ר משה זלמן מוארשא-אחיו של ר צבי הירש מזמוטש בעל \"תפארת צבי\"."},{"i":18716,"n":"זוסמן, מאיר הכהן מאוסטרהא","f":"שלמה זלמן מאוסטרהא","dt":"תרך - כז שבט","dp":"אוסטרהא","b":"אחיינו של ר חיים רפפורט מאוסטרהא. גביר מחכמי אוסטרהא, עשיר גדול, ונדבן. עזר לבן דודו ר יעקב רפפורט רבה של אוסטרהא. חתן הגביר ר מאיר מטיקטין. היה ידוע בדבריו המחוכמים והשנונים. פרסם מליצה בספר דודו ר חיים רפפורט \"מים חיים\". מבניו: ר אבא צבי, ר שלמה זלמן, ר חיים מאוסטרהא - נפטר צעיר ללא ילדים, ר דב בריש, ר יונה מוארשא. חתניו: שני בניו של הגביר ר אהרן לוריא ממינסק, ר ליבוש לנדא בן סנדר מאוסטרהא. (סיפר עליו הדיין ר מאיר אליהו מאוסטרהא כי ישב עמו בעת שהודיעו לו כי הרויח 70000 רובל בעסקה בפיירסן - ולא ניכר על פניו מאומה ושאל אותו על כך והשיב לו ר מאיר \"הלא סוחר אהיה גם בימים הבאים וכשם שאוכל להרויח כך אוכל להפסיד ולשמחה מה זה עושה\"). מחותן עם ר אורי' בער גינצבורג ממזריטש."},{"i":18717,"n":"זוסמן, מאיר מאוסטרהא","f":"אפרים זלמן מאוסטרהא","dt":"תקפח - יח אייר","b":"גביר מחכמי אוסטרהא. חתן ר יעקב אטינגר מהומין."},{"i":18718,"n":"זוסמן, מרדכי זאב מאוסטרהא","f":"צבי הירש מאוסטרהא","dt":"תרמה - ז אייר","dp":"אוסטרהא","b":"גביר תלמיד חכם מאוסטרהא וחבר הח\"ק-תריג, מסר את עסקיו ביד נאמנים וישב ועסק בתורה כל היום. חתן הגביר ר אהרן לוריא ממינסק, ובזיוו\"ש חתן נכדת הגביר ר מרדכי קלמן הלפרסון מזסלב. נתבקש לרב באוסטרהא על מקום ר יעקב רפפורט - אך סירב."},{"i":18719,"n":"זוסמן, משה מאוסטרהא","f":"אבא צבי מאוסטרהא","b":"גביר באוסטרהא."},{"i":18720,"n":"זוסמן, משה מאוסטרהא","f":"אפרים זלמן מאוסטרהא","b":"גביר מחכמי אוסטרהא. חתן ר נתן הורביץ."},{"i":18721,"n":"זוסמן, נחום מאוסטרהא","f":"חיים מרדכי מאוסטרהא","b":"גביר תלמיד חכם מאוסטרהא. חתן הגביר ר מרדכי אטינגר."},{"i":18722,"n":"זוסמן, צבי הירש מאוסטרהא","f":"שלמה זלמן מאוסטרהא","dt":"תרלב - יב אד\"א","dp":"אוסטרהא","b":"גביר מחכמי אוסטרהא. חתן דודו ר אברהם מייזלש-חתנו של הגביר ר אברהם אבלי מאוסטרהא. היה מקורב לדודו ר חיים רפפורט רבה של אוסטרהא, ומליצה ממנו נדפסה בספרו \"מים חיים\". בנו ר מרדכי זאב מאוסטרהא."},{"i":18723,"n":"זוסמן, צבי מאוסטרהא","f":"מאיר מאוסטרהא","b":"גביר באוסטרהא."},{"i":18724,"n":"זוסמן, שלום מאוסטרהא","f":"אפרים זלמן מאוסטרהא","dt":"תרעה - כא אב","b":"גביר באוסטרהא. חתן הגביר ר משה ברנשטיין."},{"i":18725,"n":"זוסמן, שלמה זלמן מאוסטרהא הזקן","f":"אבא הכהן מאוסטרהא","dt":"תקפב - ה אייר","dp":"אוסטרהא","b":"נכד ר יקותיאל זוסמן מאוסטרהא. גביר תלמיד חכם באוסטרהא, בעל צדקה מובהק. חתן הגביר ר חיים מחמלניק. בניו: ר מאיר, ר צבי הירש, ר יעקב, ר זוסיא, ר שמואל. חתניו: ר משה ביק מברודי, ר יוסף צבי מוזיש בן פישל מלמברג."},{"i":18726,"n":"זוסמן, שלמה זלמן מאוסטרהא הנכד","f":"מאיר מאוסטרהא","dt":"תרמא - ט אד\"א","dp":"אוסטרהא","b":"גביר מחכמי אוסטרהא. חתן ר יעקב יהושע הורביץ מזלוזיץ. בנו ר אפרים פישל. חתניו: ר שמלקא רוקח בן שאול, ר חיים מ רדכי זוסמן, ר אליעזר לנדא בן משה בן ר אליעזר בעל \"יד המלך\"."},{"i":18727,"n":"זוסמן, שמואל מאוסטרהא","f":"שלמה זלמן מאוסטרהא","dt":"תרלד - יד סיון","dp":"אוסטרהא","b":"גביר מחכמי אוסטרהא. חתן דודו הגביר ר משה הכהן מאוסטרהא בן הגביר ר אברהם אבלי מאוסטרהא."},{"i":18728,"n":"זוסמן, שמלקא מאוסטרהא","f":"חיים מרדכי מאוסטרהא","b":"גביר מחכמי אוסטרהא."},{"i":18729,"n":"זוסמן-דומב, מרדכי דוד מפרמישלן","dt":"תשז","b":"מחכמי פרמישלן. ברח מהשואה לסיביר, ואחרי המלחמה התישב בעיר הוהנמס-אוסטריה שם היתה ישיבה."},{"i":18730,"n":"זוסמן-סופר, בנימין זאב וולף","f":"דוד צבי","k":"חלפות שמלת בנימין","bt":"תקפו","bp":"פרשבורג","dt":"תרנח - יג אלול","dp":"פרשבורג","b":"נכד ר דניאל פרוסטיץ. תלמיד החת\"ס, הכתב סופר, ר משה שיק מחוסט ור יצחק משה פרלס מבאניהאד. חתן ר משה פליישמן-מאאר מקאמאראן ועבר לשם. רב בנאדי-וואשאן(=ואז'וני)-תריג, אדאנד, סענטגרוד-תרך, בודפשט-תרכט. (למרות שלמד אצל החת\"ס תקופה קצרה בילדותו - הקפיד כל ימיו לעמוד על רגליו כל פעם שהזכירו)."},{"i":18731,"n":"זוסמן-סופר, מרדכי אפרים פישל","f":"בנימין זאב וולף מזאל","k":"בעל עטרת פז","bt":"תרכז או תרלג","dt":"תשב - ל סיון","dp":"בודפשט","b":"תלמיד השב\"ס, ור משה סופר מטיסא-פירעד ור בנימין זאב ברייער מטאב. חתן ר יעקב קופל רייך מבודפשט. רב בקאסטאלאן-תרנא, טשוס(=טשיז)-תרנג, בודפשט-תרעד. מתורתו בספר אביו \"חליפות שמלת בנימין\", הניח כתובים בהלכה ואגדה - בכת\"י. בניו - ר שמעון אליעזר מירושלים ור חיים ישראל מגאלאנטא - תלמידי הדעת סופר. ?? לא באוצר ??"},{"i":18732,"n":"זוסמנוביץ, אשר דוב","b":"רב-שנת תר\"נ"},{"i":18733,"n":"זוסמנוביץ, יוסף מוילקומיר","f":"אשר דוב","k":"בעל חלקו של יוסף","bt":"תרנד-ה","bp":"ירושלים","dt":"תשא - אב","b":"תלמיד ישיבות טלז וסלובודקה, ונודע בכינוי \"העילוי הירושלמי\". חתן ר משה מרדכי אפשטין. רב בסלובודקה-תרפח על מקום חותנו-שעלה לארץ, יחד עם ר שלמה זלמן אוסובסקי. רבה האחרון של וילקומיר-תרצו. נספה בשואה עם בני עדתו."},{"i":18734,"n":"זוסניץ, יוסף יהודה ליב","f":"יחיאל מיכל","k":"בעל אכן יש ה'","bt":"1837","bp":"בירז'","dt":"1910","dp":"ניו יורק","b":"חתן ר חייקל לוריא מבירז. למד מתמטיקה ותכונה, התישב בבויסק והתקרב לר מרדכי אליאשברג. לאחר פרסום ספרו היה מחלוקת כנגדו מצד החרדים ששרפו את ספריו. חיבר גם \"שחוק השח\", ועוד. וכן מאמרים בנושאי מדע ותלמוד. זכה בפרס על פתרון בעיה מתמטית שהציג הפוליטכניון בריגא. היגר לארה\"ב-1891. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":18735,"n":"זוסקין, בנימין","f":"אריה","bt":"1899","bp":"פוניבז","dt":"1952","b":"שחקן ובמאי ברוסיה. נאסר ב-1949 והוצא להורג ע\"י סטלין-1952."},{"i":18736,"n":"זוראפה, חיים דוד שלמה מאלגיר","f":"שמואל בן סעדיה","k":"בעל בני שלמה","bt":"תקמה - בערך","dt":"תרך","b":"תלמיד החיד\"א, ור ח\"מ אלבו. דרשן, פוסק, רב ודיין בדזאייר(=אלגיר), והיה יחד עם ר דוד מועטי אחרוני הפוסקים והמשיבים בקהלת אלגיר. חיבר גם \"שער שלמה\", \"שם שלמה\" - ואבד, \"חיי משה\" - נזכר ב\"המאסף\"."},{"i":18737,"n":"זוראפה, יוסף מספרד ואלגיר","bt":"קץ - בערך","dt":"רע - בערך","b":"תלמיד הרשב\"ש, רב בתדל'ס, מיורקה, אלגיר, ולנסיה - תשובות אליו מהרשב\"ש למקומות אלו."},{"i":18738,"n":"זוראפה, סעדיה - ב","b":"מצאצאי ר סעדיה זוראפה תלמיד הרשב\"ש, העתיק את תשוובת הרשב\"ש ומכתב ידו נדפס הספר בליוורנו. תשובה ממנו ב\"זרע אנשים\"."},{"i":18739,"n":"זוראפה, סעדיה מאלגיר","f":"דוד בן סעדיה בן יוסף","dt":"שצה","b":"פייטן מחכמי אלגיר, בזמן הרשב\"ש - שאת תשובותיו העתיק ובסופם רשם שלשלת יוחסין למשפחתו, העתיק גם את \"יכין ובועז\", ועוד. משפחתו הגיעה מספרד אחר גזירות קנא. מפיוטיו במחזור ארגיל. חיבר קינה על ר יעקב זוראפה שנשרף עק\"ה. שיר ממנו לכבוד \"חשק שלמה\" ונציה שפג."},{"i":18740,"n":"זטולובסקי, עמנואל מהלמיאזוב","bt":"תקצה","bp":"קאהרלוק","dt":"תרנט - כט סיון","b":"חתן ר יחיאל זאב מהעלימיאזוב, רב בהעלמיאזוב על מקום חותנו כ-40 שנה."},{"i":18741,"n":"זטורנסקי, משה שלמה זלמן מקלעצק","f":"אליהו דוד הלוי מנישע","k":"בעל ברכת משה","b":"מחכמי קלעצק."},{"i":18742,"n":"זטלאווי, יעקב מטריפולי","bp":"תונס","dt":"תקפד","b":"הגיע מתונס לכהן כרב בטריפולי-תקסז. נזכר ב\"ויקרא אברהם\" לר חיים אדאדי."},{"i":18743,"n":"זטליר, שמואל זנויל מדוקלא","b":"מחכמי דוקלא-תרסא."},{"i":18744,"n":"זטנשטין, לואי","bt":"1874","dt":"1947","b":"היגר לארה\"ב והקים מפעל כריכה הגדול מסוגו באמריקה. נשיא מפעלי מולו\"ת שונים ונשיא אגודת הכורכים בניו יורק. עסקן ציבור."},{"i":18745,"n":"זטרר, שלמה זלמן","dt":"תקסח - יב אייר","b":"דיין בקרקא"},{"i":18746,"n":"זיבנברג, אברהם","b":"מו\"צ בוורשה"},{"i":18747,"n":"זיברטנסקי, שמואל ליובטשער","f":"יוסף","k":"בעל עולת שמואל","bt":"תקעח","bp":"ליובטש-מחוז נווהרדוק","dt":"תרנח - ח אב","b":"למד בילדותו עם ר אלכסנדר משה לפידות בוילנא. תלמיד זקנו ר צבי הירש מאסלאוואטי אב\"ד ליובטש. אחיהם של ר שלמה מדעלאטיץ, ר מאיר. מו\"צ בוילנא-תרמג. גבאי ארץ ישראל. סירב להצעות רבנות מכמה קהלות. הניח כתבים רבים בכת\"י והניח כסף לצורך הדפסתם."},{"i":18748,"n":"זיברסקי, צבי יהודה מאנטורפן","b":"דיין אצל ר מרדכי רוטנברג באנטורפן. לפני השואה."},{"i":18749,"n":"זיג, משה מאזמיר","dt":"תל - ג תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":18750,"n":"זיגל, אהרן מרישא וטיקטין","bp":"רישא","b":"רב בטיקטין-תרסח."},{"i":18751,"n":"זיגלואקס, שמואל צבי","b":"פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":18752,"n":"זיגלר, דוד מסאסוב","f":"אברהם מבוסק","bt":"תרסח","bp":"סאסוב","dt":"תרפח","dp":"סאסוב","b":"עסקן בקראקא. ממנהיגי אגו\"י, פרסם בכתבי עת. חתן הנגיד גרוספלד מקראקא ונפטר ערב החתונה."},{"i":18753,"n":"זיגמן, משה","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":18754,"n":"זיגר, אברהם מארה\"ב","dt":"תרצב","b":"עסקן ציוני, מזכיר ה\"שומר הצעיר\" באמריקה."},{"i":18755,"n":"זיגר, אברהם מגרודזיסק","b":"רב בגרודזיסק. רב צבאי במלחמת העולם הראשונה. תשובה אליו מרבו - \"פני מבין\". פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":18756,"n":"זידמן, אלתר עזרא מסטריזוב","b":"רב בסטריזוב אצל ר אלתר זאב הורביץ."},{"i":18757,"n":"זידמן, דוד מהורודנקא","f":"זאב אהרן מהורודנקא","bt":"תרמא","bp":"הורודנקא","dt":"תשכא","dp":"תל אביב","b":"מחכמי הורודנקא. חתן ר צבי פרמינגר מבוצאץ, התיישב בבוצאץ. מחשובי חסידי צורטקוב. עלה לתל אביב-תרצט."},{"i":18758,"n":"זידמן, הלל מבוצאץ","f":"אברהם מאיר","k":"בעל יומן גיטו וארשא","bt":"תרעה","bp":"בוצאץ","b":"עסקן בוארשא, בעל תואר דוקטור ומלומד בחכמת ישראל. ניצל מהשואה. ועבר לניו יורק-תשו. חיבר \"יומן גיטו וארשא\" בואנוס איירס תשז."},{"i":18759,"n":"זידמן, יעקב מוישניצא","b":"דומ\"ץ בוישניצא-תרפט."},{"i":18760,"n":"זידמן, ישראל איסר","b":"מקור שמו מאבותיו שסחרו במשי. עלה לירושלים-תרפב. מרצה במוסדות שונים. חיבר עם יהודה אליצור - ספר יהושע עם פירוש - ירושלים תשב."},{"i":18761,"n":"זידמן, מרדכי מאוזיראן","f":"יהודה דב","k":"בעל בגד ללבוש","bt":"תקסד","dt":"תרן","b":"רב באוזריאן-תקפח. חיבר \"בגד ללבוש\" למברג תרלז."},{"i":18762,"n":"זידמן, משה הירש מרוזינאטוב","b":"רב ברוזינטוב-תרי."},{"i":18763,"n":"זידמן, משה מבוצאץ","b":"מחכמי בוצאץ-תרע. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":18764,"n":"זידן, אהרן מרופשיץ","b":"רב ברופשיץ לפני השואה. בנו משה - נספה בשואה."},{"i":18765,"n":"זידנברג, יצחק","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":18766,"n":"זידנר, יחזקאל מקשאנוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":18767,"n":"זידפלד, גבריאל מפרשבורג","b":"משכיל מחכמי פרשבורג, לימד את ר יוזפא בן החת\"ס לימודים כלליים. חיבר שיר קינה על פטירת החת\"ס."},{"i":18768,"n":"זידר, משה מלמברג","b":"רב בסאסוב-תרף."},{"i":18769,"n":"זידר, משה מלמברג","b":"מרביץ תורה בלמברג. מתלמידיו ר ראובן מרגליות."},{"i":18770,"n":"זידר, ראובן מלמברג ליטווק","b":"ראש ישיבת למברג בשנות התרם. נקרא ליטווק ע\"ש מוצאו."},{"i":18771,"n":"זיו, אשר","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":18772,"n":"זיו, בנימין","f":"שמואל","k":"בעל כסף ואשראי בת\"א","bt":"1879","bp":"סיאד","dt":"1947","dp":"תל אביב","b":"נולד לאב תלמיד חכם וחקלאי. תלמיד ישיבת טלז, גימנסיה ריאלית בברלין. כלכלה בסורבון-פאריס. פעיל ציוני. עורך מדור כלכלה בעותנים שונים. יועץ משרד האוצר של לטביה-1918. עלה לארץ-1936, והיה פרופסור לכלכלה. פרסם מאות מאמרים בעניני כלכלה."},{"i":18773,"n":"זיו, גרשון מנחם מנדל מפלונגיאן","f":"יהודה ליב מפלונגיאן","dt":"תרסב - ט אייר","b":"רב בפלונגיאן על מקום אביו, טורגין(=טאווריג). בנו - המשכיל טוביה מבירז. ראה גם ר מנחם מנדל זיו מטאוריג (שהיה קרובו ויש שהחליפו ביניהם)"},{"i":18774,"n":"זיו, יהודה ליב מקרוז'","f":"עזריאל מקובנא","b":"אביו היה הרב הראשון בקובנא. קיבל את שם משפחתו בשנת תקסד - כשיצאה פקודת המלכות להיקרא בשמות משפחה. רב בקרוז', טלז ור אברהם שפירא על מקומו אחריו, פלונגיאן ובנו ר גרשון מנדל על מקומו אחריו. הסכים-תקצו על הדפסת ש\"ס וילנא. מומחה בדיני ממונות ובורר מקובל, ישב לצידו של ר אליהו קרטינגר (שהיה צעיר ממנו בהרבה). מתלמידיו - הגביר ר שלמה פיינברג מיורבורג."},{"i":18775,"n":"זיו, יום טוב ליפמן מסלנט","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":18776,"n":"זיו, יוסף יצחק מבריסק","bt":"תרלא","dt":"תרפה - ה אייר","b":"רב בציטיוואן(=ציטוביאן), בוטין, ראב\"ד בבריסק"},{"i":18777,"n":"זיו, יצחק משטעויאן","b":"תלמיד ישיבת סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה). רב בשטעוויאן-תר\"ס"},{"i":18778,"n":"זיו, כלב מאיר משילאל","k":"בעל גלת כלב","dt":"תשג","b":"רבה האחרון של שילעל(=שילאל), רבה האחרון של מיסיאד. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא. נספה בשואה. ?? לא באוצר ??"},{"i":18779,"n":"זיו, מנחם מנדל מטאוריג","dt":"תרסב - ז סיון","b":"מצאצאי ר עזריאל זיו מקובנא. רב בטאוריג(=טבריג, טורגין)-תרמ, מלמד תורה בראסיין. הניח חדושים בכת\"י. בנו - ר עזריאל מראסיין. קרובו של ר גרשון מנחם מנדל זיו (וכנראה שיש שהחליפו ביניהם - וקרובו הוא שהיה רב בטאוריג)."},{"i":18780,"n":"זיו, משה משאוולי","f":"גרשון מנדל","k":"בעל מחשבת משה","dt":"תרכג","b":"רב בשאוולי. אחיו - ר עזריאל מבירז."},{"i":18781,"n":"זיו, נחום זאב","f":"שמחה זיסל מקלם","bt":"תרו","bp":"קלם","dt":"תרעו","dp":"קלם","b":"תלמיד \"בית התלמוד\" בקלם, ישיבת גרובין, איישישוק. למד גם שפות ולימודים כלליים. התפרנס ממסחר ועמד בראש \"בית התלמוד\" בקעלם-תרס."},{"i":18782,"n":"זיו, עזריאל מבירז","f":"גרשון מנדל","dt":"תקפז - אחרי","b":"נכד ר יהודה ליב מפלונגיאן. רב בבירז-תקע בערך על מקום ר מנחם נחום קצנלנבוגן (ולפי אלבום ליטא - על מקום ר אברהם-אחי הגר\"א - אך ליפמן-קובנא טוען כי ר אברהם כלל לא היה בבירז), ור שמעון מארקל שפירא על מקומו אחריו. בזמן ר אבלי אב\"ד פוסבול. נזכר בשו\"ת \"גדולת מרדכי\" לר מרדכי אב\"ד בויסק. בזמנו היתה גזירת הגיוס - הקנטוניסטים, ומסופר שחלה מרוב צער עד שנפטר). אחיו - ר משה בעל \"מחשבת משה\"."},{"i":18783,"n":"זיו, עזריאל מקובנה והורדנא","f":"יהודה","dt":"תקא-ח","b":"חתן ר אריה ליב בן יעקב (אביו של ר יוסף שנכדו היה ר זאב וולף אלטשולר בעל \"שפת הים\"). רבה הראשון של קובנא. עזב את קובנא לאחר השריפה-תצא שחיסלה את הקהלה, עבר להורדנא?. בנו ר יהודה ליב זיו מקרוז' וטלז. מחותן עם ר שמואל תאומים בעל \"מקום שמואל\"."},{"i":18784,"n":"זיו, עזריאל מראסיין","f":"מנחם מנדל מראסיין","b":"שו\"ב בראסיין-סוף שנות ה-תר."},{"i":18785,"n":"זיו, שמחה זיסל ברוידא מקלם","f":"ישראל","r":"הסבא מקלם","bt":"תקפד","bp":"קלם","dt":"תרנח - ה אב","b":"תלמיד ר ישראל סלנטר בקובנא. מגדולי חכמי המוסר, יסד בקלם את ישיבת המוסר \"בית התלמוד\" ועמד בראשה. שיטת הלימוד המיוחדת שלו עוררה מחלוקת מצד גדולי תורה, ולכן עבר לגרובין-קורלנד, חזר לקלם ולימד בקיבוץ של בחורים מבוגרים. בנו ר נחום זאב על מקומו אחריו ב\"בית התלמוד\". בישיבתו למדו גם רוסית ובגרובין גם גרמנית - כחלק מתכנית הלימודים. מאמר הספד ממנו על ר ישראל סלנטר - ב\"קול תורה\" - גייטסהד תשז. מאמר ממנו ב\"תבונה\" - קובנא תרפא, \"תבונה\" - ירושלים תשא.","bk":[["חכמה ומוסר - תורה מוסר ויראה",""],["כתבי הסבא מקלם - חכמה ומוסר",""],["כתבי הסבא מקלם - חכמה ומוסר, חכמה ומוסר - תורה מוסר ויראה",""]]},{"i":18786,"n":"זיו-בירזער, טוביה אברהם מבירז","f":"גרשון מנחם מפלונגיאן","b":"מחכמי בירז. המליץ על \"אוצר נחמד\" לנ' הופמן."},{"i":18787,"n":"זיו-הורביץ, שלמה זלמן מפלונגיא","b":"שינה שמו מזיו להורביץ. דיין בפלונגגיאן, רב בקורטוביאן-ליד שאוויל. היה מקפיד במיוחד בשעטנז ולכן לבש רק בגדי בד ועל כך נקרא \"דער לייווענעטער רב\" (רב של בדים). בנו - ר יוסף יוזל מנוברדוק."},{"i":18788,"n":"זיואב, אריה ליב מהומל ודינבורג","b":"מו\"צ בהומל,דינבורג"},{"i":18789,"n":"זיוו, חיים מנ\"י","b":"תלמיד ישיבת \"רבי יצחק אלחנן\". פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":18790,"n":"זיויץ, משה שמעון מארה\"ב","f":"יחזקאל","k":"בעל חקר דעת","bt":"תרטו-יח","bp":"ציטוביאן-פלך קובנא","dt":"תרצו - יא אב","b":"תלמיד רר יצחק מלאיזעווע וקעלעס, ר שלמה איזיקס משאוויל, ר שלמה הורביץ, ר אליעזר גורדון בטלז. רב בפיקאלן-ליטא-תרמה, היגר לארה\"ב וכיהן כרב בבולטימור-תרמו, פיטסברג-תרנח (או תרמח). פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפו, \"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"בית ועד לחכמים\" - נ\"י תרסג, \"דגל התורה\" - וארשא תרפב, \"היכל התורה\" - נ\"י תרצג, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"מגד ירחים\" - סטמר תרפה, \"המגיד\" - סטמר תרפח, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"שערי ציון\" - ירושלים תרפא. בניו: יעקב-חתן הגביר ר משה צבי הרשמן מסינסינטי, יצחק, פלוני-חתן הגביר ר שמואל שוורץ מקאליש."},{"i":18791,"n":"זיונץ, אבא מליטא","b":"ניצל מהשואה והגיע לשנחאי-סין. עורך \"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":18792,"n":"זיטזומר, פסח הלוי מיארטשוב","bp":"מוסט","dt":"תשג","b":"חתן ר שלמה מסקול. רב בסקול-תרצב, יארטשוב-תרצה. נספה בשואה."},{"i":18793,"n":"זיטלבסקי, יוסף","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":18794,"n":"זיטמן, ישראל","k":"בעל עזרת ישראל","b":"רב-שנת תר\"ע."},{"i":18795,"n":"זיטפלד, גבריאל","k":"בעל רחובות הביאור","b":"סופר. חיבר גם \"אחוזת מרעים\" פרג תקפד."},{"i":18796,"n":"זייאנץ, ישראל","bt":"תריג","dt":"תרפט - ל כסלו","b":"רב בסקאלא"},{"i":18797,"n":"זיידל, בנימין מגלנטא","f":"שמואל מקאטא","bt":"תרלא או תרכט","bp":"קאטה","dt":"תרצב - כב תשרי","dp":"גאלאנטא","b":"תלמיד השב\"ס, וגיסו ר חזקיה פלויט אב\"ד שוראן. חתן ר שלום דב שטרן מסערדאוהל. רב בגאללאנטא-תרסא, ובנו ר שלום דב אשר על מקומו אחריו. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":18798,"n":"זיידל, יוסף מבלאשקי","f":"אייזיק בן דוד מלאסק","k":"יוסף הצדיק","dt":"תרי - יא אלול","dp":"בלאשקי","b":"מצאצאי ר נחום מלאסק. חתן ר אלימלך הלוי מקויל. אב\"ד בלאשקי."},{"i":18799,"n":"זיידל, משה מאשקה מלודז","f":"צבי הירש מאוזרקוב","dt":"תרכט - כב טבת","b":"מו\"ץ בלודז. הניח כתבים בהלכה וחסידות. חתנו - ר מנחם מנדל פסח, ונכדו - ר אברהם יוסף פסח מבלגיה וארה\"ב."},{"i":18800,"n":"זיידל, נחום מגאשעלסק ווישגראד","f":"איזיק בן דוד מלאסק","b":"אב\"ד גאשעלסק, וישגראד-תקץ. מתורתו ב\"אמרי בינה\" לר מאיר אוירבך. אחיו - ר יוסף זיידל מלאשקי, ר הירש לסקר מאוזורקוב."},{"i":18801,"n":"זיידל, צבי הירש לסקר מאוזרקוב","f":"איזיק בן דוד מלאסק","dt":"תקצו - א תשרי","dp":"אוזרקוב","b":"רבה הראשון של אוזרקוב. בנו - ר משה מלודז. לאחר שנפטר נישאה אלמנתו גולדה לר תנחום לובלינר מאמשינוב."},{"i":18802,"n":"זיידל, שלום דב אשר מגאלאנטא","f":"בנימין מגאלאנטא","bt":"תרע","bp":"גאלאנטא","dt":"תשד - כג סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יהושע בוקסבוים מגאלאנטא. רב בגאלאנטא-תרצב על מקום אביו. נספה בשואה."},{"i":18803,"n":"זיידל, שמואל מקאטה","b":"אביו של ר בנימין מגאלאנטא. חתניו - ר חזקיה פיבל פלויט משוראן, ור ישעיה בייערן משאראש-פוטוק."},{"i":18804,"n":"זיינא, דניאל","f":"משה","b":"מרבני כורדיסטאן-תרפ\"ח, שו\"ב בכפר רוסתקא, עלה לא\"י-תשט\"ו"},{"i":18805,"n":"זיינה, שלמה מפדובה","f":"אברהם","b":"מחכמי פדובה, מבני החבורה של הרמח\"ל."},{"i":18806,"n":"זייף, יוסף מציטוביאן","b":"רב בציטוביאן-עד תרעג."},{"i":18807,"n":"זייף, מנחם מניס","f":"צבי הירש אלעזר","bt":"תרע","bp":"זולקיב","dt":"תשג","b":"רב בזולקוא. חתן ר משה באב\"ד מזולקוא. נספה בשואה."},{"i":18808,"n":"זייציק, אברהם הכהן מיוראויטש","f":"בצלאל מסמילוביץ","bt":"תרלב","b":"רב ביוראוויטש-פלך מינסק-תרס."},{"i":18809,"n":"זייציק, בצלאל הכהן מסמילוביץ","b":"רב בסמילוביץ-תר\"ס"},{"i":18810,"n":"זייציק, חיים אפרים מפיעטרקוב","f":"אשר","k":"בעל המדע והחיים","bt":"תרסה","bp":"פיוטרקוב-פלך מינסק","b":"חתן ר ישראל וורמן מבאריש-ליד בוצאץ. תלמיד ישיבת \"בית יוסף\" נוברדוק במוזיר, אצל ר אברהם יפהן בביאליסטוק. ראש ישיבת נוברדוק בבוצאץ-תרף. ניצל מהשואה וגלה בסיביר, לאחר השואה הגיע לצרפת וסייע לר גרשון ליבמן להקים ישיבת \"אור יוסף\" בצרפת, עבר לארה\"ב, בזיוו\"ש חתן ר אברהם שמואל קוסצבסקי מליטא. עבר לניו יורק והקים עם חברו ר יצחק אורלנסקי את \"ישיבת קובל\" ברוח נובהרדוק, ר\"מ בישיבת הרב יפהן בניו יורק. עלה לארץ-תשכג והיה מנהל רוחני בישיבת \"תפארת הכרמל\" בחיפה, עבר לירושלים-תשכז והקים ישיבה בשם \"אור חדש\". חיבר \"המדע והחיים\" ניו יורק תשיב, \"אור הנפש\", \"אור חדש\", חיבר גם \"המאורות הגדולים\" נ\"י תשיג - על חיי גדולי תנועת המוסר."},{"i":18811,"n":"זייציק, נחמיה הכהן מבויד","f":"חיים נתן","bt":"תרלב","b":"רב בבויד-פלך וילנא-תרסח."},{"i":18812,"n":"זייציק, נפתלי הרץ מארה\"ב","f":"נתן נטע הכהן-אהל נטע","bt":"תרכח","bp":"זעטיל-פלך גרודנא","b":"חתן הגביר ר שמואל ראטקאוויץ מנווהארדוק. תלמיד ישיבת וולוזין. רב בדה מויין-מדינת אייווא-ארה\"ב-תרסו. נסמך מאת: ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\"."},{"i":18813,"n":"זייציק, נתן נטע מזעטיל הכהן","k":"בעל אוהל נטע","b":"מחכמי זעטיל-פלך קובנא והתפרנס ממסחר. בנו - ר נפתלי הרץ - רב בדה מוין-ארה\"ב. חיבר \"אוהל נטע\" - בכת\"י."},{"i":18814,"n":"זייציק, ראובן (רוברט)","bt":"1868","bp":"ליטא","dt":"1936","dp":"שוייץ","b":"מרצה לספרות בשוייץ. פרסם ספר על מצבם החוקי של יהודי אוסטרו-הונגריה. התנצר-1906 והטיף לרעיון שרק הנצרות יכולה לפתור את המשבר הרוחני של הדור. התישב באסקונה-ליד לוקרנו-1921. פרסם ספרים בנושאי הנצרות והיהדות."},{"i":18815,"n":"זיכל, משה מפפד\"מ","b":"מראשי קהילת פפד\"מ-תפ בערך."},{"i":18816,"n":"זיכלינסקי, אפרים מאיר גד","f":"חנוך סעדיה מזיכלין","k":"בעל להב אש","b":"בן האדמור מזיכלין. רב-שנת תרפ."},{"i":18817,"n":"זיכלינסקי, חנוך סעדיה מסטריקוב","f":"משה נתנאל מזיכלין","k":"אדמור מזיכלין","bt":"תרמה","dt":"תשג","b":"אדמור בזיכלין(=זשיכלין), עבר לסטריקוב, לודז. עמד בראש חברת \"שמירת שבת\" בלודז. נספה בשואה עם בנו ר אפרים מאיר גדל בעל \"להב אש\", וחתנו ר ראובן טשארניחא בעל \"נפלאות הסבא קדישא מרדושיץ\" - היה במשלוח הראשון מוארשא למחנות ההשמדה."},{"i":18818,"n":"זיכלינסקי, יהושע פתחיה","f":"משה נתנאל מזיכלין","k":"בעל זמר צדק","b":"בן האדמור מזיכלין. הו\"ל ספר זקנו ר שמואל אבא מזיכלין בשם \"זמר צדק\"."},{"i":18819,"n":"זיכלינסקי, מנחם ידידיה מזיכלין","f":"משה נתנאל מזיכלין","k":"אדמור מזיכלין","bt":"תרל","dt":"תש - פסח","dp":"זיכלין","b":"חתן ר ישעיה מבלנדוב (שושלת קוזניץ). רב ואדמור בזיכלין על מקום אביו."},{"i":18820,"n":"זיכלינסקי, משה נתנאל מזיכלין","f":"שמואל אבא מזיכלין","k":"אדמור מזיכלין","dt":"תרעב","dp":"זיכלין","b":"חתן ר חיים צבי אשכנזי מזוויחוואסט. בנו ר יהושע פתחיה הו\"ל \"זמר צדק\" לזקנו ר שמואל אבא מזיכלין."},{"i":18821,"n":"זיכלינסקי, שמואל אברהם אבא","f":"מנחם ידידיה מזיכלין","k":"אדמור מזיכלין","dt":"תשב - יג אדר","dp":"זיכלין","b":"חתן ר אלעזר מסטאשוב (שושלת ליזנסק). אדמור בזיכלין-תש על מקום אביו. נספה בשואה. בניו: ר מרדכי אפרים, ר אביגדור ברוך, ור אשר - נספו בשואה."},{"i":18822,"n":"זיכלנסקי, משה נתנאל מלודז","f":"חנוך סעדיה מזיכלין","k":"אדמור מזיכלין בלודז","dt":"תשג","b":"רב ואדמור בלודז בחיי אביו."},{"i":18823,"n":"זיכרמן, נתן נטע מבליגרד","f":"יצחק","bt":"תקפא","dt":"תרסז","b":"רב בבליגרוד."},{"i":18824,"n":"זילבר בנימין יהושע בן ברוך","bt":"1916","dt":"ה'תשסח 2008","bk":[["אז נדברו",""],["ברית עולם",""],["מקור הלכה",""],["תורת היראה",""]]},{"i":18825,"n":"זילבר, אהרן יהושע מקראקא","f":"מאיר פרץ הכהן","bt":"תרפב","bp":"קראקא","dt":"תשסב","b":"עבר לוינה. ניצל מהשואה - נשלח במשלוח הילדים לאנגליה לפני השואה. תלמיד ר\"מ שניידר ולמד בכולל גיטסהד אצל ר אליהו דסלר. חתן ר משה שטיינהוז. בראש מערך הכשרות בלונדון. עלה לבני ברק-תשנב."},{"i":18826,"n":"זילבר, אליעזר מארה\"ב","f":"בונם צמח מקאמאי","k":"בעל ענפי ארז","bt":"תרמב","bp":"אבאל-פלך קובנא","dt":"תשכח - ט שבט","dp":"סינסינטי","b":"תלמיד ר דוד פרידמן מקרלין בעל \"פסקי הלכות\" ור מאיר מיכל משאט, ור חיים סולוביציק, ור זלמן סנדר כהנא שפירא, וקיבוץ ר חיים עוזר גרודזנסקי בוילנא. רב בלטביה-תרסו נאלץ לעזוב והיגר לארה\"ב-תרסז, רב בהריסבורג-תרסח, ספרינגפילד-מסצוסס-תרפה, סינסינטי-תרצא, השתתף בכנסיה הגדולה במאריענבאד. נשיא אגודת הרבנים באמריקה. ממיסדי \"אגודת ישראל\" בארה\"ב. ממיסדי ועד ההצלה בזמן השואה, וסייע להגירת יהודים חרדים לאמריקה אחריה, בשליחות באירופה לצורך סיוע לפליטים. חיבר גם \"צמח ארז\". בנו רד\"ל זילבר רב בהריסבורג. חיבר גם \"צמח ארז\" נ\"י תשלה, \"דגל התורה\" - וארשא תרפב, \"מגדל תורה\" - נ\"י תרפה, \"המתיבתא\" - נ\"י תשג, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז."},{"i":18827,"n":"זילבר, אפרים מהודודונקא","f":"פנחס","k":"בן פז\"י -בעל שדה י-ם","bt":"תקצז","bp":"הורודנקא","dt":"תרעה","b":"חתן ר משה תאומים מהורודנקא. פרסם בכתב עת שונים. חיבר \"שדה ירושלים\" טשרנוביץ תרמג, ועוד."},{"i":18828,"n":"זילבר, בונם צמח מדוסיאט","f":"נתן נטע","bp":"דוסיאט","b":"רב בדוסיאט על מקום אביו, קאמאי, שאט."},{"i":18829,"n":"זילבר, בנימין יהושע מירושלים","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט, \"תבונה\" - ירושלים תשא-תשח."},{"i":18830,"n":"זילבר, דוד ליב מניו יורק","f":"אליעזר מסינסינטי","bt":"תרסז","bp":"ניו יורק","b":"תלמיד ישיבת רבי יצחק אלחנן בניו יורק אצל ר שלמה פוליאצוק, ר שמעון שקופ, ר משה סולוביציק, ונסמך ממנו ומאת: רמ\"ז מרגליות, הרב ד\"ר דב רעוועל, ר בנימין ארונוביץ. חתן ר יצחק איזיק איזנברג מג'רסי סיטי. רב קהלת \"כתר ישראל\" בהריסבורג-פנסילבניה ויסד ישיבה. חבר אגודת הרבנים באמריקה ותנועת המזרחי."},{"i":18831,"n":"זילבר, דוד מברזאן","b":"רב בברזאן-תרע."},{"i":18832,"n":"זילבר, זכריה מנדל מקולומיאה","f":"אברהם פסח","bt":"תקף","bp":"גוליגור","dt":"תרצב או תרנב","b":"רב בקולומיאה. בנו ר יהושע על מקומו אחריו."},{"i":18833,"n":"זילבר, חיים דוד","dt":"תשג","b":"רב בקויל. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":18834,"n":"זילבר, חיים יעקב","dt":"תרצט - יז כסלו","b":"רב בארה\"ב"},{"i":18835,"n":"זילבר, יהודה זלמן","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":18836,"n":"זילבר, יהושע השל מקולומיאה","f":"זכריה מנדל","bt":"תרך","dt":"תרץ","b":"רב בקולומיאה על מקום אביו."},{"i":18837,"n":"זילבר, יחזקאל מאולינוב","f":"שמשון","b":"רב באולינוב על מקום אביו. בנו ר יעקב על מקומו אחריו."},{"i":18838,"n":"זילבר, יעקב מאולינוב","f":"יחזקאל","b":"רב באולינוב על מקום אביו"},{"i":18839,"n":"זילבר, ליפא ליב","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":18840,"n":"זילבר, מנדל","f":"יעקב","k":"בעל הגאון מוילנא","bt":"1882","bp":"וילקומיר","b":"היגר לארה\"ב-1900, למד בהיברו יוניון קולג'. רב ריפורמי? בסט לואיס, ניו אורליאס, ועוד. חיבר גם \"מנהגי קבורה בישראל\", \"ספורי התורה\", ועוד."},{"i":18841,"n":"זילבר, מרדכי","b":"דומ\"צ בנייזטץ-תקצ\"ב"},{"i":18842,"n":"זילבר, מרדכי הכהן מקרקא","dt":"תש..","b":"מחכמי קראקא. חתן ר מנחם מנדל הלרבשטם מקשאנוב. רב לצד חותנו בקשאנוב. נספה בשואה."},{"i":18843,"n":"זילבר, מרדכי שלמה מארה\"ב","bt":"תרכד","dt":"תרפה - כד אדר","b":"רב במיניאפוליס-ארה\"ב-תרס. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":18844,"n":"זילבר, משה מליטא וירושלים","k":"בעל חלוקי כסף","bp":"צייקישוק","dt":"תשט","dp":"ירושלים","b":"רב בליטא, עלה לירושלים. אביו של אבא הלל סילבר מארה\"ב. ?? לא באוצר ??"},{"i":18845,"n":"זילבר, משה מנחם מדטרויט","f":"אלכסנדר","k":"אדמור מסלונים דטרויט","bt":"תרמד","bp":"לובלין","b":"תלמיד וחתן ר שמואל וינברג האדמור מסלונים. נסמך מאת: ר אבא רפפורט מקעלץ. היגר לארה\"ב-תרצד וכיהן כאדמור מסלונים בדטרויט. ממיסדי ותומכי ישיבת חכמי לובלין בלובלין ודטרויט."},{"i":18846,"n":"זילבר, נתן נטע מדוסיאט","bp":"דוסיאט","b":"רב בדוסיאט, ובנו ר בונם צמח על מקומו אחריו."},{"i":18847,"n":"זילבר, צבי הירש מסוקולוב","b":"אב\"ד סוקולוב."},{"i":18848,"n":"זילבר, רפאל מארה\"ב","k":"בעל מרפא לנפש","b":"רב בארה\"ב-תשלה."},{"i":18849,"n":"זילבר, שאול משיקגו","bt":"תרמא","dt":"תשו - אלול","b":"רב בשיקאגו-תר\"ע"},{"i":18850,"n":"זילבר, שמואל","b":"פרסם מאמרים ב\"החיים\" - אונגואר תרפב."},{"i":18851,"n":"זילבר, שמואל מזאמושט","b":"רב בזאמושט-תרנו, הסכים על חשק שלמה לר משה שלמה לוינזון.."},{"i":18852,"n":"זילבר, שמעון מגלגוב","b":"רב בגלגוב. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":18853,"n":"זילבר, שמשון מאולינוב","b":"רב באולינוב, בנו ר יחזקאל על מקומו אחריו."},{"i":18854,"n":"זילברבלאס, שמעון מגרוזיה","bp":"בריסק","b":"מלמד תורה בכותאיס-גרוזיה, ולמעשה שימש כרב לא רשמי."},{"i":18855,"n":"זילברברג אברהם בנימין","bt":"1820","dt":"ה'תרלח 1878","bk":[["אמרי מהרא\"ב",""],["דברי אברהם",""],["הדרת מלך",""],["חמדת בנימין",""],["שו\"ת משנת בנימין",""],["מהרא\"ב","שו\"ת"]]},{"i":18856,"n":"זילברברג, אברהם בנימין מארה\"ב","f":"מיכאל משה יהודה-זכרו","k":"בעל שות מהרא\"ב","r":"רב בפיטסבורג","bt":"תרמב","bp":"וידושוב-פלך קאליש","dt":"יוה\"כ תשכג","b":"תלמיד ר אברהם יצחק הלוי מזאגראוי, ישיבות לומזה, ראדין. נסמך מאת: האדמור מאוסטרובצא, ר שאול זילברמן מויערושוב, ר רפאל מאיר דן פלוצקי. חתן דודו ר אפרים שרגא לונטל מאיניאווע. רב בטולישקוב-תרעז ויסד שם ישיבת \"תורת אמת\" בראשות ר\"א ליפמן לעוי מקוואהל, ר ראובן-חתן ר יוסף הורוביץ מנוברדוק, מו\"צ בוארשא-תרפד, היגר לארה\"ב וכיהן כרב בפיטסבורג-ארה\"ב-תרצח. חיבר גם \"אמרי מהרא\"ב\"-נ\"י תשה, \"הדרת מלך\" נ\"י תשה, \"זכרון אברהם\". גיסו - ר ישכר בער מדאברי בנו של ר מאיר צבי בעל אמרי הצבי.","bk":[["אמרי מהרא\"ב",""],["הדרת מלך",""],["זכרון אברהם",""],["משנת בנימין – שו\"ת",""],["שו\"ת מהרא\"ב",""]]},{"i":18857,"n":"זילברברג, אברהם בנימין מוערשוב","f":"משה יהודה","b":"רב בוויערשוב-תר\"ל"},{"i":18858,"n":"זילברברג, אהרן זלמן מאושפיצין","b":"תלמיד בישיבת \"כתר תורה\" באושפיצין-תרצט. \"כתר תורה\" - אושפיצין תרצט."},{"i":18859,"n":"זילברברג, אליהו מפלעשען","bt":"תקצט","bp":"סעמניץ","dt":"תרמח - יז כסלו","b":"תלמיד הכת\"ס, ור יהודה אסאד. חתן ר יעקב שלום סופר מטפלטשאן. רב בגינז-תרכח, פלעשען-תרלג."},{"i":18860,"n":"זילברברג, חיים יעקב נפתלי","f":"אברהם בנימין","k":"בעל דרכי חיים","bt":"תרי","dt":"תרצ - יג אדר","b":"נכד בעל \"זית רענן\". מו\"צ בוארשא. ביקר בארץ-תרעב. מקורב לאדמו\"ר מטשכנוב, לשפת אמת, נסע אל ר ישראל סלנטר, ידידו של ה\"חפץ חיים\". מתורתו נדפס גם \"ענפי זית\".","bk":[["דרכי חיים",""],["ענפי זית",""],["ענפי זית, שבועות",""]]},{"i":18861,"n":"זילברברג, יהודה ליב מגרודזיסק","b":"תלמיד רמ\"י מאוסטרובצה ור\"ש אנגל. חסיד מרקישוב."},{"i":18862,"n":"זילברברג, יואל זליג מוארשא","b":"מחכמי וארשא, חתם שמו על שער ספר-תרנו, (כנראה קרובו של ר יעקב חיים נפתלי - שחותמתו נמצאת על גם היא על הספר)."},{"i":18863,"n":"זילברברג, יוסף","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":18864,"n":"זילברברג, יוסף משה מטיניע","b":"רב בטיניע-תרלו. השתתף באספת הרבנים במיהאלביץ-תרכו."},{"i":18865,"n":"זילברברג, יצחק יוסף מקראסנשילץ","f":"משה מיכאל יהודה","k":"בעל ויען יוסף","bt":"תרס - בערך","dt":"תש..","b":"חתן ר מאיר דן פלוצקי בעל \"כלי חמדה\". אב\"ד קראסנאשילץ. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"התפוח\" - בנדין תרפח. נספה בשואה. מחיבוריו נדפס גם \"עלהו רענן\", עצי זית\"."},{"i":18866,"n":"זילברברג, מיכאל משה יהודה מויר","f":"חיים יעקב נפתלי","k":"בעל זכרון משה","dt":"תשא - ט כסלו","b":"מצאצאי רח\"י נפתלי מוארשא, בעל \"זית רענן\" מקוטנא. מו\"צ בויערושוב, לודז."},{"i":18867,"n":"זילברברג, משה יהודה ליב-רמי\"ל","f":"בנימין בייניש","k":"בעל זית רענן","r":"אב\"ד קוטנא","bp":"לונטשיץ","dt":"תרכה - ג שבט","dp":"ירושלים","b":"רב בקובל(=קוואהל), שעפס, דאברי, לאסק-תקצח על מקום ר זאב וולף הכהן וראש ישיבה שם (הרב המתנגד האחרון בלאסק) ור דוד דב מייזלש על מקומו אחריו, קוטנא, עלה לירושלים בשנת תריז לאחר שהעביר את הרבנות לבנו. היה מנשיאי ישיבת \"עץ חיים\". בשנת תריט חתם על הסכמה בין העדות בענין החזקות. פרסם מאמרים ב\"תורת ציון\" - ירושלים תרכב - המאסף התורני הראשון בירושלים, ב\"כבוד הלבנון\" - ירושלים תרכג. חיבר \"זית רענן\" ורשה תריא, ועוד. מתלמידיו - ר יהושע צבי מיכל, ר צבי מיכל שפירא, ר ישעיה אורנשטין, ר יהודה בלומנפלד, ר יהודה הכהן, ר נסים שרלין. מתלמידיו בלאסק - ר שמואל זנויל קלפפיש מוארשא, ר משה פרלמוטר מלודז, ר ליפמן ליטמנוביץ מרדומסק. בנו - ר אברהם בנימין-אביו של ר חיים יעקב נפתלי מוארשא, חתנו - ר ישראל יעקב הלוי מפלונסק.","bk":[["זית רענן - שו\"ת",""]]},{"i":18868,"n":"זילברג, משה","f":"הלל","k":"בעל המעמד האישי","bt":"1900","bp":"שקודוויל-ליטא","b":"תלמידי ישיבת מיר, סלובודוקה, נוברדוק. למד פילוספיה ומשפטים. עלה לארץ והיה מרצה לתלמוד ב\"אהל שם\". שופט בבית המשפט העליון. פרסם מאמרים בנושאים שונים."},{"i":18869,"n":"זילברט, אליהו משה מלויקעווע","f":"מרדכי","bt":"תרכט","b":"רב בליקעווע(=לויקעווע)-פלך קובנא-תרסב."},{"i":18870,"n":"זילברט, יהודה מנובוגרד","f":"אפרים","k":"בעל תושע יהודה","bt":"תרכ","b":"תלמיד ר יחזקאל אליעזר מואקשנא, ר משה חריף מואקשנא, ר הלל ליפשיץ מלובלין, כולל קובנא. רב בנובגורק(=נאווגאראד, נובוגרד)-תרמח. נסמך מאת: ר משה דונשבסקי, ר יצחק אלחנן מקובנא."},{"i":18871,"n":"זילברמינץ, ישראל הלוי מקוזמיר","b":"פרסם מאמרים ב\"הכרם\" - וארשא תרצא, \"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":18872,"n":"זילברמיץ, חיים יהודה ליב הלוי","k":"בעל חיל וחוסן","bt":"תקצה","dt":"תרעו - יט סיון","b":"חסיד ר מרדכי יוסף מאיזביצא, ר יהודה ליב איגר מלובלין. רב בשענא-תלב, קוזמיר-תרלז."},{"i":18873,"n":"זילברמן, אברהם ליב","k":"בעל לב אברהם","b":"נכד ר רפאל זילברמן-רבה של צפת. ראב\"ד בצפת-תרפח. פרסם מאמרים ב\"תבונה\" - ירושלים תשא. ?? לא באוצר ??"},{"i":18874,"n":"זילברמן, אברהם ליב","f":"רפאל זילברמן","bt":"תרנ","dt":"תשח - טו חשון","b":"רב ראשי בטבריה"},{"i":18875,"n":"זילברמן, אליעזר ליפמן","f":"יהודה ליב","k":"בעל המגיד","bt":"1819","bp":"ראסיין-ליטא","dt":"תרמב - כד אדר","b":"למד בנארוד, קארטינגא. התישב בליק והיה גם שו\"ב. ייסד את \"המגיד\" בליק-1856, והיה ממיסדי העתונות העברית המודרנית (כתב העת השבועי הראשון בעברית). מיסד חברת \"מקיצי נרדמים\" עם דוד גורדון. הו\"ל \"פחד יצחק\" לר יצחק למפרונטי, ועוד."},{"i":18876,"n":"זילברמן, אליעזר מטרנוב","b":"מחכמי טרנוב-תרסא. פרסם ב\"אהל מועד\"."},{"i":18877,"n":"זילברמן, אלתר מארה\"ב","bp":"ירושלים","b":"חזן ושו\"ב בניו יורק."},{"i":18878,"n":"זילברמן, אלתר מניו יורק","bp":"ירושלים","b":"חזן ושו\"ב בניו יורק."},{"i":18879,"n":"זילברמן, גרשון יהודה","dt":"תרצח","dp":"ירושלים","b":"רב בפרגה (וארשא), עלה לארץ תרפד והיה חבר בית הדין"},{"i":18880,"n":"זילברמן, חיים מרדכי","k":"בעל דברי מרדכי","b":"ראב\"ד בפלאצק-תר\"מ. ?? לא באוצר ??"},{"i":18881,"n":"זילברמן, חיים שלמה מארה\"ב","f":"יעקב","k":"בעל שולחן שבת","b":"רב בהאזלטון-ארה\"ב, חיבר גם \"אור יעקב\"."},{"i":18882,"n":"זילברמן, חנניה מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":18883,"n":"זילברמן, יהודה ליב מפוגאראש","b":"רבה הראשון של פוגאראש וכיהן כ-50 שנה. ועל מקומו אחריו \"הפרעדיגער יוזף כהנא\" - ור וולף רוזנבלי מדיטשא סט מארטון פנה אל ראשי הקהל - בעתון \"שבת אחים\" תרלב - ושאל \"מה עשיתם? הזה ימלא מקום היקר והנכבד ר יהודה ליב... הסירו מעליכם את אלהי הנכר\". ניהל את פנקס הקהלה."},{"i":18884,"n":"זילברמן, יוסף מניו יורק","bt":"1860","bp":"סינסינטי","b":"תלמיד ביהמ\"ד בסינסינטי. כיהן כרב ריפורמי בערים שונות ואח\"כ רב \"עמנואל\" בניו יורק. כיהן כנשיא ועד רבני אמריקה. חיבר מאמרים באנגלית."},{"i":18885,"n":"זילברמן, יעקב מיוזעפוף","b":"רב ביוזעפוף"},{"i":18886,"n":"זילברמן, יעקב מירושלים","f":"שמואל מוני","bp":"ירושלים","b":"שו\"ב בירושלים."},{"i":18887,"n":"זילברמן, יעקב מפרשוב","b":"מחכמי פרשוב. חתניו - ר מאיר צבי יונג מלונדון, ור משה דוד גרוס מלוצרן - תל אביב."},{"i":18888,"n":"זילברמן, יעקב פרץ","b":"רב ביאנושי-תר\"י"},{"i":18889,"n":"זילברמן, יצחק מבילגוריי","dt":"תשג","b":"רב בבילגוריי"},{"i":18890,"n":"זילברמן, יצחק מדמביץ","b":"רב בדמביץ-תרל. חתנו ר יהודה אריה לויפבן על מקומו אחריו."},{"i":18891,"n":"זילברמן, יצחק משה מטולידו-אורי","dt":"תרצד - יא אייר","b":"רב בטולידו-אורייא"},{"i":18892,"n":"זילברמן, יקותיאל","b":"הביא לדפוס קונטרס על יחוס משפחת ואהל - \"גזע ישי\" למברג תרטו (והוא השלמה לספר \"גדולת שאול\"."},{"i":18893,"n":"זילברמן, ישראל יצחק מירושלים","k":"בעל קרן ישי","b":"מו\"צ בירושלים-ת\"ש. פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפו, \"ועד חכמים\" - ירושלים תרפג, \"שערי ציון\" - ירושלים תרפא. ?? לא באוצר ??"},{"i":18894,"n":"זילברמן, מאיר מרדכי מיאלוק","b":"רב ביאלוק לצד ר שמואל יעקב רבינוביץ."},{"i":18895,"n":"זילברמן, מרדכי מאומן","bt":"תקעט","bp":"אומן","dt":"תרלב","dp":"טבריה","b":"רבה של אומן לאחר חותנו ר אברהם ליב, עלה לצפת בשנת תרי, ונתמנה לרב העדה האשכנזית. בנו ר רפאל ונכדו ר אברהם ליב כיהנו אחריו כרבני צפת."},{"i":18896,"n":"זילברמן, מרדכי מאיר ממאטעלא","f":"ישראל משה","k":"בעל מאירת מרדכי-כת\"י","bt":"תרכה","b":"תלמיד ישיבות סלובודקא, טלז. חתן ר יוסף זכריה וולפוביץ. רב בלייפין-תרנב, איגנאלינע, הריעסק, מו\"צ במינסק-תרסה, רב במאטעלע-פלך גרודנא-תרע. נסמך מאת ר יצחק אלחנן מקובנא, ועוד."},{"i":18897,"n":"זילברמן, מרדכי מאיר מנ\"י","dt":"תשיד - ו תשרי","b":"רב בניו יורק"},{"i":18898,"n":"זילברמן, משה הלוי מראצפרט","f":"נפתלי הירצקא זילברמן","b":"רב בראצפרט-תרפ."},{"i":18899,"n":"זילברמן, משה מירושלים","f":"שמואל","k":"ירושלים","bp":"ירושלים","dp":"תרע - ז תמוז","b":"מורה בת\"ת עץ חיים בירושלים."},{"i":18900,"n":"זילברמן, נפתלי הירצקא מרצפערט","f":"יעקב פרץ הלוי","bt":"תקפ","dt":"תרנח - ט תשרי","b":"תלמיד הדברי חיים מצאנז. רב ביאנושי, רצפערט(=ראצפרט), וכיהן כאדמור עממי בהונגריה. מתורתו ולזכרו ב\"זכרון נפתלי\". בניו ר משה ור יעקב פרץ. חתנו ר יעקב הלוי מיאנשי."},{"i":18901,"n":"זילברמן, רפאל מטבריה","b":"רב בטבריה-תר\"ס. בנו ר אברהם ליב רב ראשי בטבריה."},{"i":18902,"n":"זילברמן, רפאל מצפת","f":"מרדכי","bt":"תקצט או תרא","bp":"אומן","dt":"תרעח","dp":"צפת","b":"אביו היה רבה של אומן, עלה עם משפחתו לצפת ואביו התמנה לרב שם. בשנת תרלב נתמנה לרב על מקום אביו. הוציא לאור \"זבחי שלמים\" לר משה קורדוברו."},{"i":18903,"n":"זילברמן, שאול משה מוירשוב","f":"יצחק אייזיק אלימלך","k":"בעל חדושי שאול משה","r":"אבד\"ק קויז'מינקא, וויערשוב, ואח\"כ רב בלודז', ותל אביב","bt":"תרט-יב","bp":"טודיק","dt":"תרצט","dp":"תל אביב","b":"מחכמי פולין, למד אצל גדולי החסידות, ובהם ה\"אבני נזר\" והגאון מקוטנא. ראב\"ד בקוזמינקה-פלך קאליש-תרמב, ויערושוב, רב ור\"מ בדיארט(=דוואהרט) - הישיבה נקראה ישיבת ר שאול דוואהרטר, וירשוב(=ויערשוב), וכן אב\"ד בלודז. בשנת תרפז עלה לתל אביב ושימש כרב. חיבר \"חידושי שאול משה\" תל אביב תשל, \"פרדס שאול\" תל אביב תשה ועוד. פרסם מאמרים ב\"קול תורה\" - פאביאניץ תרפו.","bk":[["אבני שהם - מועד, רמב\"ם שבת, ושו\"ע עירובין",""],["חידושי רבי שאול משה - בבא מציעא",""],["פרדס שאול - על התורה",""],["שאלות ותשובות רבי שאול משה",""]]},{"i":18904,"n":"זילברמן, שמאי מבוקובסק","b":"רב בבוקובסק."},{"i":18905,"n":"זילברמן, שמואל (שלמה מוני)","f":"אברהם יצחק","bt":"תקפד","bp":"פינסק","dt":"תרנד - יד אדר","dp":"ירושלים","b":"עלה לירושלים בילדותו-תקצ\"ב, מחכמי ירושלים, חתנו של ר אורי שבתי דיין. לימד ב\"עץ חיים\", בשנת תריד בשליחות ברוסיה."},{"i":18906,"n":"זילברמן, שמואל שמלקא","f":"יעקב זילברמן","b":"רב בביאליסטוק"},{"i":18907,"n":"זילברמן-מנדלין, זאב וולף מאודס","f":"יעקב ממוהלוב","k":"בעל מקרי העשר","b":"חתן ר אברהם דב איטקין מבוברויסק. מחכמי אודסה."},{"i":18908,"n":"זילברפרב, אהרן מקוידנוב","f":"חנוך הניך דב","k":"אדמור מקוידנוב בת\"א","b":"אדמור מקוידנוב בתל אביב על מקום אביו."},{"i":18909,"n":"זילברפרב, זלמן יוסף","dt":"תשד","b":"רב בטופורוב"},{"i":18910,"n":"זילברפרב, חנוך הניך דב מקוידנו","f":"משלם זלמן יוסף","k":"אדמור מקוידנוב","bt":"תרן-נא","bp":"קוידנוב","dt":"תשלח - ח אב","b":"מקורב לאדמורי בלז - כאביו לפניו. בן האדמור מטופרוב. גדל אצל זקנו ר אהרן פרלוב מקוידנוב. חתן ר מרדכי יוסף משקוביץ מסוליצא (שושלת זלוטשוב), עבר אל חותנו בבוטושאן-תרעו, וכיהן כאדמור מקוידנוב בבוטושאן, עבר לבאהריעוו-בסרביה, בוקרשט. ניצל מהשואה, ואחריה עלה לארץ-תשח והתישב בתל אביב. בנו ר אהרן על מקומו אחריו."},{"i":18911,"n":"זילברפרב, יצחק אהרן","dt":"תשג","b":"רב בוויסאקי"},{"i":18912,"n":"זילברפרב, מרדכי שלמה חיים","f":"משלם זלמן יוסף","bt":"תרס","dt":"תשג","b":"רב בטופורוב לצד אביו. חתן ר אלימלך רובין מ יברוב. נספה בשואה."},{"i":18913,"n":"זילברפרב, משה מרובנה","f":"אליעזר שינצ'ס","b":"חתן ר חנוך הניך מאייר מאלסק. רב ברובנה. בנו ר משולם זלמן יוסף מטופורוב."},{"i":18914,"n":"זילברפרב, משלם זלמן יוסף מטופ","f":"משה","k":"אדמור מטופרוב-גליציה","bt":"תרכט","bp":"רובנא","dt":"תשג","b":"נכד ר חנוך העניך דב מאלסק ותלמידו. חסיד בלז, מקורב לגדולי ליטא. חתן ר אהרן פרלוב האדמור מקוידנוב ועבר לשם. חזר לגליציה וכיהן כרב ואדמור בטופרוב-תרנו. נספה בשואה."},{"i":18915,"n":"זילברפרב, שמואל מלמברג","f":"אריה משה ליב","b":"חניך ישיבות ליטא. אב\"ד שפיקוב, נוברדוק. חתן הרב מברשד. ניצל מהשואה. היה רב בלמברג אחרי השואה. עלה לארץ-תשכז"},{"i":18916,"n":"זילברצן, חיים דוב מלוברנץ","bt":"תרמ","dt":"תרפד - יג אד\"א","b":"רב בלובראניץ(=לוברנץ)-תרס\"ו"},{"i":18917,"n":"זילברצן, ישכר בריש","b":"רב בליברנץ-תר\"ע"},{"i":18918,"n":"זילברקרון, יעקב מפפד\"מ","b":"דיין בפפד\"מ-תקנה."},{"i":18919,"n":"זילברשטין, אברהם יעקב מהולשיץ","f":"נפתלי צבי הירש","bt":"תרי","dt":"תרעה","b":"רב בהולשיץ-תרלה על מקום אביו. חתן רא\"ל הורשובסקי מאוהנוב. בנו ר נפתלי צבי הירש על מקומו אחריו."},{"i":18920,"n":"זילברשטין, אברהם שמואל צבי","k":"בעל שבעה שבועות","bt":"תרמה - בערך","bp":"רדומסק","dt":"תשס","dp":"טורונטו","b":"רב בביגטליין, ויזערבניק, טורונטו-תרפה, עלה לארץ ואחרי שנתיים חזר לטורונטו. חיבר קרנות הזבח\" בילגוריא תרפז, \"שבעה שבועות\" ירושלים תרצח, נפלאות התפארת שלמה\".","bk":[["קרבן שמואל","קדשים-שו\"ת"]]},{"i":18921,"n":"זילברשטין, אהרן מבאלאד","f":"ישעיה","dt":"תשד","b":"רב בקרצקי-תרעא, באלאד-תרפה על מקום ר יואל פלנר (שעבר לאוהל). נספה בשואה."},{"i":18922,"n":"זילברשטין, אהרן מהוד-מאזו","k":"בעל יהודי הוד-מאזו","b":"רבה האחרון של הקהלה הניאולוגית בהוד-מאזו ואשארהאי. חיבר מונוגרפיה לתולדות הקהלה."},{"i":18923,"n":"זילברשטין, אשר מארה\"ב","b":"רב בלוס אנג'לס-תשכב."},{"i":18924,"n":"זילברשטין, אשר ממזריטש","f":"ישראל אהרן ממזריטש","b":"רב במזריטש-ווהלין-תרע על מקום אביו. גיסו - ר ברוך בן ציון ברגובסקי."},{"i":18925,"n":"זילברשטין, דוד אבא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":18926,"n":"זילברשטין, דוד יהודה ליב- הזקן","f":"אהרן ליפמן","k":"בעל שבילי דוד יהודה","bt":"ה 'תקפ","bp":"באניהאד","dt":"תרמד - יד ניסן","dp":"הונגריה","b":"למד בישיבת ר מאיר אש באונגואר, ובישיבת ר קופל חריף בוורבוי, היה דיין באויהעל (=ערלוי) ואחר כך רב בזענטא, טאקע-טערעבעש, זשיסעוו-תרלד, עלה לירושלים, ובשנת תרכב חתם כדיין בירושלים. לאחר מכן רב בכמה עיירות בהונגריה וביניהם בוויצען וראש ישיבה שם, ולצדו בנו ר ישעיה בעל \"מעשי למלך\". חיבר ספר \"יד דוד\" וויצען תרסה. \"שבילי דוד\" ירושלים תרכב ועוד.","bk":[["שבילי דוד [על שו\"ע]",""],["בית דוד - שו\"ע",""],["יד דוד – עה\"ת",""],["שבילי דוד – שו\"ע ותורה וענינים",""]]},{"i":18927,"n":"זילברשטין, דוד יהודה ליב- הנכד","f":"ישעיה מוויצען","k":"בעל יד דוד","bt":"תרמה - בערך","dt":"תשד - תמוז","b":"נכד ר דוד יהודה בעל \"יד דוד\". תלמיד ר שאול בראך, ור מרדכי וינקלר בעל \"לבושי מרדכי\". רב בהעליטשאבא-תרעה, דומ\"ץ בוויצען-תרפח, ורב בוויצען-תרצה על מקום אביו. נספה בשואה. (באוצר ובמורשת רבני הונגריה נזכר שחיבר \"יד דוד\" כשם ספר זקנו ואולי טעות??)."},{"i":18928,"n":"זילברשטין, דוד צבי","b":"ר\"מ בישיבת תורת חסד בלודז, עלה לארץ והיה חבר ברבנות תל אביב."},{"i":18929,"n":"זילברשטין, יהודה ליב מפאגורוש","b":"רב בפאגורוש-תק\"צ"},{"i":18930,"n":"זילברשטין, יוסף","b":"תלמיד ר יעקב הורביץ מדלטין שהשיב לו בשות הריב\"ם."},{"i":18931,"n":"זילברשטין, יעקב מפראגא","bt":"תרמ","dt":"תשא","b":"מצאצאי ר אלימלך מליזנסק, האדמור מלובלין, המגיד מקוזניץ, ועוד. חתן ר יהושע מימון מפראגא. רב בפראגא-וארשא-תרפא, בועד הרבנים בוארשא, רב ביוזעפוף. פרסם מאמרים ב\"אור המאיר\" - וארשא תרצו, \"בית שמואל\" - וארשא תרצו, \"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":18932,"n":"זילברשטין, ישעיה מוויצען","f":"דוד יהודה ליב-שבילי","k":"בעל מעשי למלך","bt":"תריז-ט","bp":"ירושלים","dt":"תרץ","dp":"ווייצן (הונגריה)","b":"בגיל 11 חזר אביו מירושלים להונגריה. היה תלמיד ה\"כתב סופר\", רב בטרבש, וייצען-תרנו על מקום אביו וראש ישיבה כ-45 שנה, ובנו ר דוד יהודה על מקומו אחריו. נחשב לאחד משלושת מנהיגי הדור בהונגריה (יחד עם ר מרדכי ליב וינקלר ממאד ור שמעון גרינפלד מסנמיהאי), מראשי המדברים בלשכה האורטודוכסית בבודפשט. חיבר \"מעשי למלך\" וייצן תרעג, ועוד. בזמן מלחה\"ע ה-I פרסם קול קורא לרבני הונגריה יחד עם ר קופל רייך מבודפשט - שכל היוצא למלחמה יתן לאשתו גט על תנאי למניעת עגינות. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז. נספד ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד. מהמספידים את השב\"ס בהלויה בפרשבורג. פרסם מאמרים בשבח הציונות ב\"תל תלפיות\" אך נאלץ לחזור בו בלחץ מתנגדי הציונות. בנו גם ר אהרן."},{"i":18933,"n":"זילברשטין, ישראל מוויצען","f":"ישעיה מוויצען","b":"רב בוויצען. חתנו ר יצחק יונגרייז ממרטינסברג."},{"i":18934,"n":"זילברשטין, מנחם מנדל מלמברג","f":"שמשון","k":"בעל צדק וארשא","bt":"תקן","bp":"למברג","dt":"תר","b":"חיבר \"צדק וארשא\" קראקא תקפב."},{"i":18935,"n":"זילברשטין, מרדכי מהולשיץ","bt":"תקן","dt":"תרל","b":"רב בהולשיץ-תרכט. חתן ר אריה ליפשיץ בעל \"אריה דבי עילאי\". בנו ר נפתלי צבי הירש על מקומו אחריו."},{"i":18936,"n":"זילברשטין, מרדכי מנחם מנדל","f":"אליהו חיים","bt":"תרל","b":"רב בווארקא-פלך וארשא-תרנג."},{"i":18937,"n":"זילברשטין, משה","k":"מיכאל איוונוב מיכאיל","bt":"1858","bp":"וילנא","b":"משורר אצל חזנים בליטא. החל להופיע באופרה הרוסית. התנצר."},{"i":18938,"n":"זילברשטין, נפתלי מסטניסלב","b":"מחכמי סטניסלב."},{"i":18939,"n":"זילברשטין, נפתלי צבי הירש","f":"מרדכי","bt":"תקף","dt":"תרלה","b":"חתן ר אליהו הורשובסקי מדרוהוביטש. רבה של הולשיץ על מקום אביו. בנו ר אברהם יעקב על מקומו אחריו."},{"i":18940,"n":"זילברשטין, נפתלי צבי הירש מהול","f":"אברהם יעקב מהולשיץ","bt":"תרם","dt":"תרץ","b":"רב בהולשיץ-תרסו על מקום אביו. חתן ר יעקב משה ספרין מקומרנא."},{"i":18941,"n":"זילברשטין, עמנואל","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":18942,"n":"זילברשטין, עמרם מסאניסלוי","f":"אהרן מבעלעד","dt":"תש..","b":"חתן ר נתן אנשיל קרויס מסאניסלוי, וכיהן כרב תחתיו. נספה בשואה."},{"i":18943,"n":"זילברשטין, צבי הירש","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":18944,"n":"זילברשטין, שלום יוסף מארה\"ב","f":"אהרן","k":"בעל הדת והתורה","bt":"תרה","bp":"קובנא","dt":"תרעט","b":"רב בדרשונישוק. היגר לארה\"ב ופרסם מחקרים בפילוסופיה ודת. חיבר גם \"מציאות ה' והעולם\" נ\"י תרנג."},{"i":18945,"n":"זילברשטין, שלמה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":18946,"n":"זילברשטין, שלמה מגרוסורדין","f":"אהרן","k":"בעל אהל שלמה-תרפח","bt":"תקעד","bp":"באניהאד","dt":"תרסט - ט טבת","dp":"גרוסורדין","b":"אחיו של ר דוד ליב מוייצען בעל \"שבילי דוד\" ושניהם מתלמידי ר קופל חריף מוורבוי. חתן ר שלמה וייל מבאניהאד. רב בשארקאד-תריג, עבר בגלל המתקנים בקהלה לגרוסורדין. וייצען-תרמא."},{"i":18947,"n":"זילברשטין, שמואל מבאניהאד","b":"תלמיד הגאון מבאייה. דיין בבאניהאד."},{"i":18948,"n":"זילברשטין, שמואל מקאסטופול","f":"אשר","bt":"תרך","dt":"תרצב","b":"רב בקאסטאפאליא-ווהלין-תרמד. בנו - נתן - נהרג עק\"ה בידי פורעים ערבים בירושלים תרצח."},{"i":18949,"n":"זילברשטין, שמואל צבי מבנדין","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":18950,"n":"זילברשטין, שמואל צבי מויזרבניק","f":"ראה: אברהם שמואל צבי"},{"i":18951,"n":"זילברשטין, שמחה דב מפראן","b":"רב בפראן, אורלה."},{"i":18952,"n":"זילברשטרום, אליהו פרץ מבריסק","b":"מתורתו ב\"בית שמואל\" - וארשא תרצו (מתוך כת\"י)."},{"i":18953,"n":"זילברשיץ, חיים משה מזלוטשוב","f":"שמואל","k":"בעל משנה ברורה למשנה","bt":"תרל","bp":"זלוטשוב","dt":"תשיד","b":"מחכמי זלוטשוב-תרכה. פרסם בכתבי עת שונים. עלה לארץ-תרצו והתישב בחיפה. חיבר \"משנה ברורה על המשניות\" זלטשוב תרפב. פרסם מאמרים ב\"הנצח\" - לבוב תרפז."},{"i":18954,"n":"זיליאר, אלתר יהודה","dt":"תשד","b":"רב בלולינץ"},{"i":18955,"n":"זילפן, פיביש מפשמישל","f":"אפרים מזלין","bt":"תרלג","dt":"תרצו","b":"חתן ר יעקב שלמה הכהן פרידמן מפשמישל."},{"i":18956,"n":"זימן, יוסף מתל אביב","f":"זאב","k":"בעל עם נחלת יצחק","bt":"1882","bp":"פיליפובה-פלך סובאלק","b":"תלמיד ישיבת סלובודקה, טלז. ממיסדי שכונת נחלת יצחק בתל אביב (ע\"ש ר יצחק אלחנן ספקטור). עלה לארץ-1925, יו\"ר איגוד יוצאי ליטא. חיבר \"עם נחלת יצחק בראשיתה\"-תשז."},{"i":18957,"n":"זימנסון, מאיר מקאנדאוי","bp":"קורלנד","dt":"תרמג","b":"רב בקאנדאוי-תרא כ-40 שנה, יחד עמו כיהן ר מרדכי שטרן שעלה לארץ."},{"i":18958,"n":"זין, ישועה מקושטא","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":18959,"n":"זינגיל, מאיר ממינקביץ","k":"בעל אמרי טעם","b":"אב\"ד מינקביץ-פלך פודוליה. חיבר שו\"ת \"אמרי טעם\" וארשא תרסב."},{"i":18960,"n":"זינגמן, קלמן","k":"בעל די יונגע אידישע","bt":"1880","bp":"סלובודקה","dt":"1929","dp":"סימפרופול","b":"יסד בחרקוב-1917 הוצאת הספרים \"אידיש\" והו\"ל יצירות סופרי אידיש ברוסיה, עבר לקובנא. חיבר שירים וספרים באידיש."},{"i":18961,"n":"זינגר, אברהם דב ממדערן","bt":"תקצד","bp":"מיהאלפלווא","dt":"תרסה - יח אלול","b":"תלמיד הכת\"ס, ור אברהם יצחק וינברגר מקליינורדין. מחכמי פעזינג, רב במאדערן(=מודרן)-תרלו."},{"i":18962,"n":"זינגר, אברהם יעקב קאפל מלאשנץ","f":"אשר מפאקש","bp":"פאקש","dt":"תרכו-ז","dp":"גלייכנברג","b":"תלמיד החת\"ס והכתב סופר. רב באדראג-קערעסטור-תרז, לאשאנץ-תריח - והיה במחלוקת עם המהרסים, נסע לגליינכברג. תשובה אליו ב\"כתב סופר\"."},{"i":18963,"n":"זינגר, אברהם יעקב קופל מסמרין","f":"ישאל מפרשבורג","bt":"תרמח","bp":"פרשבורג","dt":"תשד - כז סיון","dp":"אושוויץ","b":"נכדו של ר אברהם יעקב קופל מלאשאנץ. תלמיד הדעת סופר, ור יוסף צבי דושינסקי. חתן ר אברהם גרינבורג מקעזזמארק. רב בקעזמארק-תרעד, סעמערין-תרצג. נספה בשואה."},{"i":18964,"n":"זינגר, אברהם מבקשביץ","f":"דוד צבי","k":"אדמור מבקשביץ","bt":"תרם","dt":"תש","b":"רב ואדמור בבקשביץ. חתן ר ישעיה גוטליב מזלוטניק."},{"i":18965,"n":"זינגר, אברהם מואר-פאלטא","f":"פסח מקירכדורף","k":"בעל המדריך","bt":"תרט או תרכב","dt":"תרעד - ו טבת","b":"רב בקירכדורף-תרלג, קהילת סטטוס-קוו בואר-פאלאטא ובנו ר יהודה ליב על מקומו אחריו. חיבר ספר על תולדות יהודי הונגריה ועל תנועת התיקונים בדת. השתתף באסיפת הרבנים בקראקא-תרסד בדבר חזוק הדת ומכתב ממנו בענין - ב\"כנסת הגדולה\" להרא\"מ הכהן. חתניו - ר ברכיה שיק מטימישואר, ר בצלאל פישר מטרנטשין, ור ראובן גליק מואראזשדין. ?? לא באוצר ??"},{"i":18966,"n":"זינגר, אברהם מוארשא","k":"בעל בלי תקומה","bt":"תרכד","bp":"קאפיל-פלך מינסק","b":"תלמיד דודו ר יצחק פורטני, ישיבת ד\"צ קצנלסון, ישיבות סלוצק, ניעשויז, מיר. פרסם מאמרים וספורים ב\"האסיף\", \"כנסת הגדולה\", \"המליץ\". חיבר \"בלי תקומה\" - תרסג."},{"i":18967,"n":"זינגר, אברהם מקשוינז","b":"אב\"ד קשוינז. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":18968,"n":"זינגר, אהרן יעקב מלונדון","b":"פרסם מאמרים ב\"אור תורה\" - לונדון תרצד, \"המסילה\" - לונדון תשז."},{"i":18969,"n":"זינגר, אהרן ממטרסדורף","f":"יצחק","k":"בעל תפארת אהרן","r":"רב ור\"מ במטרסדורף","bt":"תקסו","bp":"סענט-גרוד","dt":"תרכט - יב חשון","dp":"ניידרפל","b":"גדל אצל דודו - ר אליעזר ליפשיץ ממטרסדורף. תלמיד החת\"ס. חתן ר מנדל דייטש ממטרסדורף. רב במטרסדורף-תקצח וראש ישיבה. חיבר \"תפארת אהרן\". תשובות אליו ב\"כתב סופר\" ו\"מכתב סופר\". ?? לא באוצר ??","bk":[["תפארת אהרן - חידושים בסוגיות הש\"ס",""]]},{"i":18970,"n":"זינגר, אליהו מסטוטשין","f":"יעקב ויינריב","k":"בעל גנזי אליהו","bt":"תריג","dt":"תרנג","b":"תלמיד רש\"ד אונגר מזבנא ורצ\"א שפירא מבלוזוב. חתן ר ישכר דב ברל פאוסט. רב בסטוטשין. שינו את שם משפחתם אחרי שברחו מהרוסים. חיבר \"גנזי אליהו\" ניו יורק תשנז."},{"i":18971,"n":"זינגר, אליהו מסטוטשין","f":"שמעון","bt":"תרנו","bp":"סטוטשין","dt":"תשד - יח חשון","b":"תלמיד המהרשם מברזאן וסייע לו בהוצאת ספרו. נסמך מאת: מהרש\"ם מבראזן, ר מאיר אריק מטורנא, ר שמואל אנגל מרדומישל, ר טבלי זעהמאן מדוקלא, ר נחום וידנפלד מדומברובא. חתן ר ברל פאוסט מטורנא. רב בלודמיר-צ'כיה - תרעט. עבר לארה\"ב-תרפג ושימש כרב בנוארק."},{"i":18972,"n":"זינגר, אליהו מפשיסחא","b":"רב בפשיסחא,אושיוקוב,ברזניצא,ראב\"ד בקאליש"},{"i":18973,"n":"זינגר, אלימלך הכהן","k":"בעל זכרון אלימלך","b":"רב בסוסנובצה"},{"i":18974,"n":"זינגר, אליעזר יקותיאל מברוד","f":"יעקב מודיל","k":"א' ברמ\"ז","bt":"תקסז","bp":"ברודי","dt":"תרל","b":"רב בניקלשבורג-תרי. חיבר \"תורת הרמה\" למברג תרו."},{"i":18975,"n":"זינגר, אלעזר מלודז","b":"פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":18976,"n":"זינגר, אלעזר מרימסאמבאט","f":"שלמה יהודה ליב","bt":"תרמח","bp":"רימסאמבאט","dt":"תשד - כג סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יוסף ליב סופר מפאקש. חתן ר עמרם פישר מיינק. רב בויינערן-תרעב, רימאסאמבאט-תרעג על מקום אביו. נספה בשואה. בנו - ר שלמה יהודה ליב מראזשנוי."},{"i":18977,"n":"זינגר, בנימין זאב מסט מיקלוש","f":"פסח מקירכדורף","bt":"תריח","b":"רב בליפטוי-סט-מיקלוש-תרמג. פרסם מאמרים בכתבי עת ומאספים."},{"i":18978,"n":"זינגר, גרשון","dt":"תשד","b":"רב בפרעשוב"},{"i":18979,"n":"זינגר, דוד מטרנוב","f":"אליהו","bt":"תרפא","bp":"טרנוב","dt":"תשנד","b":"חסיד בלוזוב. עבר לארה\"ב-תרף עם הוריו. חניך ישיבות ניו יורק ורב שם."},{"i":18980,"n":"זינגר, דוד מפילזנא","f":"בנימין","bt":"תרלח","dt":"תרפב","dp":"קאשוי","b":"רב בפילזנא-תרנח, דיין בקאשוי. חתן נכדת הנודע ביהודה. למד עם רד\"ד מייזלש. חתן ר גרשון אדלר מפולזנא, רב בפולזנא על מקום חותנו. עבר לוינה ולקאשוי."},{"i":18981,"n":"זינגר, דוד מפרשבורג","b":"מג\"מ בפרשבורג בחברה \"אגודת רעים\"-נוסדה תרסד."},{"i":18982,"n":"זינגר, זאב מליטוביסק","f":"דוד צבי","k":"בעל מספד תמרורים","bt":"תרמה","bp":"בקשביץ","dt":"תרפג","b":"מחכמי ליטוביסק. חתן ר יעקב קופל מרילוס מליטוביסק. עבר לארה\"ב-תרפב. חיבר \"מספד תמרורים\" למברג תרעא. ?? לא באוצר ??"},{"i":18983,"n":"זינגר, חיים אלעזר","f":"אליהו זינגר","dt":"תשג","dp":"לודז","b":"חתן אחיו ר יצחק מאיר מאלכסנדר. דומ\"צ בלודז. נספה בשואה."},{"i":18984,"n":"זינגר, חיים שלמה יהודה ליב","f":"פסח מקירכסדורף","k":"בעל חובת הלבבות","bt":"תריח","bp":"וואר-פאלאטא","dt":"תרעג - כה כסלו","dp":"רימא סאמבאט","b":"תלמיד השב\"ס, ור ירמיה לעוו באויהל. חתן ר שמואל קליין מפוטנאק. רב ברימא-סאמבאט-תרמב ובנו ר אלעזר על מקומו אחריו. פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":18985,"n":"זינגר, יהודה דב מגבעת שמואל","f":"יעקב יוסף ממאראש","k":"בעל זיו המצות","dt":"תשלא - יט שבט","b":"תלמיד הדעת סופר, ור מנחם סופר ממאראש-ואשארהעלי. חתן ר מרדכי קאהן מבודפשט. רב ומלמד בבודפשט, עלה לארץ וכיהן כרב בברית מאיר ובגבעת שמואל, בנו ר יעקב יוסף על מקומו אחריו. חיבר \"זיו השבת\", \"זיו המצות\" ועוד."},{"i":18986,"n":"זינגר, יהודה ליב מוארפלאטא","f":"אברהם מוארפלאטא","dt":"תשד","b":"תלמיד הדעת סופר. רב בבאלאש-יארמוט, קהילת סטטוס-קוו בואר-פאלאטא-תרעד על מקום אביו. חיבר ספר על תולדות קהילת ואר-פאלטא. תרגם להונגרית את תהלים ואת קיצור שו\"ע. נספה בשואה."},{"i":18987,"n":"זינגר, יהושע השל מבאפלו-נ\"י","k":"בעל זכרון בספר","b":"רב בבאפלו-ניו יורק. חיבר \"זכרון בספר\" וילנא תרס."},{"i":18988,"n":"זינגר, יוסף יצחק מאיר מאלכסנדר","f":"יחיאל מנחם מאלכסנדר","k":"אדמור מאלכסנדר נ\"י","b":"אדמור מאלכסנדר בניו יורק."},{"i":18989,"n":"זינגר, יוסף מדרוהוביטש","f":"צבי הלוי","k":"בעל שארית יוסף","bt":"תקצא","dt":"תרמז","b":"מחכמי דרוהוביטש. חיבר \"שארית יוסף\" דרוהוביטש תרמט."},{"i":18990,"n":"זינגר, יזאב מליטוביסק","f":"דוד צבי מבקשביץ","b":"חתן ר יעקב קופל מרילוס מליוביסק. מקורב לר אורי מסמבור."},{"i":18991,"n":"זינגר, יחזקאל מוילנא","f":"משה","k":"בעל דרושי יחזקאל","b":"רב ומגיד בקלויז היסוד בוילנא. חיבר גם \"דברי יחזקאל\"."},{"i":18992,"n":"זינגר, יחיאל מנחם מאלכסנדר ואו","f":"יעקב שרגא פיבל מאוסט","k":"אדמור מאלכסנדר בנ\"י","bt":"תרעט","dt":"תשמט - ו חשון","b":"אב\"ד אוסטרוב. נכד ר יצחק מאיר מאלכסנדר-חתנו של ר שמואל צבי דנציגר מאלכסנדר. ניצל מהשואה והיה השריד היחיד לזקנו ר שמואל צבי האדמור מאלכסנדר, רוב ימיו סירב לאדמורות ולבסוף כיהן כאדמור מאלכסנדר בארה\"ב ובני ברק. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":18993,"n":"זינגר, יעקב","f":"יצחק","bp":"רישא","dt":"תש..","b":"חסיד בובוב. גדל אצל זקנו ר שמעון מדומברובה. תלמיד ר נחום ויינפלד בעל \"חזון נחום\" - תשובה אליו בספרו. חתן ר צבי דיאמנד מקולבסוב. נספה בשואה."},{"i":18994,"n":"זינגר, יעקב יוסף ממאראש-ואשרהל","b":"חתן ר משה שמעון מפרוינקירכן. מזכיר הקהלה במאראש-ואשארהעלי."},{"i":18995,"n":"זינגר, יעקב מטימשואר","dt":"תש","dp":"טימשואר","b":"רבה הניאולוגי של טימשואר-תרנז-תש. פרסם מחקרים במדעי היהדות, ועל רבני טימשואר."},{"i":18996,"n":"זינגר, יעקב מסמרין","dt":"תשד","b":"מג\"מ בפרשבורג-תרסד, רב בסמריין(=סאמורין)."},{"i":18997,"n":"זינגר, יעקב מרישא","b":"רב ברישא. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":18998,"n":"זינגר, יעקב שרגא פיבל מאוסטרוב","f":"יצחק מאיר מאלכסנדר","bt":"תרנט","bp":"אלכסנדר","b":"תלמיד זקנו ר אליהו מקאליש. חתן ר יוסף קאליש האדמור מאמשינוב. רב באוסטרוב-מאז-תרץ, בזמן השואה ברח לסלונים. נספה בשואה. בנו (היחיד ששרד) - ר יחיאל מנחם מניו יורק."},{"i":18999,"n":"זינגר, יצחק אליעזר ממדלינג","f":"אהרן ממטרסדורף","bt":"תרה","bp":"מטרסדורף","b":"תלמיד הכת\"ס. מחכמי מעדלינג (ליד וינה). העלה בכת\"י מתורת רבו."},{"i":19000,"n":"זינגר, יצחק מאיר מאלכסנדר","f":"אליהו מברזניצא","dt":"תשג","b":"חתן האדמור מאלכסנדר ר שמואל צבי דנציגר. אב\"ד באלכסנדר-תרע. נספה בשואה. פרסם הספד לבן האדמור ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":19001,"n":"זינגר, יצחק מפרמישלא","b":"מחכמי פרמישלא - תשובה אליו ב\"האלף לך שלמה\"."},{"i":19002,"n":"זינגר, ישראל","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":19003,"n":"זינגר, ישראל מפרשבורג","f":"אברהם יעקב קופל","b":"חתן ר שמואל הכהן עהרנרטיא מפרשבורג. אביו של ר אברהם יעקב קופל מסמערין."},{"i":19004,"n":"זינגר, מנחם הניך משאוולאן","f":"אהרן אליהו","k":"בעל לוית חן","bp":"קמניץ-ליטאווסק","b":"תלמיד ר שמעון שקופ, ר רפאל שפירא, ר יצחק יעקב מפוניבז, ר חיים סולוביציק. נסמך מאת: ר רפאל שפירא, ר שמעון שקופ, ר אליהו פינשטיין. רב בשאוולאן-ליטא, ואסילארק-פלך ניזנע, היגר לארה\"ב וכיהן כרב בלוס-אנגלס-תשז. חיבר \"לוית חן\". חבר אגודת הרבנים באמריקה."},{"i":19005,"n":"זינגר, מרדכי מקראקא","dt":"שלו - יט טבת","b":"רב בקראקא."},{"i":19006,"n":"זינגר, משה מאטיניא","b":"מחכמי אטיניא(=אטוניא)."},{"i":19007,"n":"זינגר, משה מדזיקוב","f":"פנחס מנחם מנדל הכהן","bt":"תרן","dt":"תשב","b":"רבה של דזיקוב-תרץ על מקום אביו. נספה בשואה."},{"i":19008,"n":"זינגר, משה מפילזנא","f":"דוד","bt":"תרע","bp":"פילזנא","b":"מצאצאי בעל \"נודע ביהודה\". תלמיד ישיבת טרנוב, נסמך מאת: ר\"ש אנגל מרדזמישל. אב\"ד פילזנא-גליציה-תרצח, עבר לארה\"ב-תרצט."},{"i":19009,"n":"זינגר, משה פנחס מסטרי","dt":"תשג","b":"רב בסטארי-דזיקוב"},{"i":19010,"n":"זינגר, נפתלי הרץ מסטוטשין","b":"הדיין הראשון בסטוטשין, בנו ר חיים על מקומו אחריו, ובנו ר אליהו על מקומו אחריו."},{"i":19011,"n":"זינגר, פנחס מאיפלשג","f":"שבתי באשאץ","dp":"ירושלים","b":"רב באיפאלשאג. עלה לירושלים."},{"i":19012,"n":"זינגר, פנחס מנחם מנדל מדזיקוב","f":"שמואל הכהן","k":"בעל מגדים חדשים","bt":"תרלב","bp":"טומשוב","dt":"תשב","b":"חתן ר יעקב מרדכי זילברמן מבילגורי. רב בלענטשין-תרנו, ר\"מ ברדזימין, רב בוארשא-תרע, בילגורי, דזיקוב-תרפו. חיבר \"מגדים חדשים\" פיעטרקוב תרע."},{"i":19013,"n":"זינגר, פסח מקירכדורף","k":"בעל נקודת פז","bt":"תקעו","dt":"תרנח - יד ניסן","b":"רב בפאלאטא-תרו, קירכדורף-תרלא. חתן ר אהרן יוסף שמואל מטרנטשין."},{"i":19014,"n":"זינגר, ראובן רז'ו מרימה סומבוט","b":"רבה האחרון של רימה סומבוט. בנו ר עקיבא - עלה לארץ והתישב בתל אביב."},{"i":19015,"n":"זינגר, שבתי מבאשאץ","f":"משה מפעטשי-ניידורף","bt":"תרלז","bp":"פעטשי-ניידארף","dt":"תשד","b":"תלמיד השב\"ס. חתן ר יעקב קופל קרויס מאטש. רב באשאץ-תרסו. נספה בשואה. בנו ר פנחס מאיפאלשאג וירושלים."},{"i":19016,"n":"זינגר, שלמה יהודה ליב מראזשנו","f":"אלעזר מרימאסאמבט","bt":"תרעד","dt":"תשד - כד סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר. רב בראזשנוי-תרצח. נספה בשואה."},{"i":19017,"n":"זינגר, שמואל הכהן מטומשוב","f":"ישעיה מקינצק","b":"חתן ר דב בריש מיזלש מראווא. חסיד ר ישראל מרוזין, השר שלום מבלז, והדברי חיים מצאנז."},{"i":19018,"n":"זינגר, שמעון מדומברובה","f":"יעקב יוקל","bt":"תריח או תקצח","bp":"פינטשוב","dt":"תרצז","dp":"דומברובה","b":"חסיד בובוב. חתן ר שמחה מסטוטשין. רב בסטוטשין, דומברובה."},{"i":19019,"n":"זינגר, שרגא יאיר הכהן מקראקא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":19020,"n":"זינגר-ליברזון, דוד צבי מבקשביץ","f":"יוסף חנינא ליפא","k":"אדמור מבקשביץ","bt":"תר","dt":"תרמד","b":"מחכמי בקשביץ. נכד ר אריה יהודה ליב ליברזון. חתן ר לוי יצחק מריציף. בנו ר זאב מליטוביסק."},{"i":19021,"n":"זינגרמן, בנימין מלוקישיבקה","f":"יצחק זינגרמן","b":"חתן אחיו ר יהודה ליב מפבלוטש. רב בלוקישיבקה-תרע על מקום אביו."},{"i":19022,"n":"זינגרמן, יהודה ליב מפבלוטש","f":"יצחק מלוקישיבקה","bt":"תרכג","b":"נסמך מאת ר יעקב שמואל מיאנישפולי בעל \"תפארת שמואל\". רב בפבלוטש(=פאוולאטש)-פלך קיוב-תרע. חתנו - אחיו-ר בנימין מלוקישיבקה."},{"i":19023,"n":"זינגרמן, יצחק מלוקישיבקה","b":"רב בלוקישיבקה(=לוקישיווקע)-פלך קיוב-תרל ובנו ר בנימין על מקומו אחריו."},{"i":19024,"n":"זינובר, ישראל ברוך מלונדון","f":"ליב שלום זינובר","k":"בעל נתיבות ישראל","b":"רב בלונדון."},{"i":19025,"n":"זינובר, ליב שלום מקופישוק","f":"מאיר זלמן","k":"בעל דברי שלום","dt":"תרנח-ט","b":"חתן ר רפאל מדרויא. נסמך מאת ר יצחק אלחנן מקובנא. רב באוסטרוב (כ-12 שנה), קופישק-תרפ. התכתב עם גדולי דורו ובהם ר שלמה הכהן מוילנא. נספד מאת ר חיים הלוי כץ מפומפיאן בעל נחלת חיים והזכירו בספרו. בנו - ר ישראל ברוך ואלמנת בנו הו\"ל את ספרו 'דברי שלום'."},{"i":19026,"n":"זינצהיים, יהודה ליב אפרים מוינ","f":"חיים","dt":"תקד - כד סיון","b":"גביר בוינה, תרם הרבה לצרכי צבור, בנה את חורבות בית מדרשו של רש\"י בוורמייזא, אירח את ר צבי הירש בן עזריאל מוילנא ואצלו חיבר את ספרו \"בית לחם יהודה\" (נקרא יהודה לכבודו)."},{"i":19027,"n":"זינצהיים, יוסף דוד משטרסבורג","f":"יצחק מטריער","k":"בעל יד דוד","r":"הרב הראשי ליהודי צרפת","bt":"תקה","bp":"טריר","dt":"תקע-ג - שבט","dp":"פאריס","b":"ר\"מ בביסהיים ראש הישיבה בביהמ\"ד של גיסו - ר נפתלי הרץ מאדלסהיים-תקלח, רב בשטרסבורג ור יעקב מוציק על מקומו אחריו, ראש ה\"סנהדרין\" שהקים נפוליון-תקסו - בצווי הקיסר. חיבר \"יד דוד\", \"מנחת עני\", השגות ל\"נודע ביהודה\" ושלחם למחבר ר יחזקאל לנדא. נשא ונתן עם ר יעקב שמשון סיניגאליה מאנקונא.","bk":[["שלל דוד","מפרשי תורה"],["יד דוד [הקדמות]","מפרשי ש\"ס - אחרונים"],["יד דוד [על הגמרא]","מפרשי ש\"ס - אחרונים"],["יד דוד [על המשנה]","מפרשי ש\"ס - אחרונים"],["מנחת עני","מערכות"],["יד דוד [עהש\"ס]",""],["שלל דוד [עה\"ת]",""],["דעת דוד - הארות וציונים בשו\"ע (כת\"י)",""],["יד דוד - ש\"ס",""],["מנחת עני - על התורה דרשות תשובות ופסקים",""]]},{"i":19028,"n":"זינצהיים, יצחק מנידרסהיים","b":"רב בטריער-תקל, נידרסהיים."},{"i":19029,"n":"זינצהיים, יצחק מפפד\"מ","b":"אחיו של ר ליב מוינה. מחכמי פפד\"מ. חתנו - ר דוד טבלי מלונדון."},{"i":19030,"n":"זינצהיים, ליב מוינה","b":"גביר בוינה-תפג, והיה היחיד שבזמן גירוש היהודים-תפג - הותר לו להישאר בוינה. מחותן עם ר יוסף לבוב מטרביטש."},{"i":19031,"n":"זינצהיים, שלמה חיים","b":"שיר לכבודו מאת ר יקותיאל בשם \"משלוח מנות\" אודות המאורעות בימי הפורים."},{"i":19032,"n":"זינרייך, דוד הלוי מהעלישוי וסע","b":"חתן ר יעקב-חתנו של ר זלמן שפיץ מאיזנשטט. רב בסערעד-תקם על מקום ר אנשל ור משה מייזלש על מקומו אחריו. השתתף באספת רבנים בגאלאנטי עם ר ישראל דב משוראן, ור זאב מקראקא ומגנדורף ותיקנו תקנות. בנו - ר יעקב מסעניץ, חתנו - ר מרדכי מרגליות-יפה."},{"i":19033,"n":"זינרייך, יעקב סגל מסעמניץ","f":"דוד מהעלישוי וסעלעש","b":"רב בסמניץ-תק\"פ"},{"i":19034,"n":"זינרייך, מרדכי סגל","f":"יעקב זינרייך","b":"דומ\"צ בסמניץ-תר\"כ"},{"i":19035,"n":"זיס, אברהם אבא מקומרנא","f":"בנימין ירמיהו","k":"בעל מנהגי קומרנא","bt":"תרעג","bp":"קומרנא","dt":"תרעג","b":"חסיד קומרנא ומהדיר ספרי החסידות. ניצל מהשואה. עלה לארץ אחרי השואה והיה רב בתל אביב. ההדיר ספר :\"שלחן הטהור\" תל אביב תשכג. חיבר \"מנהגי קומרנא\" תל אביב תשכה."},{"i":19036,"n":"זיס, אברהם ניסן הלוי מלמברג","bt":"תקף","dt":"תרם","b":"מחכמי למברג. מדפיס ובעל עסק במסחר ספרים. חדושים ממנו בספר בנו \"מעשיות ושיחות צדיקים\" למברג תרנה."},{"i":19037,"n":"זיס, בנימין ירמיהו מקומרנא","f":"ישעיהו","dt":"תשג","b":"נספה בשואה. בנו ר אברהם אבא - חסיד קומרנא ומהדיר ספרי החסידות."},{"i":19038,"n":"זיס, יוסף מוירטנברג ובלגרד","b":"עוזרו של הנסיך אלכסנדר מוירטנברג מושל בלגרד, סייע רבות ליהודי בלגרד תחת השלטון האוסטרי-תע. לאחר מות הנסיך אלכסנדר - נידון למיתה."},{"i":19039,"n":"זיס, ישראל דוד הלוי","f":"אברהם ניסן","k":"בעל מעשיות ושיחות הצ","b":"חיבר מעשיות ושיחות צדיקים."},{"i":19040,"n":"זיסל, זלמן מצעשניק","f":"צבי הירש שיינס","b":"רב בצאשניק-תרע\"ב"},{"i":19041,"n":"זיסלין משפירא","b":"מגדולי חכמי אשכנז,רב בפרנקפורט-קנ\"ה"},{"i":19042,"n":"זיסלין, שאול דוב מתל אביב","bt":"תרלט","dt":"תשכב - יב סיון","b":"רב פעלים,מגדולי חסידי חב\"ד,רב ברוסיה,עלה לא\"י,רב בתל אביב-תרצ\"ד"},{"i":19043,"n":"זיסנוין, יהושע זאב אבנר","f":"ישראל יצחק","k":"בעל ציר נאמן","bt":"תרג","bp":"סובלק","dt":"תרנט","dp":"ירושלים","b":"עלה לירושלים בתרמ. חיבר \"ציר נאמן\" ירושלים תרנה."},{"i":19044,"n":"זיסקוביץ, אריה","bt":"1912","bp":"אושמיאנה-פלך וילנא","dt":"1943","b":"ארגן בגיטו אושמיאנה עם חברו יוסף מינץ קבוצת פרטיזנים, הגיע לגיטו וילנא והיה פעיל במחתרת, יצא עם קבוצה ליערות נארוטש. נהרג בקרב עם חבריו לפלוגת י. גלזמן."},{"i":19045,"n":"זיסקינד הכהן","f":"רפאל הכהן","b":"רב-שנת תק\"ע"},{"i":19046,"n":"זיסקינד הלוי מלבוב","f":"אלחנן","dt":"תא - יג ניסן","dp":"לבוב","b":"תלמיד המהר\"ם מלובלין. אב\"ד ור\"מ בלבוב. נזכר בשו\"ת המהר\"ם מלובלין."},{"i":19047,"n":"זיסקינד מדרויא","b":"רב בדרויא(=דרויע)."},{"i":19048,"n":"זיסקינד מזלאטווא","b":"רב בזלאטיווע-תק\"צ"},{"i":19049,"n":"זיסקינד מלויצק","dt":"שפא","b":"אב\"ד לויצק, נספד מאת ר אברהם רפפורט בספרו \"איתן האזרחי\"."},{"i":19050,"n":"זיסקינד מקורניץ","b":"רב בקורניץ-תק\"צ"},{"i":19051,"n":"זיסקינד, חיים שמואל מבוכניה","b":"תשובה אליו - אוריין תליתאי."},{"i":19052,"n":"זיסקינד, ישראל משה מטורעק","b":"רב בטורעק. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":19053,"n":"זיסקינד, מניס מפרמישלא","b":"מחכמי פרמישלא-תרנח, ודובצעק."},{"i":19054,"n":"זיסקינד, שלמה מרדכי מניו יורק","b":"רב בניו יורק-תרלה, והסכים אז על \"עטרת שלמה\" בכת\"י - לר שלמה זלמן ברוין מפוטנאק."},{"i":19055,"n":"זיסרמן, זאב מלעווקיעוו","f":"שמואל","bt":"תרמד","b":"תלמיד ישיבות סלובודקא, טלז, קובנא. רב בלעווקי(=לעווקיעוו)-ווהלין-תרמט. נסמך מאת ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ר משה דונשבסקי."},{"i":19056,"n":"זיף","k":"ראה: זייף","dt":"תשג","b":"רב בקמינקא"},{"i":19057,"n":"זיף, דוד משה מקמינקא","dt":"תשג","b":"רב בקמינקא. נספה בשואה."},{"i":19058,"n":"זיפרט, משה","bt":"1851","bp":"וילקומיר","dt":"1922","b":"תלמיד ישיבת וולוזין - גורש בגלל קריאת ספרות פסולה. פרסם מאמרים ומחזות, היגר לארה\"ב-1886. פרסם רומנים פופולריים, ומאמרים ב\"הדור\", \"התקופה\", ועוד."},{"i":19059,"n":"זיצ’יק חיים אפרים בן אשר","bt":"1905","dt":"ה'תשמט 1989","bk":[["אור הנפש",""],["אור חדש",""],["אורות החיים",""],["המדע והחיים",""],["פרי חיים",""],["תורת הנפש",""]]},{"i":19060,"n":"זיצר, חיים יהושע מקראס","b":"תלמיד קיבוץ גבוה דרדומסק בסוסנוביץ. נספה בשואה. מתורתו - \"תורת העולות\". פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":19061,"n":"זיתון, אברהם מתונס","b":"מחכמי תונס"},{"i":19062,"n":"זיתון, אהרן ממצרים","b":"מחכמי מצרים-שנות ה-ת'."},{"i":19063,"n":"זיתון, ישראל מתונס","bt":"תרא","bp":"תונס","dt":"תרפא - יח אב","dp":"תונס","b":"תלמיד ר שלמה זרקא, ר יהודה דרמון, בעל \"גור אריה\", ר ישועה באסיס, ור אברהם הכהן יצחקי בעל משמרות כהונה, ור אברהם חג'אג' - והוציא לאור את ספר רבו \"זרעו של אברהם\". אב\"ד וראש הרבנים בתונס-תרנח, וישבו לצדו הדיינים ר משה חיים זיתון ור דוד ברבי נתן ג'אוי שכיהנו על מקומו אחריו. השיב אלפי תשובות בתונס ולארצות אחרות. מתשובותיו ב\"זכרון יוסף\" לר יוסף בוכריס, ו\"משפט כתוב\" - בני ברק תשם, ועוד. נספד ב\"פקד משה\" לר משה כלפון. בין הרבנים שעמם התכתב גם ר שמואל סלנט מירושלים.","bk":[["משפט כתוב",""]]},{"i":19064,"n":"זיתון, משה חיים מתונס","k":"בעל פני המזרח","b":"דיין בתונס אצל ר ישראל זיתון בעל \"משפט כתוב\", מגיה וחיבר הקדמות לספרי רבני תונס. ?? לא באוצר ??"},{"i":19065,"n":"זיתוני, אליהו שלמה","f":"שלמה מרדכי","k":"כאביה זיתוני","bt":"תרמג-יד סיון","bp":"ביירות","b":"דיין בביירות-תר\"ע, רב במנצ'סטר-תרפ\"ז, חזר לביירות"},{"i":19066,"n":"זך, יעקב מירושלים","b":"רב בירושלים-שנות ה-ר'-ש'."},{"i":19067,"n":"זכאר ן, משה הלוי מאלגיר","bt":"קמ","dt":"רי - בערך","b":"רב ודיין בתלמסאן, יחד עם ר אברהם ן חקון בזמן ר אפרים אנקאווא. ונזכר בשו\"ת הריב\"ש."},{"i":19068,"n":"זכות, אברהם הרופא - ג","bt":"שלה","bp":"ליסבון","b":"רופא מאנוסי פורטוגל, מצאצאי ר אברהם זכות בעל ספר יוחסין. חזר ליהדות באמשטרדם-שפה. חיבר ספרי רפואה בלטינית."},{"i":19069,"n":"זכות, אברהם מטריפולי","bt":"תל","dt":"תק","b":"דיין בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":19070,"n":"זכות, אברהם מספרד - א","b":"ממשפחה צרפתית במקור, מחכמי ספרד-קן. נכדו - ר אברהם התוכן בעל ספר יוחסין."},{"i":19071,"n":"זכות, אברהם מספרד - ב","f":"שמואל","k":"בעל ספר היוחסין","bt":"ר - ריב","bp":"סלמנקה (קשטיליה)","dt":"רעה או רפ","dp":"דמשק","b":"תלמיד ר יצחק-מהר\"י אבוהב. חכם בתורה ובקי במדעים, גיסו של ר אברהם בן אליעזר הלוי המקובל מירושלים. פרופסור לאסטרונומיה ומתמטיקה, שיכלל את מכשיר האצטרולב, והכין לוחות אסטרונומים חשובים. חיבר ספר יוחסין (קושטא שכו), וספר מתוק לנפש (ונציה שסז). בגירוש-רנב עבר לפורטוגל, אחד היחידים שניצל מגזירת השמד על יהודי פורטוגל, נשבה פעמים, הגיע לפאס, תלמאסן, תוניס, תורכיה, ירושלים והיה בישיבת הנגיד ר יצחק שולל. חיבר \"ספר היוחסין\". בנו ר שמואל. חיבר מאמר \"על הקץ והאיצטגנינות\" לבקשת הנגיד ר אברהם. (במלכי ישורון אומר כי הוא החכם ר אברהם בן סעדון)"},{"i":19072,"n":"זכות, דוד ממודנא","f":"מזל טוב","k":"בעל זכר דוד","bt":"תקלח","bp":"איטליה","dt":"תרכה - כט אייר","b":"מראשי רבני איטליה, חבר הסנהדרין בפריס-תקס\"ו, דרשן, גדול בתורה בנגלה ונסתר, חיבר \"זכר דוד\" ליוורנו, \"למודי השם\". חיבור על יסודי הדת ועוד. מתלמידיו - ר שמואל יעקב הכהן."},{"i":19073,"n":"זכות, יוסף משלוניקי","b":"מראשי קהלת גרוש ספרד בשלוניקי-רן-ש'."},{"i":19074,"n":"זכות, לוזוטאני","bt":"שמה","bp":"ליסבון","dp":"תב","b":"אנוס ממשפחת זכות, הגיע לאמשטרדם ושב ליהדות והיה מחכמי אמשטרדם. חיבר ספרים ברפואה."},{"i":19075,"n":"זכות, משה מונציה","f":"מרדכי","k":"בעל קול הרמ\"ז","bt":"שפה","bp":"אמשטרדם","dt":"תנח - טז תשרי","b":"תלמיד ר שאול מורטירה באמ\"ד, למד בפולין אצל ר יצחק מפוזן בעל \"באר יצחק\", עבר באיטליה בדרכו לארץ והתעכב שם, תלמיד ר בנימין הלוי השליח מצפת שהיה תלמיד ר חייא תלמיד הארי. מקובל, רב בויניציאה-ת\"ה, מנטובה-תל\"ד. תלמידיו ר בנימין הכהן מרג'יו ור אברהם רוויגו, ור ישעיה בסאן. חתנו הרב פאפו מאנקונה, ונכדיו - ר שמואל שמעיה ור אברהם דוד רב באישפלטרו. (גרץ האשימו בשבתאות - ופרומקין הגן עליו).","bk":[["שרשי השמות",""]]},{"i":19076,"n":"זכות, משה מוסא משלוניקי","dt":"תקם","b":"רב ודיין בטריפולי. חתם בפנקס בי\"ד טריפולי. נקבר בחלקת ג'ראמנא המקודשת (למשפחת דרמון)."},{"i":19077,"n":"זכות, שמואל מספרד","f":"אברהם","b":"יצא בגלות מספרד ופורטוגל יחד עם אביו, והגיעו לאפריקה, נפלו בשבי כמה פעמים ונפדו."},{"i":19078,"n":"זכותו, דוד מאלגיר","f":"אברהם","dt":"תנב","b":"רב ומקובל ובקי במדעים באלגיר."},{"i":19079,"n":"זכותו, יהודה","b":"חתן הראשון לציון הרב אג\"ן"},{"i":19080,"n":"זכלינסקי, משה נתנאל","f":"שמואל אבא מזיכלין","dt":"תרעב","b":"אדמו\"ר בזיכלין"},{"i":19081,"n":"זכרי ן, אהרן מצפרו-מרוקו","dt":"תקכא - יט תמוז","b":"מו\"ץ בצפרו-מרוקו"},{"i":19082,"n":"זכרי ן, דוד מפאס","bp":"פאס","dt":"מו-ז","b":"רב בפאס, נזכר בשו\"ת הרשב\"א. נזכר אצל ר יוסף בן גליל ממראקש. בנו - ר משה."},{"i":19083,"n":"זכרי ן, חיים שלמה","f":"יהושע","b":"מחכמי צפרו(מרוקו)-תרל\"ב"},{"i":19084,"n":"זכרי ן, חנניה ממכנאס","bp":"פאס","b":"סופר בי\"ד ודיין במכנאס, משורר, תרגם לעברית את \"אזן שמואל\". שאלה ממנו ליעב\"ץ ב\"משפט וצבי\". חתם עם ר משה טולדנו ומהר\"ם בירדוגו."},{"i":19085,"n":"זכרי ן, יהודה מספרד ופאס","f":"שם טוב","dt":"שה - בערך","b":"מחכמי פאס לאחר גירוש ספרד, תלמיד ר משה חלאווה. חתם על פס\"ד-שו עם ר יהודה עוזיאל, ור נחמן ן סונבאל."},{"i":19086,"n":"זכרי ן, יהושע מצפרו","f":"אהרן","b":"מו\"ץ בצפרו-שנות ה-ת'."},{"i":19087,"n":"זכרי ן, ישעיה ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'. חתם בעניני טריפות."},{"i":19088,"n":"זכרי ן, מכלוף ממרוקו","b":"נכד ר חנניה. מחכמי מרוקו, חתם-תקעו."},{"i":19089,"n":"זכרי ן, מנחם ממרוקו","f":"מכלוף","b":"מחכמי מרוקו-תקפח."},{"i":19090,"n":"זכרי ן, מסעוד ממכנאס","dt":"תקן - סיון","dp":"מכנאס","b":"גביר מקורב למלכות במכנאס-שנות ה-תק', יחד עם ר מרדכי אשריקי. נהרג עק\"ה יחד עם חברו בידי המושל אליזיד בזמן הפרעות."},{"i":19091,"n":"זכרי ן, מרדכי מאלגיר","bt":"שך - בערך","dt":"שץ - בערך","b":"רב בווהראן. שאלות ממנו לר צמח דוראן - נזכר ב\"חוט המשולש\"."},{"i":19092,"n":"זכרי ן, משה מספרד ופאס","f":"דוד","b":"רב בפאס על מקום אביו, ספרד-ל', ופאס. התכתב עם הרשב\"א ונזכר בספרו."},{"i":19093,"n":"זכרי ן, מתתיה מצפרו","f":"אהרן","dt":"תקכט - יד תמוז","dp":"מרוקו","b":"רב בצפרו-מרוקו, ודיין אצל ר רפאל משה אלבז ונזכר בספרו \"הלכה למשה\". חתם-תרך על פס\"ד. חתנו ר אהרן אפיראט."},{"i":19094,"n":"זכרי ן, נסים מפאס","f":"שלמה","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":19095,"n":"זכרי ן, ראובן מפאס","b":"מחכמי פאס, בזמן הרעב-שסז עבר למכנאס, מכתב בקשה ממנו אל ר חיים טולדנו."},{"i":19096,"n":"זכרי, יום טוב מקושטא","f":"רפאל","b":"מדפיס בקושטא-רפ, הדפיס \"הליכות שבא\"."},{"i":19097,"n":"זכרי, ימין מפאס","f":"מוסא בן שם טוב","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":19098,"n":"זכרי-זכריה הכהן מפאס","f":"נסים","b":"מחכמי פאס, חתם-רפו במחלוקת הנפיחה."},{"i":19099,"n":"זכריה דער אלטער","b":"חתם על כרוז ועד ד ארצות-שמז - שלא לקנות רבנות בכסף."},{"i":19100,"n":"זכריה הכהן מיון","b":"פייטן מחכמי יון-ריא. חיבר קונטרס להשיב על השגות הרמב\"ן על ראב\"ע, ואולי הוא שחיבר-ריא ספר להשיב על השגות הרמב\"ן על ספר המצוות לרמב\"ם. חיבר פיוט \"תורת אמת אמון\". היה חכם נוסף בשם זה בשנת - רמא."},{"i":19101,"n":"זכריה הכהן מירושלים","f":"אהרן","b":"עלה לירושלים, דרשן. תלמיד ר עובדיה מברטנורא-רנה. מספר עליו במכתב הנוסע משנת רפב. שאלה ממנו לרא\"ם בידי ר ישעיה בן יוסף מישיני מארטא."},{"i":19102,"n":"זכריה הכהן מליפאנטו","b":"דיין בליפאנטו-שנות ה-ת' אצל ר דניאל יצחק."},{"i":19103,"n":"זכריה הכהן מספרד","b":"מחכמי ספרד, פילוסוף, פייטן בזמן הר\"ן"},{"i":19104,"n":"זכריה הלוי מוינה","f":"ישכר","k":"זכריאס מאיר","dt":"תכד - כב תמוז","dp":"וינה","b":"גביר ופרנס בוינה לפני גירוש-תל. יסד בית כנסת וישיבה. כנראה עמד בראש ועד הקהלות בוינה-תטו."},{"i":19105,"n":"זכריה הלוי משלוניקי","b":"רב בשאלוניקי-תר\"מ"},{"i":19106,"n":"זכריה הספרדי","b":"דרשן מחכמי ירושלים-רנה."},{"i":19107,"n":"זכריה הרופא מתימן","f":"שלמה","k":"רז\"ה - בעל מדרש חפץ","b":"רופא מגדולי חכמי תימן, רב בד'מאר-ר' בערך. חיבר \"מדרש החפץ\"על התורה-ק\"ץ"},{"i":19108,"n":"זכריה ידידיה","b":"מגדולי חכמי צרפת באורבינא"},{"i":19109,"n":"זכריה כהן גדול, קבור בירושלים","dt":"י תשרי"},{"i":19110,"n":"זכריה מבגדד","f":"ברכאל","bt":"ד'תתיד","bp":"חלב","b":"ראש ישיבת בגדאד, חתנו של ר' שמואל בן עלי-ד'תתקנ\"ד, נפטר לאחר זמן קצר."},{"i":19111,"n":"זכריה מברלין","f":"פייטל","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":19112,"n":"זכריה מלבוב","f":"יעקב","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה עם אחיו יצחק."},{"i":19113,"n":"זכריה מנדל בן אריה ליב מבוצ’אץ’","bt":"1720","dt":"ה'תקנא 1791","bk":[["מנורת זכריה",""]]},{"i":19114,"n":"זכריה מנדל מאוסטרהא","f":"חיים","b":"מחכמי אוסטרהא. חתם על פסק דין בענין מחלוקת בין שתי הח\"ק באוסטרהא יחד עם ר נתן נטע ור יהודה סו\"ד."},{"i":19115,"n":"זכריה מנדל מהורדנא","f":"אריה ליב מהורדנא","bt":"תסז","dt":"תקו - כב תשרי","dp":"הורדנא","b":"רב בהורדנא-תפט על מקום אביו (בהיותו בן 22 שנה) ור יחיאל מרגליות על מקומו אחריו. חברו - ר אריה ליב אפשטין המזכירו בספרו - הפרדס. נפטר ללא ילדים."},{"i":19116,"n":"זכריה מנדל מטישביץ","f":"אברהם מליסא - יאסקיס","b":"בן פרנס ועד ארבע ארצות. חתן ר יעקב עמדן-היעב\"ץ. רב בטישביץ(=טשעוויטץ)-תקטו."},{"i":19117,"n":"זכריה מנדל מירוסלב","f":"משה יהושע משטרים","k":"בעל דרכי צדק","dt":"תקנה","dp":"ירוסלב","b":"תלמיד דודיו ר שלמקא ור פנחס הורביץ בעל ההפלאה, וסופרו של \"הנעם אלימלך\". רב בירוסלב-תקיד, שאנדישוב-תקלז. תלמיד ר אלימלך מליזנסק והו\"ל את ספרו \"נועם אלימלך\" יחד עם בנו ר אלעזר מליזנסק, ובו אגרתו המפורסמת לדודו על רבו ועל דרכי החסידים. חיבר \"דרכי צדק\" למברג תקנו. ותולדותיו ב\"דרכי צדק השלם\"."},{"i":19118,"n":"זכריה מנדל מלבוב","f":"ליווא-המהר\"ל מפרג","b":"רב בלבוב ש\"פ"},{"i":19119,"n":"זכריה מנדל מלובלין","f":"יוסף ממינסק","b":"מחכמי לובלין. נזכר ב\"פרי תבואה\". בנו ר דוד טעביל - חותנו של ר שלמה ליב מליקוב ולינטשיץ."},{"i":19120,"n":"זכריה מנדל מלובלין","f":"טעביל","dt":"תקנד - כד שבט","dp":"לובלין","b":"מחכמי לובלין. חתם על תקנות ופסקים בפנקס ביה\"כ ר צבי הירש בן משה דאקטאר."},{"i":19121,"n":"זכריה מנדל מליסא (קצנלנבוגן)","f":"דוד טבלי קצנלנבוגן","dt":"תקסט","b":"דיין וראב\"ד בליסא על מקום אביו, רב באינאוורצלב-תקסה. מתלמידיו - ר צבי מקלנבורג בעל \"תפארת יעקב\". החזיק בספר תורה מיוחד אשר מי שטעה בברכותיו לא הוציא את השבוע."},{"i":19122,"n":"זכריה מנדל מפודהייץ","f":"אריה ליבוש","k":"בעל מנורת זכריה","bt":"תפ","bp":"בוצאץ","dt":"תקנב - כד כסלו","dp":"פפד\"מ","b":"נכד ר דוד מזאמושט-בן ר אריה ליב בעל שאגת אריה. תלמיד ר יעקב יהושע בעל \"פני יהושע\". חתן בעל \"מרכבת המשנה\". רב בבוצאץ, פודהייץ, דרשן בלבוב, עבר לפפד\"א. נפטר ללא ילדים. חיבר \"מנורת זכריה\" פפד\"א תקלו, \"זכריה משלם\" פפד\"א תקלט. (לפי פרומקין הוא זהה לר זכריה מבעלז בעל \"באר היטב\" ולדעת אחרים הם רבנים שונים).","bk":[["מנורת זכריה",""]]},{"i":19123,"n":"זכריה מנדל מקראקא","f":"אריה ליב קלויזנר","k":"בעל באר היטב","b":"אביו מכונה הויכער רבי ליב (יש אומרים ששם אביו ר יוסף). גביר מחכמי קראקא, רב בטורבין, בעלזא-תמט. חדושיו נדפסו באמשטרדם תקיד, ואח\"כ בשם \"באר היטב\". הסכים על \"חלוקא דרבנן\", חתם-תנט אודות המדפיסים בזולקוא. בניו - ר אריה ליב, ר אלעזר מלבוב, ר משה מבעלז, ר נתן נטע מטרניגרד והורדנא? (כך לפי אוצר הספרים - והוא ספק). חתנו - ר שאול מקראקא, ר אריה ליב מסלוצק והורדנא. (לפי פרומקין היה בנו של ר יוסף מייטלינג בעל \"חותם השם\", ונכד ר אריה ליב קלויזנר \"דער הויכער\" ולדעת אחרים הוא מחליף בינו לבין ר זכריה פודהייץ בעל \"מנורת זכריה\")."},{"i":19124,"n":"זכריה מנדל מקראשנובא","b":"רב בקראשנובא-איטליה."},{"i":19125,"n":"זכריה מראווא","b":"תלמיד החוזה מלובלין. מחכמי ראווא, השר שלום מבלז חשש לקבל על עצמו את רבנות ראווא מחשש להקפדתו של ר זכריה."},{"i":19126,"n":"זלבוביץ, מרדכי מריגא","k":"מאטע פונידילר","bp":"פונודיל-פלך קובנא","dt":"תש..","b":"דיין וראש השוחטים בריגה. חסיד חב\"ד והיה \"חוזר חסידות\" ועורך שיעורים והתועדויות חסידיות בביתו. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד. נספה בשואה, רוב חדושיו אבדו."},{"i":19127,"n":"זלדוב, אלכסנדר (א. ניעמאנסקי)","k":"בעל פראפעסיאנעלע פער","bt":"1870","bp":"וילקומיר","dt":"1924","dp":"רוסיה","b":"עסקן ב\"בונד\". עורך ה\"ארבייטער שטימא\" העתון הסוצאליסטי היהודי הראשון ברוסיה שהפך לבטאון ה\"בונד\". נאסר והוגלה לסיביר, ברח ועבר לשוייץ. עורך \"די וועלט\" בוילנא-1908. חיבר זכרונות, ועוד."},{"i":19128,"n":"זלדוביץ - משפחה במינסק","b":"משפחה עשירה במינסק, היו מוקירי תורה ולקחו לבנותיהם חתנים מיוחסים."},{"i":19129,"n":"זלדוביץ, אליהו אברהם מסטרי","b":"רב בסטרי-תרצב. נכד רמ\"ז איטינגא. בנו ר יצחק אהרן - החליף מכתבים עם הרוגצ'ובר. פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":19130,"n":"זלדוביץ, ברוך ממינסק","f":"זאב וולף ממינסק","b":"חתן הגביר ר שמחה אטינגר ממינסק. גביר מחכמי מינסק-תרן."},{"i":19131,"n":"זלדוביץ, דובער ממינסק","f":"זאב וולף ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":19132,"n":"זלדוביץ, זאב וולף הלוי ממינסק","f":"אליהו","bp":"ברעזין","dt":"תרמג - כז אד\"ב","dp":"מינסק","b":"גביר מחכמי ברעזין, מינסק-תרם בערך. בניו - הגביר ר דב, ר ברוך, ר צבי הירש. חתניו - ר משה רבינוביץ ממינסק, ר מרדכי שמחוביץ (מרגליות)."},{"i":19133,"n":"זלדוביץ, צבי הירש ממינסק","f":"זאב וולף ממינסק","dt":"תרנה - טו תשרי","dp":"מינסק","b":"גביר מחכמי מינסק."},{"i":19134,"n":"זלדין, אברהם ישראל מארה\"ב","f":"בנימין בינוש","dt":"תרעה - כו סיון","dp":"ניו יורק","b":"מחכמי בוברויסק, היגר לארה\"ב-תרסה בעקבות הפרעות ברוסיה."},{"i":19135,"n":"זלדנר, אהרן דוד הכהן מארה\"ב","k":"בעל מטה אהרן","bt":"תרלה","dt":"תרצה - א תשרי","b":"רב בבוסטון, רב בסופיריאר, לורנס מאס-ארה\"ב-תרעח."},{"i":19136,"n":"זלוור, דוד מאיר צבי משמיאנוביץ","b":"רב בשמיאנוביץ. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":19137,"n":"זלוור, זלמן","k":"הו\"ל סדור הרב","b":"חסיד ר דב בער מליובאויטש, וחתנו ר מנחם מנדל. הו\"ל \"סידור הרב\"."},{"i":19138,"n":"זלוור, ישראל מראדומסק","f":"שמואל זלוור","bt":"תרטו","dt":"תרצו - כו תשרי","b":"דומ\"צ ברדומסק(=נאוי-ראדאמסק)-תרנב לצדו של אביו, ורב ברדומסק-תרסב על מקומו אחריו. נסמך מאת: ר אברהם מסוכטשוב, ר יואב יהושע מקינצק בעל \"חלקת יואב\". בניו: ר צבי הוזר מיאלעצעב, ר חנוך גרשון, ר נחמן דוד, ר יעקב שלמה."},{"i":19139,"n":"זלוור, צבי עוזר מיעלצוב","f":"ישראל מרדומסק","b":"מו\"ץ ושו\"ב ביאלעצעב(=יעלצוב)-פלך ראדום."},{"i":19140,"n":"זלוור, שמואל מראדומסק","k":"בעל שם משמואל","bt":"תקפח","dt":"תרסב - טז ניסן","b":"רב בראדומסק(=רדאמסק)-פלך פיעטרקוב. חיבר \"שם משמואל\" על המשניות - בכת\"י."},{"i":19141,"n":"זלוטוביץ, אהרן מארה\"ב","f":"מאיר יעקב","bt":"תרס","bp":"טרושין-פלך לומזה","b":"תלמיד ישיבת לומזה אצל ר יחיאל מרדכי גורדון ור יהושע זליג רוך. נסמך מאת: ר יוסף אברהם צינוביץ מלומזה, ר יהודה ליב גורדון מלומזה, מדודו - ר יוסף דב הורוביץ מסט פאל. רב בניו יורק-תרפה. בנו - ר ברוך - רב בניו יורק."},{"i":19142,"n":"זלוטניק, אליהו מירושלים","k":"בעל פרי אליהו","bt":"תרסה","dt":"תשלה - ח אדר","b":"דיין, ר\"מ בישיבת היכל התורה בירושלים."},{"i":19143,"n":"זלוטניק, יהודה","b":"פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח."},{"i":19144,"n":"זלוטניק, יונה מרדכי מפלאצק","f":"אברהם יצחק","k":"בעל כנפי יונה","bt":"תריח או תרכט","dt":"תרפב - ט אדר","b":"רב בשרנסק(=שרענצק-פלך פלאצק-תרן, זקרוצים(=זאקראטשין)-פלך וארשא-תרנז, פלאצק-תרסה. ?? לא באוצר ??"},{"i":19145,"n":"זלוטניק, יעקב מירושלים","f":"שלמה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":19146,"n":"זלוטניק, ישעיה מראדום","b":"פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה, \"אהל תורה\" - קראקא תרפח, \"דגל התורה\" - אויבר-וישובה תרפח, \"הנשר\" - טירנוי תרצג-תשד, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה, \"שערי ציון\" - ירושלים תרפא, \"שערי תורה\" - וארשא תרסג-תרצט."},{"i":19147,"n":"זלוטניק, מאיר","bt":"תרכח","dt":"תשב","b":"רב בגלובאטשוב"},{"i":19148,"n":"זלוטעס, דוד מבוליחוב","b":"תלמיד החוזה מלובלין, ר צבי הירש מזידטשוב, והשר שלום מבלז. לא כיהן באדמורות."},{"i":19149,"n":"זלזניק, אברהם יעקב מירושלים","r":"ראש ישיבת עץ חיים","bt":"תרעג","dt":"תשעא","b":"ראש ישיבת \"עץ חיים\" בירושלים. פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג.","bk":[["אור יעקב [עהש\"ס]",""],["אור יעקב - שבת פסחים סוכה סנהדרין יבמות",""],["שער התורה - לעמל התורה והיראה",""],["שער התורה - לעמל התורה והיראה, אור יעקב - שבת פסחים סוכה סנהדרין יבמות",""]]},{"i":19150,"n":"זלזניק, יצחק מירושלים","b":"פרסם מאמרים ב\"מוריה\" - ירושלים תשג."},{"i":19151,"n":"זלזניק, שלמה זלמן","f":"נחמן יעקב","k":"בעל בני יעקב","r":"רו\"מ ישיבת עץ חיים","bt":"תרמד","bp":"ירושלים","dt":"ה'תשלה","b":"תלמיד ישיבות ירושלים. מנהל ת\"ת וישבית \"עץ חיים\"-תרע. עסקן ציבור.","bk":[["זרע אברהם",""],["זרע יעקב",""],["זרעה של רחל",""],["זרע אברהם - ש\"ס",""],["זרע יעקב - שלחן ערוך אורח חיים",""],["זרעה של רחל - ביאורים במקרא",""],["זרע אברהם, זרע יעקב, זרעה של רחל",""]]},{"i":19152,"n":"ז'לט, בריש מטשוקבה","b":"אב\"ד טשוקבה לפני מלחמת העולם הראשונה."},{"i":19153,"n":"זלטלוב, שלמה מלומזה ונ\"י","k":"בעל זכרון מנחם","b":"רב בלומז'ה, ניו יורק. חיבר \"זכרון מנחם\" וארשא תרפד."},{"i":19154,"n":"זלטמן, לאיוש מהוד-מאזו","k":"בעל האשה והתלמוד","bt":"1879","dt":"1932","b":"רב הקהלה הניאולוגית בהוד-מאזו ואשארהאי. פרסם מאמרים ב\"היהודי\", ו\"אוצר הספרות\" - בעברית, ופרסם גם בהונגרית ובגרמנית. חיבר גם \"לולי דמיסתפינא\""},{"i":19155,"n":"זלטמן, משה","f":"יהודה החסיד","b":"מגדולי חכמי אשכנז-שנת ל'"},{"i":19156,"n":"זלטנרייך, אלכסנדר סנדר מקרניץ","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":19157,"n":"זלטנרייך, אשר מואדוביץ","b":"פרסם מאמרים ב\"תצא תורה\" - קריניצה תרצא."},{"i":19158,"n":"זלטנרייך, שמואל אברהם מטשקוב","k":"בעל קובץ הפוסקים","b":"רב בטשאקאווא, ארה\"ב. פרסם מאמרים ב\"הלבנון\" - גורליץ תרפח."},{"i":19159,"n":"זלטס, דוד מבוליחוב","b":"נחשב לצדיק נסתר והיה מקורב לגדולי החסידות."},{"i":19160,"n":"זלטקיס, יעקב מדרוהוביטש","f":"ישראל מזלוטשוב","k":"בעל מטה לוי","b":"חסיד מחכמי דרוהוביטש. חיבר \"מטה לוי\" ו\"בית לוי\" על המחזור, \"עקבי הצאן\" הוסיאטין תרסד. ?? לא באוצר ??"},{"i":19161,"n":"זלטקיס, יצחק מפרמישלן","b":"מחכמי פרמישלן. תשובה אליו בשות מהרשם."},{"i":19162,"n":"זלטקיס, מיכל","b":"פרסם מאמרים ב\"יבנה\" - לבוב תרפט."},{"i":19163,"n":"זלטרניך, אליקים מקשאנוב","f":"יוסף","bt":"תרמה","bp":"זבורוב","dt":"תרצא","b":"מחכמי קשאנוב. חתן ר סיני קורץ מקשאנוב."},{"i":19164,"n":"זלטרניך, אלכסנדר סנדר מלמברג","f":"אשר אנשל יצחק","bt":"תרעא","dt":"תשב","b":"אחיינו של האדמור מבובוב. חתן ר חיים מושקוביץ מגלינא. התגורר בלמברג. נספה בשואה."},{"i":19165,"n":"זלטרניך, אלכסנדר סנדר מקרעניץ","f":"יוסף","bt":"תרנז","dt":"תשב","b":"מחכמי קרעניץ-תרפה. חתן ר יונה דב הרבסט. נספה בשואה."},{"i":19166,"n":"זלטרניך, אשר אנשיל יצחק מודובי","f":"יוסף","bt":"תרמא","bp":"זבורוב","dt":"תשג","b":"חתן הגביר ר נתן אהרן וולף, ובזיוו\"ש חתן ר שלמה זלמן פרנקל מויליפולי. התישב באושפיצין אצל חותנו. רבה של ודוביצה-תרעג. הוציא לאור ספר \"משובב נתיבות\". מקצת מחדושיו בספרי אחרים. נספה בשואה."},{"i":19167,"n":"זלטרניך, יהושע ברוך מפרוביזנא","f":"אשר אנשל יצחק","bt":"תרס","dt":"תשג","b":"חתן רא\"י הורביץ מפרוביזנא, ורב על מקומו אחריו. נספה בשואה."},{"i":19168,"n":"זלטרניך, יוסף מברדיוב","dt":"תשד","b":"רב בברדיוב."},{"i":19169,"n":"זלטרניך, יוסף מזבארא","b":"פרסם מאמר ב\"אגם מים\" תרס."},{"i":19170,"n":"זלטרניך, מנחם מנדל מקשאנוב","f":"יוסף","k":"בעל דברי מנחם","bt":"תרנג","bp":"זבורוב","dt":"תשג","b":"חתן ר משה הלברשטם מקשאנוב. רב בקשאנוב. נספרה בשואה. חיבר \"דברי מנחם\" שנדפס בסוף \"ילקוט הפלאות\" בילגוריי תרצח. ?? לא באוצר ??"},{"i":19171,"n":"זלטרניך, נתן אהרן מדובשיץ","f":"אשר אנשל יצחק","bt":"תרסה","dt":"תשג","dp":"למברג","b":"חתן ר מתתיהו חיים הלפרין מדובשיץ. רב בדובשיץ על מקום חותנו, והתפטר מכהונתו. נספה בשואה."},{"i":19172,"n":"זלטרניך, שמואל אברהם מטשקובה","f":"אשר אנשל יצחק","bt":"תרע","dt":"תשמא","b":"ממקורבי האדמור מבובוב. חתן ר אריה הלברטשם מגורליץ. רב בטשקובה-תרצד. ניצל מהשואה. אחר השואה רב בכמה עיירות באירופה ואחר כך עבר לניו יורק ושם כיהן כרב. עורך קובץ הפוסקים על חו\"מ."},{"i":19173,"n":"זליג הירש מגלנטה","b":"דומ\"צ בגאלאנטא-תר\"נ"},{"i":19174,"n":"זליג הכהן מקרלסבורג","b":"רב בקרלסבורג ומדינת זיבנבירגן"},{"i":19175,"n":"זליג הריס ל.","bt":"1880","dt":"ה'תשכ 1960","bk":[["די סדרה און הפטרה",""],["פון אייביגען קוואל",""]]},{"i":19176,"n":"זליג מברוד","dt":"תצ","b":"מחכמי ברוד"},{"i":19177,"n":"זליג מברוד","k":"החסיד מברוד","bt":"תץ","b":"תלמיד המגיד ממזריטש, והמגיד מזלוטשוב. נזכר ב\"תורי זהב\" לר בנימין מזאלוזיץ."},{"i":19178,"n":"זליג מירושלים","f":"חנוך הניך מקלווריה","b":"נכד ר יהודה מוילנא - היסו\"ד. מקובל, רב בירושלים-תקץ."},{"i":19179,"n":"זליג מליסא וטיקטין","dt":"תקיז - כד אדר","b":"ראב\"ד בליסא,טיקטין"},{"i":19180,"n":"זליג ממאקוב-מחוז צ'אנאד","f":"יעקב זליג הכהן ממאקו","b":"רבה הראשון של מאקו, ור יהודה ליב סגל על מקומו אחריו."},{"i":19181,"n":"זליג מנאוידוור","dt":"תקצה - ט כסלו","b":"רב בנאדאודוואר"},{"i":19182,"n":"זליג מפלונגיאן","dt":"תשג","b":"מרבני פלונגיאן"},{"i":19183,"n":"זליג מקלימוביטש","b":"רב בקלימוביטש"},{"i":19184,"n":"זליג משרנצק","k":"ר' זליג משרנצק","b":"רב בשרנצק-תר\"פ"},{"i":19185,"n":"זליג שמוקלער מוילנא","b":"ממיסדי ותומכי ישיבת מייליס בוילנא."},{"i":19186,"n":"זליגזון, אברהם אבא מקראקא","f":"מיכאל אהרן","bt":"תרסז","b":"חסיד חב\"ד (אביו היה חסיד חב\"ד היחידי בקראקא). רופא בבית החולים היהודי בקראקא. ניצל מהשואה והגיע לשנחאי והציל יהודים רבים כרופא. הגיע לארה\"ב-תשז והיה רופאם של אדמורי חב\"ד. חתן ר יצחק מאיר הכהן פינסקר מפלונסק. ספר \"תולדות חייו של הרב החסיד הרופא זליגזון\" מאת בנו ר מיכאל אהרן - ניו יורק תשן."},{"i":19187,"n":"זליגמן יהודה הכהן מהמבורג","f":"ישכר בער הכהן מהמבור","b":"גביר מחכמי המבורג-תק ומראשי הקהלה על מקום אביו. חתן ר שמשון ורטהיימר מוינה. שתדלן הקהלה בזמן \"גזירת הענגע טעפכען\". מבניו: ר יצחק הכהן מהמבורג."},{"i":19188,"n":"זליגמן מהמבורג","dt":"תקע - ו תמוז","b":"רב בהמבורג"},{"i":19189,"n":"זליגמן מוגעטשע","b":"רב בווגוועטשע-תר\"י"},{"i":19190,"n":"זליגמן סגל מאופנהים","f":"מנחם ציוני","b":"מגדולי חכמי אשכנז,מרביץ תורה באפנהים-ר\"כ"},{"i":19191,"n":"זליגמן, אהרן עזריאל","dt":"שעז","b":"רב בפפד\"מ"},{"i":19192,"n":"זליגמן, זלמן שמעון מבוריספול","bt":"תרל","b":"נסמך מאת: ר שניאור נח שניאורסון מבוברויסק. רב בבאריספול-פלך פולטבה-תרסה."},{"i":19193,"n":"זליגמן, חיים דוד מגריווא","f":"מיכאל יעקב מגריווא","b":"חתן ר נפתלי ציוני מלוצין. רב בגריווא-(תריא בערך) על מקום אביו - נפטר בן בגיל 24. בנו - ר ישראל זליגמן מלוצין. אחיו - ר שלום אליהו דב מדנקרא."},{"i":19194,"n":"זליגמן, חיים מגשלר","b":"רב בגשלר"},{"i":19195,"n":"זליגמן, יהושע מפרג","b":"דיין בפרג-שנת ת'"},{"i":19196,"n":"זליגמן, יוסף מצנסטחוב וקראסני","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":19197,"n":"זליגמן, ישראל מדריסא","f":"אהרן זליג מאשווא","b":"רב באשווע, שעבעז, דריסא-פלך ויטבסק."},{"i":19198,"n":"זליגמן, ישראל מלוצין","f":"חיים דוד מגריווא","dt":"תרסח - ג טבת","dp":"לוצין","b":"מחכמי לוצין. חיבר \"יד ישראל\", \"מעין גנים\", הניח חדושים בכת\"י."},{"i":19199,"n":"זליגמן, מיכאל יעקב מגריווא","f":"ישראל מדריסא","dt":"תריא - ז אלול","b":"חתן ר יהודה ליב מרגליות מטלז. רב בגריווא-תר, ובנו ר חיים דוד על מקומו אחריו, בנו גם - ר שלום אליהו דב."},{"i":19200,"n":"זליגמן, רפאל","b":"רב בדריסה-תר\"י"},{"i":19201,"n":"זליגמן, שלום אליהו דוב מדנקערא","f":"מיכאל יעקב מגריווא","bt":"תקצט","bp":"גריווא-קורלנד","b":"נכד-אבי אמו ר יהודה ליב מרגליות מטלז. רב בדנקרה(=דנקערא)-פלך ויטבסק-תרלה."},{"i":19202,"n":"זליגסברג, מרדכי חיים","k":"בעל עיר מקלט","b":"מחכמי פעלהיים-ליד מעמינגען."},{"i":19203,"n":"זליגר, יוסף מסניאטין","f":"שמואל הלוי","bt":"תרלב","bp":"סניאטין","dt":"תרעט","b":"בעל תואר דוקטור מאוניברסיטת ברן בשוויץ. התיישב בקראקא ועסק בחינוך. פרסם בכתבי עת שונים. חתן ר יוסף רוזנקרנץ. עלה לארץ-תרסז, ואשתו ערכה את הספר \"כתבי הרב ד\"ר יוסף זליגר\" ירושלים תרץ."},{"i":19204,"n":"זליחובר, שמעון","b":"מרביץ תורה בישיבת חכמי לובלין-תר\"צ"},{"i":19205,"n":"זלינגר, מאיר","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":19206,"n":"זליקוביץ, גצל (גיאורג)","k":"בעל ציורי מסע במדבר","bt":"1863","bp":"ריטובה-ליטא","dt":"1936","b":"מומחה לשפות שמיות בספריה הלאומית בפאריס, מתרגם ראשי במשלחת לורד וולפול וקיצ'נר להצל גורדון בסודן, מרצה על כתב חרטומים בפנסילבניה. פרסם ב\"המליץ\" ו\"המגיד\". בסוף ימיו חיבר רומנים פופולריים באידיש."},{"i":19207,"n":"זליקוביץ, נתן מקאלאנדיא","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":19208,"n":"זליקמן","dt":"שעז - יא ניסן","b":"דיין בפפד\"מ"},{"i":19209,"n":"זלכה הכהן, אפרים מירושלים","f":"משה","bt":"תרמו","bp":"בגדד","dt":"תשיז - ג תשרי","dp":"ירושלים","b":"עלה לא\"י-תרפ\"ד, ראש ישיבת \"פורת יוסף\" בירושלים,"},{"i":19210,"n":"זלמאטי, זרחיה מאלגיר","f":"שלמה","bt":"קפ","dt":"רס","b":"רב ומשורר בתלמסאן, שאלות ממנו לרשב\"ש."},{"i":19211,"n":"זלמאטי, יוסף מאלגיר","b":"רב בתלמסאן. נזכר בפנקס ר סעדיה בן סידון (ברשימות ר יצחק רוש)."},{"i":19212,"n":"זלמאטי, ישועה ממצרים","b":"רב במצרים. נזכר בספר הדרשות של ר חיים חברייא מקאהיר, ואצל ר שבתי ברכה ממצרים."},{"i":19213,"n":"זלמאטי, שלמה מאלגיר","f":"יוסף","b":"רב בספרד, הגיע לאלגיר-רן עוד לפני הגירוש והתישב בתלמסאן. סופר, והעתיק בשנת רן את פירוש ר יהודה מושקוני על האבן עזרא עבור ר יהודה כלץ. תשובה אליו מר צמח בן הרשב\"ש לשאטיבא-ספרד."},{"i":19214,"n":"זלמינד, שלמה מראשקוב ראה\"","f":"שלמה זלמינא מראשקוב","b":"רב בראשקוב-תר\"ס"},{"i":19215,"n":"זלמלין","b":"ראש הרבנים בויניציאה-שנת ש'"},{"i":19216,"n":"זלמן","f":"משה אפרים","b":"רב-שנת ת\"ר"},{"i":19217,"n":"זלמן אפרים מברסטיצקי","f":"שאול מלודמיר","b":"חתן ר ישראל חריף מזסלב ואוסטרהא. רב בברסיטישקע(=ברסטיצקי) על מקום אביו, דובנא ור אברהם כהנא על מקומו אחריו (ביניהם היה תקופה ללא אב\"ד)."},{"i":19218,"n":"זלמן הכהן ממנטובה","b":"רב במנטובה. הספידו - ר שמואל יהודה קצנלנבוגן."},{"i":19219,"n":"זלמן וולף מוילנא","dt":"תרכז - י תשרי","b":"מרביץ תורה ומו\"צ בווילנה"},{"i":19220,"n":"זלמן זעזמיר מדוינסק וקריסלאוב","b":"תלמיד בעל התניא, והיה גם מחסידי בנו ר דב בער אחריו. קירב את ר הלל מפאריטש לחסידות חב\"ד."},{"i":19221,"n":"זלמן חסיד מפפד\"מ","dt":"תקנא - ח חשון","b":"איש מופת,מרביץ תורה בפפד\"מ"},{"i":19222,"n":"זלמן חסיד מפפד\"מ","b":"מתלמידיו - החתם סופר."},{"i":19223,"n":"זלמן כץ ממנטובה","b":"ר\"מ במנטובה-שנות ה-ש', ונזכר אצל ר יהודה מינץ."},{"i":19224,"n":"זלמן ליב מצפת","f":"וולף","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":19225,"n":"זלמן ליפא מקאדמיע","b":"רב בקאדמיע-ת\"ר"},{"i":19226,"n":"זלמן מבערנוי ופרשבורג","f":"שלמה","k":"פרשבורג","dp":"תקפט - ג שבט","b":"פרנס מראשי קהלת פרשבורג. חתם על כתב מנוי רבנות לחת\"ס-תקסז."},{"i":19227,"n":"זלמן מגולדינגן","dt":"תרלו","dp":"גולדינגן","b":"שמש ודיין בגולדינגן. בנו - ר בנימין ממיטאווי."},{"i":19228,"n":"זלמן מגרודזיסק","b":"תלמיד ר אלימלך מליזנסק, וחברו של החוזה מלובלין - שאמר לו \"רבי זלקא אנו אוהבים אתכם מאוד\"."},{"i":19229,"n":"זלמן מדובראוונא","b":"תלמיד בעל התניא, ובנו ר דב בער אחריו, ושניהם ביקרוהו כמה פעמים בביתו."},{"i":19230,"n":"זלמן מויליז וליעפלי","b":"תלמיד ר מנחם מנדל מליובאויטש. אב\"ד ויליז, ליעפלי, קריסלוב."},{"i":19231,"n":"זלמן מזלטשוב","dt":"תקצא - ח אב","b":"רב בזלאטשוב"},{"i":19232,"n":"זלמן מלאדי","k":"ר' זלמן מלובלין","b":"רב בלאדי,עלה לירושלים-תר\"כ"},{"i":19233,"n":"זלמן מלוברנץ","b":"רב בלוברנץ-תר. בנו - ר זכריה ליב לוברנץ מדרום אפריקה."},{"i":19234,"n":"זלמן מלויצק","b":"תלמיד הבעשט. אחיין ר קהת מוועריש. שליחו של הבעשט למעשי מופת, ומקושר גם עם ר אדם בעל שם. אחרי פטירת הבעשט מקורב למגיד ממזריטש ולר שניאור זלמן מלאדי."},{"i":19235,"n":"זלמן מליקעווע","b":"מקובל,רב בליקעווע-תק\"מ"},{"i":19236,"n":"זלמן מפרשבורג","f":"משה חריף","b":"דומ\"צ בפרשבורג-תק\"כ"},{"i":19237,"n":"זלמן מקובנא","k":"בעל קול שחל","b":"ר\"מ בקובנה-תר\"כ ?? לא באוצר ??"},{"i":19238,"n":"זלמן מקולומיאה","f":"יעקב קופל קופילטיס","b":"חותנם של ר שאלתיל יצחק מקולומיאה ור יעקב קופל חסיד. מחכמי קולומיאה לאחר שגורש משנייטוך. עלה לארץ (וקיבל ברכה מאחיינו ר מנחם מנדל מקוסוב) והתגורר בטבריה בימי רז\"ו מטשרני-אוסטרהא. נכדו ר משה יוסף שרף רב בזבלטוב וזלישטשיק."},{"i":19239,"n":"זלמן מקולומייא","f":"יעקב קופל קמיאל","b":"רב בקולומייא-ת\"ק"},{"i":19240,"n":"זלמן מקונסטנטין","b":"מגיד בקונסטנטין. נכדו - ר מאיר לרנר מלאבון."},{"i":19241,"n":"זלמן מקורעניץ","dt":"תקצט - כ כסלו","b":"תלמיד ר שניאור זלמן בעל התניא ובנו ר דב בער."},{"i":19242,"n":"זלמן משלם מגוריציאה","f":"אברהם","b":"רב, גורש מוינה. הוציא לאור \"חסד לאברהם\" לר אברהם אזולאי."},{"i":19243,"n":"זלמן פנחס מגילוואן","b":"רב בגילוואן-תר\"ע"},{"i":19244,"n":"זלמן ריבלס (=ריבעהלעס)","b":"דודו של הגר\"א. מגדולי חכמי וילנא-תק. חתנו - ר ישכר בר אנצילביץ מדרושקביץ."},{"i":19245,"n":"זלמנוב, זלמן מוארשא","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":19246,"n":"זלמנוב, שמואל מוארשא ונ\"י","b":"עורך \"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\". פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":19247,"n":"זלמנוב, שרגא פיבוש","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד - ובו על החסיד ר חנוך הנדל."},{"i":19248,"n":"זלמנוביץ, אברהם יצחק מנ\"י","f":"אביגדור מלודז","bt":"תרמז","bp":"טומשוב","dt":"תשז - ט תשרי","b":"תלמיד ר אברהם ברנשטין בעל \"אבני נזר\". נסמך מאת: ר אליהו חיים מייזל מלודז. חסיד גור. ר\"מ בישיבת רבי יצחק אלחנן בניו יורק-תרפז, רב בברוקלין. סייע בהצלת יהודים בזמן השואה, ולהצלת האדמור מגור. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":19249,"n":"זלמנוביץ, אהרן שלמה","f":"ישכר דב הלוי","bt":"תרל","bp":"ריטובה-פלך קובנא","dt":"תשא","dp":"מונטריאול","b":"תלמיד ישיבות טלז, וולוזין. נסמך מאת: ר חיים סולוביציק, ר צבי רבינוביץ מקובנא, ר משה דנישבסקי מסלובודקה. רב בספיזשוק(=ספיזישוק)-ליד קובנא, דוקשיץ-פלך מינסק, היגר לקנדה וכיהן כרב במונטריאול-תרפד, והיה ראש ועד הרבנים שם. הניח חדושים על הש\"ס-בכת\"י."},{"i":19250,"n":"זלמנוביץ, הלל","dt":"תשג","b":"רב בגולבקי"},{"i":19251,"n":"זלמנוביץ, ישכר דוב","f":"שלמה זלמן-בית אבות","b":"מצאצאי ר אברהם-אחי הגר\"א. רב-שנת תרמה. בנו - ר אהרן שלמה זלמן."},{"i":19252,"n":"זלמנוביץ, מנחם","dt":"תשג","b":"רב בועד הרבנים בווילנה"},{"i":19253,"n":"זלמנוביץ, שלום מוילנא","f":"מאיר ישראל מוילנא","b":"בן למשפחה שבמשך דורות היו שומרי בית העלמין בוילנא. חיבר ספר על גר הצדק אברהם - הגרף פוטוצקי - קובנא תרצד."},{"i":19254,"n":"זלמנוביץ, שלמה זלמן מניישטט","b":"חתן ר אליעזר ליפמן ליכטנשטין מטוקום. נכד ר מיכל בן ר אליהו בן ר אברהם-אחי הגר\"א. רב בניישטט, סוגינט-תרי. בנו - ר ישכר דב ונכדו ר אהרן שלמה זלמן."},{"i":19255,"n":"זלמנסון, לוי יצחק מוויליז","k":"חתן ה\"צמח צדק\"","b":"נכד(-אבי אמו) האדמור האמצעי, ונינו של ר לוי יצחק מברדיטשוב. חתן בעל \"צמח צדק\". ראש ישיבת הצמח צדק בליובאוויטש, רב בוויליז-תרל."},{"i":19256,"n":"זלנפרינד, אלכסנדר יעקב משיניבה","f":"חיים מאיר זאב הכהן","bt":"תקמח","bp":"טרלא","dt":"תרלד","b":"רב בהאלאס, שאמשון על מקום ר יצחק יעקב בלום, ור פנחס וייס על מקומו אחריו, שינאווא. הוציא לאור ספר אביו ובו מקצת מחדושיו שלו - \"שערי חיים\" פרשבורג תריט."},{"i":19257,"n":"זלנפרינד, שלמה שמואל","f":"חיים מאיר זאב הכהן","b":"חתן ר אלעזר לעוו-מינץ בעל \"שמן רוקח\". רב בראסנוביץ-תרנ (כך באוצר הספרים - אך לפי הרצוג - \"קהלת שטמפן\" - זו טעות כי חתנו של בעל שמן רוקח נפטר בשנת תקסט)."},{"i":19258,"n":"זלנץ, א' מפלוטל-ליטא","dt":"תש..","b":"רבה האחרון של פלוטל. נספה בשואה."},{"i":19259,"n":"זלץ, ישכר בער מצפת","b":"פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":19260,"n":"זלץ, משה יוסף מטורנא","dt":"תשג","b":"חתן ר צבי הירש גוטוירט. ר\"מ בישיבת בובוב בטורנא. רב בזאטור-תרצא על מקום חמיו. נספה בשואה."},{"i":19261,"n":"זלץ, משה מרדומישל","b":"רב ברדומישל. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד."},{"i":19262,"n":"זלצבורג, אברהם עבריל מלבוב","f":"משלם זלצבורג","dt":"תמא - יג טבת","b":"דיין בלבוב. חתם-תיד על תקנה. נזכר ב\"איתן האזרחי\", חתם על גביית עדות עם ר יעקב בן יוסף , ר יהודה ליווא אפשטין, ור יעקב בן אברהם יעקב יוסף קצנלנבוגן-תח."},{"i":19263,"n":"זלצבורג, אברהם עבריל מקראקא","f":"משלם","b":"חתן ר שלום שכנא הכהן מקראקא (ולפי בובר בנו ר שמריה הוא שהיה חתן ר שלום שכנא). גביר תלמיד חכם בקראקא-שן. בנו ר שמעיה שמרל."},{"i":19264,"n":"זלצבורג, יהודה ליב","f":"שמריה בן אברהם עבריל","b":"הו\"ל חדושי מהר\"י בן לב-וילמשדורף תעט."},{"i":19265,"n":"זלצבורג, משה מזולקוא","f":"אלעזר","b":"חתם-שפו על תקנה בזולקוא."},{"i":19266,"n":"זלצבורג, משלם אשכנזי","f":"אברהם אב\"ד לבוב","dt":"תה - ח חשון","dp":"לבוב","b":"חתן ר השל מקראקא. אב\"ד בלבוב על מקום ר יהושע בעל מגיני שלמה (שהזכירו בספרו \"פני יהושע\"). נזכר ב\"סדר גיטין\" לר אברהם שרנצל. הסכים על \"מגיד מישרים\", חתם-תא בפנקס קהלת לבוב. מצאצאיו ר משלם איגרא מטיסמניץ. חתנו - ר יעקב מרדכי מפוזנא (או ר מרדכי כץ מפוזנא)."},{"i":19267,"n":"זלצבורג, שמריה שמרל","f":"אברהם עבריל בן משלם","b":"חתן ר שכנא כהנא-חתנו של בעל מגיני שלמה (כך לפי בובר). ראה גם שמריה שמרל מלבוב. בנו - ר יהודה ליב (שהו\"ל חדושי מהר\"י בן לב - וילמשדורף תעט)."},{"i":19268,"n":"זלצברג, ליפא מאושפיצין","bt":"תרעב","bp":"אושפיצין","dt":"תשנב","b":"נכד הנועם אלימלך. חסיד בלז. חתן ר ישראל הלוי לנדא מרישא. עבר לקראקא. ניצל מהשואה, עבר לפריזז. עלה לארץ-תשכו."},{"i":19269,"n":"זלצברג, מנחם (מכס)","k":"בעל שורת הכבוד-תשיב","bt":"1883","bp":"קובנא","dt":"1954","dp":"המבורג","b":"תלמיד ישיבת סלובודקה. למד בברלין פילוספיה ושפות. התעוור והמשיך בלימודיו. נשא אשה גרמניה שהסתירה אותו בברלין בזמן השואה. חיבר ספורים ותיאורים מחיי יהודי ליטא."},{"i":19270,"n":"זלצברגר, משה מאלשקוביץ","b":"רב באלשאקובין"},{"i":19271,"n":"זלצמן, אבא מדומברוביץ","dt":"תשב - יד אלול","b":"רב בדומברוביץ"},{"i":19272,"n":"זלצמן, ברוך","b":"פרסם מאמרים ב\"החיים\" - לונדון תש."},{"i":19273,"n":"זלצמן, יהודה ליב מלונא","f":"מתתיהו","b":"גביר תלמיד חכם בלונא. גיסו של ר חיים עוזר גרודזנסקי."},{"i":19274,"n":"זלצמן, יעקב מדוברוביץ","f":"יהודה ליב","bt":"תרלא","b":"רב בדוברוויץ-וואהלין-תרסא."},{"i":19275,"n":"זלצמן, משה יעקב מדריליטש","b":"פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":19276,"n":"זלצמן, צבי הירש ממינסק","b":"גביר מחכמי מינסק-תר בערך."},{"i":19277,"n":"זלצמן, שלמה","f":"דוד","k":"בעל מן העבר הקרוב","bt":"1872","bp":"סעלץ-פלך גרודנא","dt":"1946","dp":"גבעת ברנר","b":"תלמיד ישיבת מיר. חבר הועד הציוני באודסה. מיסד ומו\"ל ה\"ראזסוויט\", ועוד. מיוזמי האנציקלופדיה הרוסית הגדולה. עלה לארץ-1919 והיה ממייסדי \"הארץ\". הו\"ל תרגומים שונים לעברית בהוצאותיו \"קדימה\", \"השחר\" ו\"הספר\". חיבר ספרי זכרונות."},{"i":19278,"n":"זלצר, אברהם דב מקראקא","b":"מחכמי קראקא - תשובה אליו בשות מהרשם."},{"i":19279,"n":"זלצר, אהרן מונדזיגולה","b":"חתן ר ישראל איזראליט מגרודנא. רב בונדזיגולה - התפטר מהרבנות והתפרנס מחנות. בנו לואיס עוזר ליב - עסקן חשוב בניו יורק."},{"i":19280,"n":"זלצר, דוד הכהן ממונקטש","f":"מיכאל מסערדאוהל -הבן","k":"בעל דברי דוד","dt":"תרסח - כט-ל שבט","b":"נכד ר דוד דייטש בעל \"אוהל דוד\". תלמיד דודו זקנו מהר\"ם א\"ש, ודודו(-אחי אמו) ר שמעון פרידמן מגאלאנטא. חתן דודו ר יוסף שלמה זלמן אסטריכר ממונקטש, ובזיוו\"ש חתן בנו ר מרדכי אסטריכר בן ר יוסף שלמה. נעזר בידי אחי חמותו - הגביר ר יוסף זרח הורביץ. רב במונקטש. בניו ר מאיר זאב, ר מרדכי - דיינים ורבנים במונקטש. חתנו - ר יצחק צבי יונגרייז מקאשוי."},{"i":19281,"n":"זלצר, דוד יהודה ליב מהומנא","f":"שלמה מקוברסדורף","k":"בעל מנחת בכורים","bt":"תרח או תרי","bp":"ראדא שיצא","dt":"תרעט - כט אד\"ב","dp":"הומנא","b":"תלמיד הכת\"ס, ור אברהם שאג מקוברסדורף ור יהודה אסאד. גיסו של ר יוסף חיים זוננפלד מירושלים. חתן ר דוד כץ בן צבי ממטרסדורף. רב בטעוויל-תרלד, באטורקז(=באטריקעז)-תרלט, הומנא-תרנב, חתנו ר יצחק איזיק פרידריך על מקומו אחריו. הו\"ל ספרי חותנו \"מנחת כהן\" עם תוספות ממנו, ועוד. חתנו גם - ר אשר אנשל יונגרייז מטשנגר."},{"i":19282,"n":"זלצר, יהודה ליב מארה\"ב","f":"יצחק מהלוסק","k":"בעל משא יהודה","bt":"תרכט","bp":"הלוסק-פלך מינסק","dt":"תשיט - יח אלול","b":"תלמיד ישיבת וולוזין, קיבוץ סלוצק, וילנא, איישישוק. היגר לארה\"ב וכיהן כרב ברב בבנגור(סאניגור?)-מיין-תרס, פטרסון-ארה\"ב-תרסו, צפת-תרעג, ברידג'פורט-תרפג, מיניאפוליס. נסמך מאת: הרידב\"ז, ר צבי הירש מה יפית, ר\"י אליאשברג מוולקוביסק. מנשיאי אגודת הרבנים בארה\"ב-תרעד. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג, \"היכל התורה\" - נ\"י תרצג, \"היהודי\" - נ\"י תרצו, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג, \"מרכז התורה\" - מונטריאול תשב, \"שערי ציון\" - ירושלים תרפא."},{"i":19283,"n":"זלצר, יחיאל מסערד-האלי","dt":"תשג","b":"רב בסערדאהעלי"},{"i":19284,"n":"זלצר, יעקב הכהן מיוהנסבורג","f":"יוסף מפרשבורג","k":"בעל אוצר יעקב","bt":"תרעו","bp":"פרשבורג","dt":"תשם - כה אלול","dp":"ירושלים","b":"תלמיד הדעת סופר. עלה לירושלים-תש. חתן ר מנחם מנדל עמנואל. רב ביוהנסבורג (דרום אפריקה)."},{"i":19285,"n":"זלצר, יעקב קופל מוינה","f":"דוד מפרשבורג","bt":"תרי","bp":"פרשבורג","dt":"תרצה - ה כסלו","dp":"וינה","b":"תלמיד הכת\"ס. חתן ר אלחנן. רב בוינה."},{"i":19286,"n":"זלצר, מאיר זאב ממונקטש","f":"דוד - דברי דוד","dt":"תשד","b":"דומ\"צ במונקאטש."},{"i":19287,"n":"זלצר, מיכאל מסערדאוהל - האבא","f":"צבי הרש הכהן","bt":"תקמד","dt":"תקעב - ז סיון","dp":"סערדאוהל או פרשבורג","b":"תלמיד החת\"ס. חתן ר דוד דייטש מסערדאוהל. גיסו של ר מאיר א\"ש מאונגוואר. רב בסערדאוהל. נספד ע\"י החת\"ס. אלמנתו נישאה בזיוו\"ש לר בער רוזנר ממונקטש. בניו - ר מיכאל (שנולד לאחר פטירתו), ר מנחם קאהן מאונסדורף."},{"i":19288,"n":"זלצר, מיכאל מסערדאוהל - הבן","f":"מיכאל","bt":"תקעב","dt":"תרנד - ד טבת","dp":"סערדאוהל","b":"נולד לאחר פטירת אביו ונקרא על שמו. גדל אצל זקנו ר דוד דייטש מעיר חדש. תלמיד החת\"ס, ור משה שיק מחוסט. חתן ר אליעזר אסטריכר מקראלי. מחכמי סערדאוהל. בנו - ר דוד ממונקטש בעל דברי דוד."},{"i":19289,"n":"זלצר, מרדכי ממונקטש","f":"דוד - דברי דוד","k":"בעל ויכתוב מרדכי","b":"מ\"מ במונקטש."},{"i":19290,"n":"זלצר, פנחס יעקב מהעדילא-מאדא","bt":"תרלה","bp":"סנט קירלי","dt":"תשד - כז אייר","b":"תלמיד השב\"ס, ור יעקב טננבוים מפוטנק. חתן ר דוד יצחק טיטלבוים מערדא-בעניע. ראה הקהל בהעדילא-מאדע."},{"i":19291,"n":"זלצר, שלמה חיים מארה\"ב","f":"יצחק מהלוסק","bt":"תרמא","bp":"הלוסק","b":"חתן ר שמואל ארמסון מניו יורק. תלמיד ישיבת איישישוק, סלוצק, ר אהרן סידערסקי בקיוב. היגר לארה\"ב וכיהן כרב בראקסבורי-מסטצוסס-תרסו."},{"i":19292,"n":"זלצר, שלמה מראדא-שיצא","b":"רב בראדא-שיצא, קוברסדורף, עלה לירושלים. חותנו של ר יוסף חיים זוננפלד מירושלים."},{"i":19293,"n":"זלקא, מנחם ב","bt":"תרכח","b":"ראב\"ד בדאלינא"},{"i":19294,"n":"זלקינד שלמה זלמן בן יהושע","bt":"1806","dt":"ה'תרכח 1868","bk":[["קול שלמה",""]]},{"i":19295,"n":"זלקינד, דב בר מראקישוק","b":"ראש ישיבה בראקישוק-אחרי מלחה\"ע ה-I על מקום ר שמואל לויטין שהיגר לארה\"ב."},{"i":19296,"n":"זלקינד, יהודה ליב מדוינסק","f":"שלמה","k":"לייב בטלן","dt":"תריח","dp":"דוינסק","b":"רב בוילקומיר על מקום ר חיים מוולוזין, דוינסק. השיב לשואלים מקרוב ומרחוק - תשובותיו התבססו על המקור התלמודי ולא על האחרונים."},{"i":19297,"n":"זלקינד, יואל זליג מרייגורד","f":"ישראל","k":"בעל בית יואל","bt":"תקצט","bp":"וילוקמיר","b":"רב באוראן-ליטא, אליטא, רייגרוד(=רייגראד)-תרכח. חיבר \"בית יואל\" על \"פחד יצחק\" לר יצחק למפרונטי."},{"i":19298,"n":"זלקינד, שלמה זלמן מוילנא","f":"יהושע","k":"בעל קול שלמה","bt":"תקסו","bp":"וילנא","dt":"תרכח - כ אדר","b":"חתן ר וולף קאזס מבריסק. מורה בביהמ\"ד למורים בוילנא. בשנות ה-1840 הגיש תזכיר לממשלה הרוסית בדבר הצורך בהפצת השכלה בין יהודי רוסיה. חיבר גם \"שמע שלמה\" וילנא תרכו, ועוד."},{"i":19299,"n":"זלקינד, שמואל מוילנא","bp":"ליטא","b":"יסד בוילנא-1841 יחד עם מ.א. גינצבורג בי\"ס ראשון מסוגו בליטא שלימד יהדות והשכלה כללית."},{"i":19300,"n":"זלקינדסון, ארנולד","bp":"וילנא","dt":"תש..","b":"מתמיטקאי ורופא. עסק בגיטו במחקר מתמטי. נספה בשואה."},{"i":19301,"n":"זלקינסון (סלקינסון), יצחק אדו'","bt":"1822","bp":"וילנא","dt":"1883","dp":"וינה","b":"נסע לסמינר רבנים בארה\"ב ובדרכו עבר בלונדון התחבר למסיונרים והתנצר. נשלח כמסיונר לאדינבורג ואח\"כ היה בגלזגו, פרשבורג, וינה. תרגם לעברית \"גן העדן האבוד\", וכתבי שקספיר. עליו ב\"יצחק אדוארד זלקינסון\" תל אביב תשב."},{"i":19302,"n":"זלקלן (ז\"ק), יהודה מפרג","f":"נתן","dt":"שי - טו שבט","dp":"פרג","b":"מקובל, מלמד תורה בפרג, אולי הוא הנזכר ב\"צמח דוד\" שהרביץ תורה בימי ר שכנא ומכונה \"ר זעלקלא ראש ישיבה בפרג\"."},{"i":19303,"n":"זלר, דוד מליסקא","f":"משה מנחם","k":"בעל קול דוד","bt":"תרי","dt":"תרעב","b":"דרשן נודד. חיבר \"קול דוד\" למברג תרנד, \"מגן דוד\" למברג תרנו."},{"i":19304,"n":"זלר, יצחק מוארשא","f":"משה מנדל","k":"בעל ילקוט יצחק","b":"רב ומלמד תורה בוארשא. חיבר גם \"שערי יצחק\"."},{"i":19305,"n":"זלר, משה משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":19306,"n":"זלר, עקיבא משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":19307,"n":"זמבא, מנחם מפראגא","f":"ר\"א","k":"בעל אוצר הספרא","r":"כת\"י – כנראה אבד בשואה","bt":"תרמד","dt":"תשג - יט ניסן","b":"חתן ר חיים ישעיה צדרבוים. מגדולי חכמי הדור בוארשא, חבר בועד הרבנים שם-תרצה. פרסם מאמרים ב\"דגל התורה\" - וארשא תרפב, \"קול תורה\" - פאביאניץ תרפו, \"תלפיות\" - נ\"י תשד. נהרג בזמן מרד גיטו וארשא. בנו - ר משה יהודה אריה בעל \"גור אריה יהודה\".","bk":[["אוצר הספרא - ספרא",""],["זרע אברהם - שו\"ת",""],["מחזה למלך - רמב\"ם",""],["מנחם ירושלים – קדשים",""]]},{"i":19308,"n":"זמבא, משה יהודה אריה ליב","f":"מנחם","k":"בעל גור אריה יהודה"},{"i":19309,"n":"זמברובסקי, יהושע הלוי מוארשא","f":"ישראל יצחק","k":"בעל חמדת יהושע","bt":"תרלד","dt":"תרצט - יא אלול","b":"רב בוארשא, סירקוז-נ\"י, באפלו-תרפג. חיבר \"חמדת יהושע\" סט לואיס תרצג, \"עטרת יהושע\"."},{"i":19310,"n":"זמברובסקי, ישראל יצחק הלוי","k":"בעל רביד הזהב","bt":"נדפס ה'תרנה","dt":"אחרי ה'תרנה","b":"רב בווארקא, דומ\"צ בוארשא-תרמ","bk":[["גרש כרמל",""]]},{"i":19311,"n":"זמודזאק, ברוך יעקב מדברעץ","dt":"תשג","b":"חתן ר חיים בער גרינגרוס מקרמנצוג. רב בדברעץ"},{"i":19312,"n":"זמור, יהודה מאלגיר","bt":"שך","dt":"שץ - בערך","b":"תלמיד ר שלמה בן צמח דוראן-רשב\"ץ האחרון. רבה של ביסקרא-אלגיר, גדול בנגלה ונסתר. התכתב עם רבו."},{"i":19313,"n":"זמור, משה מאלגיר","bt":"תמ","dt":"תקי - בערך","b":"דיין בקצמטינא. נזכר יחד עם ר שלום גיג ב\"פרי צדיק\" לרי\"ש צרור מאלגיר המביא תשובה ממנו."},{"i":19314,"n":"זמור, משה מתונס","f":"פריג'א","k":"בעל בן מז\"ה","b":"דיין בתונס-תרם. חיבר \"בן מז\"ה\" על המדרשים והו\"ל ר אברהם דידי עם הוספות."},{"i":19315,"n":"זמור, נתן מאלגיר","b":"רב בביסקרא-אלגיר. פנה בשאלות לר שלמה בן צמח דורן-רשב\"ץ האחרון."},{"i":19316,"n":"זמורה, ישראל","f":"אהרן","k":"הו\"ל שירי יהודה הלוי","b":"הו\"ל שירי רבי יהודה הלוי עם מבוא - תל אביב תשו."},{"i":19317,"n":"זמטר, שלמה מאלטונא","f":"יהודה ליבש מזאמטר","dt":"תקעד - יד שבט","dp":"אלטונא","b":"דיין באלטונא והיה נציג הקהלה בזמן התפרדות קהלות אה\"ו-תקעב יחד עם ר מאיר הכהן."},{"i":19318,"n":"זמיל, צבי מזורובנא","b":"דיין בזורובנא-תרטו."},{"i":19319,"n":"זמירו, אברהם ממגניסיאה","b":"רב במגניסיאה-תלב."},{"i":19320,"n":"זמירו, אברהם מספרד","f":"מאיר","b":"משורר מחכמי מלגה-ספרד, לאחר הגירוש הגיע לכהן כרב בתלמסאן-רפ, אסרי. נזכר בסיפור ר דוד ראובני שר אברהם שלח אליו אגרת מפאס. ראה גם: ר אברהם ן זמרא."},{"i":19321,"n":"זמירו, דוד מפאס","b":"נגיד בפאס בזמן הרבנים בעלי התקנות, חתם-שנח בספר התקנות עם חבריו - ר משה הלוי, ר יעקב רותי, ר יצחק גיקטיליא."},{"i":19322,"n":"זמירו, זכריה מירושלים","dt":"תקצח","dp":"ירושלים","b":"מחכמי ירושלים ופרנס בזמנו של ר משה עייאש, חתום עם רבני ירושלים החל משנת תקעד. בשנת תקצו בשליחות."},{"i":19323,"n":"זמירו, יהודה ממרוקו","b":"דיין מחכמי מרוקו-שיו, נזכר ב\"שמות הגיטין\" ליעב\"ץ."},{"i":19324,"n":"זמירו, יוסף מירושלים","f":"זכריה","k":"בעל דברי דוד והון","dt":"תרג - א סיון","dp":"ירושלים","b":"תלמיד ר מנחם בן אברהם מירושלים. מחכמי ירושלים, דיין בבית דינו של ר יעקב משה עייאש, חתם על הסכמות שונות משנת תקעד. בשנת תקעה בשליחות לאירופה, והסכים שם לספר \"קבוצת כסף\" לר מרדכי שמואל גירונדי. חיבר \"דברי דוד והון יוסף\" ליוורנו תקפח. בשנת תקנד היה בפאס (מרוקו) והסכים על ספר \"פתח הבית\" לר אברהם בלעיש."},{"i":19325,"n":"זמירו, יוסף ממצרים","b":"מגדולי רבני מצרים-ק\"פ"},{"i":19326,"n":"זמירו, יצחק מטיטואן","b":"מחכמי טיטואן-מרוקו, חתם על פס\"ד עם ר יוסף ביבאס. בזמן ר יחיא בירדוגו - שעבר לטיטואן-שסט."},{"i":19327,"n":"זמירו, מאיר מירושלים","dt":"תקמז - יז ניסן","dp":"ירושלים?","b":"אביו של ר זכריה וסבו של ר יוסף פרנס קהילת ירושלים."},{"i":19328,"n":"זמירו, שלמה משלוניקי","dt":"רץ - ב אב","dp":"שלוניקי","b":"מחכמי שלוניקי, נפטר צעיר."},{"i":19329,"n":"זמלמן, יעקב יהודה ליב","f":"יוסף אלכסנדר","bt":"תריז","b":"רב בסלעשין-פלך קאליש-תרנד, דרבנין-פלך פלאצק."},{"i":19330,"n":"זמלמן, ישראל מסטנוב ובאלטא","f":"אריה","bt":"תרה","b":"רב בסטאנוב-תרלה, באלטא-פודוליה-תרמו."},{"i":19331,"n":"זמסקי, אברהם יהושע השל מפרילוב","f":"חיים הכהן","bt":"תרלה","bp":"סטרידוב-פלך צרניגוב","b":"שם המשפחה על שם מקום מוצאם - זאמוט. תלמיד וחתן ר טוביה ממינא-פלך צרניגוב. רב בהרדץ(=האראדעץ)-פלך מוהילוב-תרנט, זלאבין-תרסח, פרילובקה(=פרילוקא)-פלך פולטובה-תרע. נסמך מאת: ר רפאל שפירא מוולוזין, אדמורי חב\"ד."},{"i":19332,"n":"זמצ'יק, יעקב","bt":"תרמט","dt":"תשג","b":"ועד הרבנים בוורשה-תרצ\"ד"},{"i":19333,"n":"זמרא ן, אברהם מאלגיר","f":"מאיר","b":"משורר, פילוסוף, ממגורשי ספרד, רב בתלמסאן, ווהראן(=אוראן), סאפי(=אסאפי). לדעת ר יצחק רוש הוא ר אברהם סמרה (מעיר סמרה-ספרד) שחיבר מאמר על שכר ועונש - בכת\"י. ראה גם: ר אברהם זמירו."},{"i":19334,"n":"זמרא ן, אברהם מאלגיר","bt":"תר","dt":"תרף - בערך","b":"רב באל אסנאם(=אורליאנוויל)-אלגיר. סייע בהדפסת \"בית שלמה\" ירושלים תרנב מאת ר א\"ש פרידמן."},{"i":19335,"n":"זמרא ן, אברהם מטיטואן","b":"מו\"ץ בטיטאון-ש', יחד עם ר יעקב הלוי ור חנניה ארובאץ ור אברהם ן זמרא. חתם עם ר חיים בן יוסף ביבאס. חתנו - ר שלמה אבודרהם"},{"i":19336,"n":"זמרא ן, אפרים מתלמסן","b":"מגדולי חכמי דורו בתלמסאן"},{"i":19337,"n":"זמרא ן, דוד - רדב\"ז","f":"שלמה","k":"רדב\"ז","bt":"רמ","bp":"זמורה - ספרד","dt":"שלג-מט-כא חשון","dp":"צפת","b":"לאחר גירוש ספרד הגיע לצפת, למד אצל ר יוסף סארגוסי ואצל ר לוי בן חביב ואצל ר יוסף טאיטצאק, היה גם בירושלים, נדד לפאס ולאלכסנדריה-רעב, וקהיר שם ישב כארבעים שנה, היה בבית דינו של ר יצחק שולל הנגיד האחרון. ולאחר מכן היה ראש הרבנים במצרים (משבוטלה משרת הנגיד). עסק במסחר בתבואה - על מנת שלא להתפרנס מהרבנות, החזיק ישיבה גדולה ובין תלמידיו היו ר בצלאל אשכנזי, הארי, בין תקנותיו היה חדוש התפלה בלחש בשמונה עשרה (בניגוד לתקנת הרמבם). בשנת שיד הגיע לירושלים, ובגלל התנכלות המושל עבר לצפת, בימי ר יוסף קארו ור משה מטראני, שהושיבוהו בראש. תשובותיו בדפוס לבד מגיעות לכמה אלפים, ענה לשאלות מכל מרכזי התורה ומכל החכמים בני זמנו. חיבר פירוש לרמב\"ם, חדושים לתלמוד (בתוך שיטה מקובצת), כללי הגמרא, מגן דוד, מצודת דוד ועוד בדפוס ובכתב יד. נפטר בהיותו כבן מאה ועשר שנים"},{"i":19338,"n":"זמרא ן, דוד מטיטואן-מרוקו","b":"מחכמי טיטואן, חתם על שטר עם ר מימון אדהאן, ר אברהם אלמושנינו, ר משה ביבאס."},{"i":19339,"n":"זמרא ן, דוד מתלמסן","b":"רב בתלמסן"},{"i":19340,"n":"זמרא ן, יהודה","b":"רב במלאגה"},{"i":19341,"n":"זמרא ן, יעקב מפאס","f":"חיים ן זמרא","bt":"תקפו","b":"מגדולי חכמי פאס"},{"i":19342,"n":"זמרא ן, יצחק מטיטואן","b":"מחכמי טיטואן. תוכחה לזכרו מאת ר יהודה ן צור."},{"i":19343,"n":"זמרא ן, יצחק מנדיל מאלגיר","f":"אברהם מאלגיר","b":"רב ומשורר בתלמסאן-אלגיר ולפי מלכי רבנן היה בעיר פאס-שסט. חיבר קינה על פטירת ר אברהם גבישון וחיבר הקדמה ל\"עומר השכחה\" ושיר סימנים לששים המסכתות. בנו ר מרדכי בן מנדיל."},{"i":19344,"n":"זמרא ן, מאיר מספרד","bp":"ספרד","b":"רב ומשורר ממגורשי ספרד, עבר לתלמסאן-אלגיר עם חברו ר אברהם גבישון בעל \"עומר השכחה\". בנו - ר אברהם."},{"i":19345,"n":"זמרא ן, מנדיל","bt":"שלד","bp":"תלמסאן","b":"חברו של ר אברהם גבישון בעל \"עומר השכחה\" המזכירו בספרו ומביא פיוטים ושירים ממנו."},{"i":19346,"n":"זמרא ן, מרדכי מאלגיר","f":"מנדיל (יצחק)","bt":"ש - בערך","dt":"שע - בערך","b":"רב ומשורר באלגיר. חיבר הפיוט \"אהמה בנודי לנודי\"."},{"i":19347,"n":"זמרא ן, משה מטיטואן","b":"רב בטנג'יר, טיטואן, חתם על פס\"ד-תעג עם ר מנחם עטייה."},{"i":19348,"n":"זמרא ן, משה מפאס","f":"אברהם","dt":"תקלח - טז תשרי","dp":"פאס","b":"רב ודיין בפאס עם ר אליהו הצרפתי שהספידו ב\"נער בוכה\", נספד גם מאת גיסו - ר אברהם מאנסאנו. נמנה בין חברי בית הדין של חמש בפאס - לאחר שר אפרים מונסוניגו עבר לטיטואן (החברים היו: ר שאול שמואל דנון, ר אפרים בן אברהם מונסונייגו, ר רפאל עובד בן יעקב ן צור, ר אליהו בן יוסף הצרפתי, ר מתתיהו בן מנחם סירירו). בנו - ר שמואל אברהם מפאס."},{"i":19349,"n":"זמרא ן, רחמים חיים דוד מפאס","f":"שמואל אברהם","dt":"תרח - כז חשון","dp":"פאס?","b":"אב\"ד בפאס-תקץ על מקום אביו. חיבר שו\"ת בכת\"י."},{"i":19350,"n":"זמרא ן, שמואל אברהם ממרוקו","f":"משה מפאס","bt":"תצז","dt":"תקץ","dp":"פאס?","b":"רב בפאס-תקס ובנו - ר רחמים חיים דוד על מקומו אחריו, ודיין עם ר חיים דוד סירירו, ר יהונתן סירירו, ור רפאל אהרן מונסונייגו. (לפי מלכי רבנן - שם אביו - אברהם)."},{"i":19351,"n":"זמרהויזן, צבי הירש מבלגיה","f":"שמעון","k":"בעל חצים שנונים","b":"דוקטור לפילוסופיה בבלגיה. חיבר גם \"דעת דורות\" לקורות עם ישראל בעברית וצרפתית - בריסל 1842."},{"i":19352,"n":"זמרון, יוסף מאלגיר","f":"אברהם","bt":"קפ","dt":"רס - בערך","b":"תלמיש הרשב\"ש באלגיר. מחכמי בג'איה-אלגיר, רב בקצמטינא, תונס. היה בקשרי מכתבים עם ר צמח בן הרשב\"ש. חיבר שיר לספר \"תיקון סופרים\" לרשב\"ש - והרשב\"ש ענה לו. חיבר שו\"ת \"אבני שוהם\" - ואבד. תשובה ממנו ב\"בית יוסף\", בשו\"ת המבי\"ט, ועוד. בנו - ר יהודה - דיין אצל ר נתן שולאל במצרים."},{"i":19353,"n":"זמרוני, ש' מדעווא","b":"מחכמי דעווא-רומניה. עורך הירחון \"הבחור\" - דעווא תרפח. פרסם מאמרי פולמוס כנגד ר יוסף שמעון פאלק מסטמר עורך \"בית ועד לחכמים\" שהיה מחלוקת ביניהם."},{"i":19354,"n":"זנבור, יצחק מבוכרה","b":"תלמיד ר יוסף מאמן (מערבי). רב בבוכרה, למד קבלה עם ר פנחס הכהן רבין."},{"i":19355,"n":"זנגר, יוסף","dt":"תשג","b":"רב באוסרוב-מאז"},{"i":19356,"n":"זנגר, שלמה זלמן מדוקלא","b":"פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":19357,"n":"זנגר, שמואל","bt":"1866","bp":"זאגר-ליטא","b":"סופר ודיפלומט בגרמניה. פרסם מאמר ב\"צוקונפט\" ובו יוצא כנד פ.ס. צמברלין שטען שישו לא היה ממוצא יהודי - התפרסם בעקבות המאמר, ונתמנה לפרופ' בברלין. עורך \"די נוייע רונדשוי\". שגריר גרמניה בפרג-1920 - היהודי הראשון בתפקיד שגריר. ויועץ סתרים במשרד החוץ הגרמני. היגר לארה\"ב עם עלית הנאצים."},{"i":19358,"n":"זנגר-פירטה, אברהם אבא מקראלי","f":"נתן הכהן זנגר מבירוט","bp":"פיורדא","dt":"תרמא - כח טבת","dp":"קראלי","b":"תלמיד החת\"ס. חתן ר זאב וולף סימאנדל מקראלי, רב בקראלי על מקום חותנו. בנו ר מיכל כץ זנגר מירושלים."},{"i":19359,"n":"זנדר, יצחק מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":19360,"n":"זנויל","b":"דיין בברלין"},{"i":19361,"n":"זנויל ליב","f":"אליהו","k":"בעל שלמה מול אדר","b":"חיבר \"שלמה מול אדר\" בשני חלקים - \"אדרת שער\", \"אור כשלמה\" - וארשא תקעד."},{"i":19362,"n":"זנויל מוילנא","b":"מגדולי חכמי ווילנה-שנת ת'. נזכר ב\"פני יהושע\". חתנו - בעל חלקת מחוקק."},{"i":19363,"n":"זנויל מפרשבורג","dt":"תקח - כה תשרי","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":19364,"n":"זנויל, שמואל ממונקאטש","b":"פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":19365,"n":"זנזורי, יהודה מלוב","bt":"תרסה","bp":"כומס-לוב","dt":"תשנג","dp":"ישראל","b":"ראש ועד הקהל במצראתה-לוב, עבר לטריפולי, עלה לארץ-תשכט."},{"i":19366,"n":"זסלבסקי, אליהו מקרמנצוג","b":"חתן ר שניאור זלמן בעל התניא (ולפי אלפסי חתן ר משה בנו של בעל התניא). בנו - ר אהרן מקרמנצוג."},{"i":19367,"n":"זסלבסקי, יוסף מבוהוסלב","f":"אשר למל","bt":"תרכו","b":"חתן ר בן ציון משינדעריבקא. רב בשינדריבקה-תרמ, בוהיסלאב-תרנה. נסמך מאת: ר חיים ברלין, ר דוד מטולנא, ר יוחנן מרחמיסטריבקא. חיבר ספר חדושים וכללים בש\"ס."},{"i":19368,"n":"זסלנסקי, אהרן יצחק מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\". מעורכי \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - ירושלים תשא-תשח."},{"i":19369,"n":"זסקביצר, יוסף מוילנא","f":"שמואל מזסקביץ","dt":"תקפט - ו תמוז","dp":"וילנא","b":"מחכמי זסקביץ, וילנא. חתן ר אליהו מוולוזין וסמרגון. בנו - ר שמואל שטרשון. נקבר לצד אחיו - ר ברוך."},{"i":19370,"n":"זעבאג, חיים מאלגיר","bt":"ר","dt":"רע - בערך","b":"דיין בווהראן על מקום ר סעדיה נגאר שעבר לתלמסאן. החליף אגרות עם ר שמעון דוראן בן הרשב\"ש."},{"i":19371,"n":"זעבאג, שלמה מאלגיר","f":"חיים","bt":"רך - בערך","dt":"רץ - בערך","b":"רב באלג'יר. תשובה אליו ב\"יכין ובועז\" לר צמח בן הרשב\"ש."},{"i":19372,"n":"זעבוקא, יוסף מאבילונא-אלבניה","b":"מחכמי פורטוגל, אחרי הגירוש מחכמי אבילונא-אלבניה."},{"i":19373,"n":"זעבל, יוסף מטרנוב","f":"משלם פיבל","k":"בעל לקוטי אור","b":"חיבר \"לקוטי אור\" למברג תרלט. ?? לא באוצר ??"},{"i":19374,"n":"זעבסיל, זכריה אשכנזי","f":"שלמה","b":"מחכמי ירושלים ורבה של הקהלה האשכנזית בדורו של הרדבז. אביו מתואר הקדוש וכנראה שנהרג על קדוש השם. היה חותנו של ר יוסף קארו בזיווג שלישי, ר יוסף קארו מכנה את רבי זעבסיל, מורי חמי וכו' ומזכירו כמה פעמים בתשובותיו. יתכן שהיה נכדו של ר זכריה ורנק."},{"i":19375,"n":"זעדלו, חיים שמואל הלוי ממרוקו","b":"מחכמי מרוקו-תקעט."},{"i":19376,"n":"זעהמן, דוד מדוקלא","k":"בעל מנחת סולת","b":"רב בדוקלא-ת\"צ."},{"i":19377,"n":"זעהמן, דוד צבי טעביל מדוקלא","f":"אליקים גצל","k":"בעל קב זהב","bt":"תרכד","bp":"סטרי","dt":"תשב","b":"תלמיד ר זאב וולף המר מסטרי, ר אריה ליב הורביץ בעל \"הרי בשמים\", ר יצחק שמלקיש מלבוב. חתן ר יוסף משה טייכר מפשמישל. דיין בפשמישל. ראב\"ד דוקלא-תרנב. נספה בשואה. חיבר \"קב זהב\" מונקטש תרנט, \"מנחת סולת\". נקרא פעם לוינה לפתור משפט בין גויים שנמשך 24 שנה. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"אהל תורה\" - קראקא תרפח, \"אסיפת גדולים\", \"אסיפת חכמים\" - אושפצין תרצד, \"הנשר\" - טירנוי תרצג-תשד. נכדו - ר פנחס הירשפרונג ממונטיראול."},{"i":19378,"n":"זעהמן, יוסף משה מצאנז","b":"מחכמי צאנז חדש-תרפח, חתן ר נפתלי נאטעל. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":19379,"n":"זעהמן, ראובן","dt":"תשג","b":"רב באוטואצק"},{"i":19380,"n":"זעהמן, ראובן מארה\"ב","k":"בעל יחי ראובן","b":"רב בארה\"ב-תרצז."},{"i":19381,"n":"זעזמיר, דוד מוילנא","f":"צבי הירש מזעזמיר","dt":"תרכט - כו טבת","dp":"וילנא","b":"נכד ר דוד בן יחיאל מיכל מו\"צ בוילנא הנקרא ר דוד קענדעס. פרנס ומנהיג הקהלה בוילנא."},{"i":19382,"n":"זעזמיר, מיכעלע מוילנא","f":"צבי הירש מזעזמיר","dt":"תרכט - טז כסלו","dp":"וילנא","b":"נכד ר דוד בן יחיאל מיכל מו\"צ בוילנא הנקרא ר דוד קענדעס. פרנס בוילנא. אחיו של ר דוד זעזמיר פרנס בוילנא. חתנו ר יוסף עקיבא קוסובסקי מוילנא."},{"i":19383,"n":"זעלקי מקראקא","dt":"תקמב - כט אייר","b":"דיין בקרקא"},{"i":19384,"n":"זעפרן, משה מאלגיר וירושלים","dt":"תקסה-ח -כב אייר","dp":"ירושלים","b":"גביר מחכמי אלגיר, דיין בירושלים. יסד ישיבה בירושלים \"בני משה\". הסכים על \"מראה האופנים\"-תקסו."},{"i":19385,"n":"זעפרני, שלום ממרוקו","dp":"תארודנת-מרוקו","b":"מחכמי מרוקו."},{"i":19386,"n":"זעפרני, שלמה סלי מחלב","bt":"תרנא","bp":"חלב","dt":"תשכה - כב שבט","b":"תלמיד ר עזרא שעיו, ר\"מ בישיבה ודיין עם ר משה מזרחי ור משה מעלי וטטיל הכהן. עלה לארץ-תשיט. מתלמידיו ר יצחק שחיבר - רב בארגנטינה, ור שחוד שרים - רב בלבנון ובסאן פאולו-ברזיל."},{"i":19387,"n":"זעקל","dt":"תקעה - ל חשון","b":"רב בבאייא"},{"i":19388,"n":"זפראני, משה מאלגיר","dt":"תקסה - כב אייר","dp":"ירושלים","b":"רב דיין וגביר מחכמי אלגיר, עלה לירושלים והקים בה ישיבת \"בני משה\" וסייע בהחזקתה. (אצל גליס תאריך הפטירה - תקעה)."},{"i":19389,"n":"זפרין, זלמן","b":"תלמיד ר\"י שמלקיס שהשיב לו ב\"בית יצחק\"."},{"i":19390,"n":"זפרין, ישראל איסר זלמן מבלשביץ","dt":"תרס - בערך"},{"i":19391,"n":"זפרן, משה","dt":"תקסח - כב אייר","b":"דיין בירושלים"},{"i":19392,"n":"זפרנא, אברהם","f":"גבריאל בן מרדכי","b":"מחכמי קורפו-ר'. חיבר פיוטים ונכנסו למחזור קורפו."},{"i":19393,"n":"זפרני, שלום","b":"מגדולי רבני ארם צובה"},{"i":19394,"n":"ז\"ק, אבלי מלודמיר","f":"שמחה בונם ז\"ק","b":"רב בלודמיר"},{"i":19395,"n":"ז\"ק, אברהם","b":"למד קבלה עם הבעש\"ט-ת\"ק"},{"i":19396,"n":"ז\"ק, אברהם - האח הגדול","f":"מאיר מלבוב","dt":"תה - טז תשרי","dp":"לבוב","b":"בזיוו\"ש חתן ר נתן שפירא בעל מגלה עמוקות (אלמנת ר צבי הירש בן חיים שור). רב בבאר, ראש ישיבה בלבוב. נפטר צעיר בחיי אביו - ולאביו נולד בן אחר פטירתו ונקרא ע\"ש אברהם והיה רב באוסטרהא."},{"i":19397,"n":"ז\"ק, אברהם אבא הכהן מאלשאד","f":"אריה ליב","bt":"תרכב","bp":"לוקניק","dt":"תשא - ז אלול","b":"נסמך מאת: ר יצחק אלחנן מקובנא. רבה האחרון של אלשאד(=אלסיאד)-תרן - מעל 50 שנה. לאחר מלחה\"ע ה-I פעל לשיקום העיירה. נספה בשואה. חתניו: ר שמואל יעקב רבינוביץ בעל \"מבצרי הדת\", ר משה שמואל שמוקלר בעל \"תולדות הגר\"ח מוולוזין\"."},{"i":19398,"n":"ז\"ק, אברהם מאוסטרהא - הזקן","b":"תלמיד המהרש\"ל. אב\"ד באוסטרהא. אביו של ר מאיר מלבוב, וזקנו של ר אברהם שהיה ראש ומנהיג באוסטרהא. נזכר ב\"טיב גיטין\" - כמה פעמים. ור\"י כהן צדק בעל \"שם ושארית\" סובר שאולי הוא ר אברהם דרוסיא שהשלים ספר רבו \"ים של שלמה\" למסכת ב\"ק."},{"i":19399,"n":"ז\"ק, אברהם מאוסטרהא - הנכד","f":"מאיר מלבוב","bt":"תה - אחרי","b":"נולד אחר פטירת אחיו ר אברהם מבאר ולבוב - ונקרא על שמו. ראש ומנהיג באוסטרהא, אחיו ר שמואל שמלקא אב\"ד אוסטרהא. בניו ר יעקב שמחה בונם מאוסטרהא, ר מאיר-חתן ר יעקב מפוזנא, ר שמואל זנויל מאוסטרהא. (אולי הוא שנפטר באוסטרהא תעט)."},{"i":19400,"n":"ז\"ק, אברהם מפטרבורג","f":"יצחק","dt":"תרנג - אייר","dp":"ברלין - גיסען","b":"נכד ר שמעון זימל בן יחיאל מיכל אפשטין מוילנא. גביר ומנהל בנק בפטרבורג, בעל תואר \"יועץ מדיני בפועל\" מהממשלה. נדב לצדקה מדי שנה 60,000 רובל לעניי ישראל."},{"i":19401,"n":"ז\"ק, אברהם משדה לבן","f":"מאיר מלכוביץ","b":"אב\"ד שדה לבן. הסכים על \"בית פרץ\" זולקווא תקיט. מתורתו ב\"דברי רב משלם\" קורץ תקמג."},{"i":19402,"n":"ז\"ק, אלחנן נתנאל מסלונים","b":"מו\"ץ בסלונים, חתם-תרסד על כרוז לטובת כולל רייסין בירושלים, עם ר יהודה בן משה יצחק מסלונים."},{"i":19403,"n":"ז\"ק, אליהו משידלוב","k":"בעל עטרת אליהו","b":"מחכמי וינה-תקיד, רב בשידלוב-תקכ. חיבר \"עטרת אליהו\" ונדפס ע\"י בנו ר צבי הירש - תקלו. לפי פעסיס בנו גם ד\"ר שלמה רוזנברג."},{"i":19404,"n":"ז\"ק, אליעזר ליפא מרוזינאי","f":"צבי הירש ז\"ק","dt":"תקכה - כז אייר","b":"דיין ברוזינאי"},{"i":19405,"n":"ז\"ק, אליעזר מוילנא","f":"אשר בן משלם זלמן","dt":"תקנא","dp":"וילנא","b":"נכד ר משלם זלמן מפוקרוי. מחכמי וילנא."},{"i":19406,"n":"ז\"ק, אשר מוילנא","f":"משלם זלמן מפוקרוי","dt":"תקנו - יז אב","dp":"וילנא","b":"מחכמי וילנא, נפטר בחיי אביו."},{"i":19407,"n":"ז\"ק, אשר צבי מפראבישטא","f":"אברהם-חבר הבעש\"ט","b":"רב בפראביטשע-תקל. נכדו - ר אליעזר ז\"ק."},{"i":19408,"n":"ז\"ק, בן ציון מקובנא","f":"ישראל בן משלם זלמן","b":"גביר בקובנא. בניו - ר משה נתן מקובנא, ר חיים צבי מקובנא, ר אשר יעקב מקובנא. חתנו - ר חיים יעקב שפירא מקובנא."},{"i":19409,"n":"זק, בנימין גוטל","bt":"1889","bp":"אבאל-ליטא","b":"היגר לקנדה. עתונאי ב\"קענעדער אדלער\". פרסם מאמרים בעתוני התקופה. תרגם ספרים לאידיש. חיבר ספר על תולדות היהודים בקנדה."},{"i":19410,"n":"ז\"ק, בנימין זאב מוילנא","b":"תלמיד וחתן ר יעקב מלובלין. רב בוילנא-תח. מחותן עם בעל ר אפרים הכהן בעל שער אפרים - בנו ר יעקב היה חתנו."},{"i":19411,"n":"ז\"ק, ברוך יוסף מקוברין","f":"ישראל מקרוסילוב","k":"אדמור מקוברין נ\"י","bt":"תרמז","bp":"קרוסילוב-ווהלין","dt":"תשט - טז סיון","b":"תלמיד דודו ר שלום בוש מקרוסילוב, תלמיד וחתן ר דוד שלמה רבינוביץ האדמור מקוברין. עלה לארץ-תרעג, הוגלה למצרים-תרעה, עבר לארה\"ב וכיהן כאדמור מקוברין בניו יורק. חיבר \"ברכת יוסף\" נ\"י תרעח, \"שכל טוב\"."},{"i":19412,"n":"ז\"ק, דוד מאמדור","f":"ישראל ז\"ק","b":"רב באמדור-ת\"ק"},{"i":19413,"n":"ז\"ק, חיים מבירז","f":"שלום או ישראל מבירז","dt":"תקס","dp":"וילנא","b":"נכד ר ישראל הקדוש מראזינאי. רב בבירז והגליל על מקום אביו, ובנו ר יצחק על מקומו אחריו. (לפי ליפמן היה בנו של ר שלום ואחיו של ר ישראל - ולפי אחרים היה בנו של ר ישראל ונכדו של ר שלום). בניו - ר יצחק, ר משלם זלמן מפאקראי, ר ישראל מבירז."},{"i":19414,"n":"ז\"ק, חיים מזאגר","bp":"ליטא","b":"מחכמי זאגר-ליטא, בקי במדעים ופילוסופיה ושלט בעשר שפות. סייע לל. מנדלשטם בתרגום הרמב\"ם לגרמנית. דודנו של שלמה זלקינד אלישיב. הניח חבורים רבים בכת\"י."},{"i":19415,"n":"ז\"ק, חיים מזולקוא","f":"מרדכי מברעזן","b":"מחכמי זולקוא. נכד ר מאיר מלבוב. בנו - ר מרדכי-דיין בזולקוא."},{"i":19416,"n":"ז\"ק, חיים מראזינאי","f":"צבי","b":"דיין בראזינאי-ת\"צ"},{"i":19417,"n":"ז\"ק, יהושע אהרן מלבוב וטולטשין","f":"מאיר מלבוב","dt":"תיא - יב טבת","dp":"לבוב","b":"מגדולי חכמי לבוב, אב\"ד טולטשין. יש אומרים כי היה רב בפולדא ונהרג שם עק\"ה. בנו - ר יקותיאל מחעלם."},{"i":19418,"n":"ז\"ק, יהושע זליג מהומל","f":"משה","k":"בעל ליקוטי תורה","bt":"תר","b":"נכד ר ברוך מרדכי אטינגר(=איטינגא) מבוברויסק. רב בלאייאוו-מוהילוב-תרם, הומל(=האמעל). הו\"ל סידור עם פירוש \"ליקוטי תורה\" בדרך החסידות."},{"i":19419,"n":"ז\"ק, יחזקאל מזולקוא","f":"מאיר","b":"מראשי קהלת זולקוא, חתם-תנב, תנד, תסד, תסה - על תקנות הקהלה."},{"i":19420,"n":"ז\"ק, יעקב מוילנא","f":"אשר בן משלם זלמן","dt":"תקעב","dp":"וילנא","b":"נכד ר משלם זלמן מפוקרוי. מחכמי וילנא."},{"i":19421,"n":"ז\"ק, יעקב מוילנא וירושלים","f":"בנימין זאב","k":"אבי החכם צבי","bt":"שפב או שעב","bp":"וילנא","dt":"תנה-ח","dp":"ירושלים","b":"תלמיד ר יעקב אב\"ד לובלין (אביו של ר העשיל). רב בטריויטש, ברח בזמן גזירות ת\"ח ות\"ט למהרן וכיהן כרב בברוידא. חתן ר אפרים הכהן בעל \"שער אפרים\" ראבד וילנא, ומילא מקום חותנו בקהילת אופין. נפל בשבי במלחמה עם נפילת העיר ברוידא בידי הצבא האוסטרי ונפדה בברלין. רב באלטונה. חתן ר אפרים הכהן מבודה בעל \"שער אפרים\". משום מעשה שקרה לו בזמן גזרות תח תט, סירב לעסוק בעניני עגונות (נחשב להרוג ור השל מלובלין התיר את אשתו - והספיק לחזור אל חותנו - ומאז סירב ר השל לדון בדיני עגונות). עלה לירושלים ולאחר פטירת אשתו הכריחוהו חכמי ירושלים לשאת אשה ונשא את בתו של ר נפתלי כץ מפרנקפורט. מתלמידיו: ר דוד אופנהיים. בנו: ר צבי אשכנזי \"חכם צבי\". (הואשם ע\"י גרץ ורוזניס בשבתאות - ופרומקין הגן עליו)."},{"i":19422,"n":"ז\"ק, יעקב מלודמיר והוסיאטין","f":"אבלי מלודמיר","b":"רב בלודמיר,הוסיאטין-ת\"י"},{"i":19423,"n":"ז\"ק, יעקב שמחה בונם מאוסטרהא","f":"אברהם מאוסטרהא -הנכד","dt":"תנח - י אב","dp":"אוסטרהא","b":"נכד ר מאיר ז\"ק מלבוב. מחכמי אוסטרהא. דודו היה ר שמואל שמלקא אב\"ד אוסטרהא. בנו - ר שמואל שמלקא מאוסטרהא שהיה מאלופי הח\"ק ונזכר בפנקסי הח\"ק-תפח."},{"i":19424,"n":"ז\"ק, יצחק איזיק מפרמישלא","f":"שמואל שמלקא מאוסטרהא","b":"חתן בעל \"מגיני שלמה\" ו\"פני יהושע\". רב בפרמישלא."},{"i":19425,"n":"ז\"ק, יצחק מבירז ופוסוואל","f":"חיים מבירז","b":"רב בפאסוואל(=פוסבול), זאמוט, בירז'-תקל על מקום אביו, ואחיו ר ישראל חריף על מקומו אחריו (ולפי ליפמן-קובנא - חתנו ר אברהם שלמה-אביו של ר אבלי פוסוואלר על מקומו אחריו). בנו - ר צבי הירש משקוד, חתנו - ר גרשון מלובלין ואניקשט, נכדו - ר אברהם שלמה מוילנא ונינו - ר אברהם אבלי מוילנא."},{"i":19426,"n":"ז\"ק, יצחק משקוד-ליטא","f":"צבי הירש משקוד","b":"רב בשקוד-תקמח-תקסא. נזכר בשו\"ת ר עקיבא איגר."},{"i":19427,"n":"ז\"ק, יקותיאל מחעלם","f":"יהושע אהרן מטולטשין","dp":"לבוב","b":"אב\"ד חעלם. בנו - ר בנימין זאב בעל \"ענף עץ אבות\"."},{"i":19428,"n":"ז\"ק, ישכר בר מרוזינאי","f":"משה ז\"ק","b":"ראב\"ד ברוזינאי-תקכ\"ט"},{"i":19429,"n":"ז\"ק, ישראל מבירז","f":"שלום מבירז","b":"חתן ר יוסף יוסקי מדובנא. רב בזבלודאווי(=זאבלודובה), בירז'-תק עד תקה (לפי אוצר הרבנים מ-תפה) על מקום אביו (ולפי ליפמן-קובנא - על מקום קרובו - ר אברהם שלמה), ובנו ר חיים על מקומו אחריו (לפי ליפמן-קובנא אחיו ר חיים ולא בנו ולפי אווצינסקי - קורלנד המדובר באביו של ר שלום וזקנו של ר חיים - וכנראה הוא זקנו שהיה מרוזינאי ונהרג עק\"ה). חתנו - ר צבי ברוידא מהורדנא. הסכים על \"עמודי בית יהודה\" תקכו. בשליחות עם הדיין ר נתן אברהם מבירז בפטרבורג בענין התישבות היהודים ברוסיה החדשה (דרום רוסיה)"},{"i":19430,"n":"ז\"ק, ישראל מבירז","f":"חיים בן שלום מבירז","dt":"תקלח","b":"רב בבירז והגליל על מקום אחיו ר יצחק, ור אברהם שלמה בן גרשון-אביו של ר אבלי מפוסבול על מקומו אחריו. השתתף בועידה בפטרבורג בענין התישבות יהודים בדרום רוסיה בזמן יקטרינה ה-2. הסכים על \"עמודי בית יהודה\" - אמשטרדם תקכו."},{"i":19431,"n":"ז\"ק, ישראל מלוקאטש","f":"יעקב","b":"רב בלוקאטש,זילאזיץ-ת\"מ"},{"i":19432,"n":"ז\"ק, ישראל מרוזינאי הקדוש","k":"הקדוש ר' ישראל","dt":"תכ - ב תשרי","b":"רב ברוזינאי, העלילו עליו עלילת דם ונהרג עק\"ה, ממנו יצאה שושלת ז\"ק. בניו - ר שלום מבירז, ר מנחם נחום מפלאצק."},{"i":19433,"n":"ז\"ק, מאיר","f":"גרשון","bt":"1893","bp":"היידוצישוק-ליטא","dt":"1951","dp":"תל אביב","b":"בן לחסיד חב\"ד. תלמיד ישיבת לידא והחל שם בפעילות ציונית וציבורית. פעיל בעזרה לפליטי מלחה\"ע ה-I. התישב במאריאמפול והיה ראש הקהלה, וממיסדי הגימנסיה העברית. מזכיר הועד הלאומי בזמן האוטונומיה היהודית בליטא, פעיל בבנק היהודי בליטא. עלה לארץ-1933 והתישב בתלא אביב."},{"i":19434,"n":"ז\"ק, מאיר מאוסטרהא","f":"שמואל שמלקא מאוסטרהא","dt":"תע - ג תמוז","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":19435,"n":"ז\"ק, מאיר מאוסטרהא - הנכד","f":"אברהם מאוסטרהא הנכד","b":"נכד ר מאיר ז\"ק מלבוב. חתן ר יעקב מפוזנא."},{"i":19436,"n":"ז\"ק, מאיר מלבוב הזקן","f":"אברהם מאוסטרהא","dt":"תיד - כ כסלו","dp":"לבוב","b":"חתן ר חיים בן שמואל אב\"ד קרמניץ ור יהושע שמלקש. רב בלבוב, חתם-תח ונזכר ב\"איתן האזרחי\". הסכים על \"נחלת יעקב\"-תיב, \"אהבת השם\"-תח, \"מגיד מישרים\", ועוד. בניו: ר אברהם מבאר-נפטר בחיי אביו ונולד לו בן זקונים שנקרא ע\"ש אברהם והיה רב באוסטרהא, שמואל שמלקא אב\"ד אוסטרהא, ר מרדכי מברעזן, ר יהושע אהרן מטולטשין ולבוב, ר שמחה בונם, ר משה. חתנו ר מאיר בן יצחק גינצבורג מרייסין."},{"i":19437,"n":"ז\"ק, מאיר מלכוביץ ודרישהאפליא","f":"בנימין זאב - ענף עץ","b":"אב\"ד לכוביץ, דרישהאפאליע. בנו - ר אברהם ז\"ק משדה לבן."},{"i":19438,"n":"ז\"ק, מנחם מנדל (דובער) מריגא","f":"דובער או לוי יצחק","bt":"תרלא","bp":"ניירי","dt":"תשג","b":"תלמיד ישיבות ליטא, תלמיד ר יוסף דב סולוביציק. חתן ר גרשון אב\"ד ואגאר. מגדולי דורו, רב בקאנדאוי(=קנדוי)-תרנח, מיטאו-תרעג, ריגא-תרעה, רב הכולל במדינת לטביה ופעל רבות למען הפליטים בזמן מלחה\"ע ה-I. ממנהיגי אגו\"י וחבר מועצת גדולי התורה. הוזמן לכהן כרב בירושלים - מטעם אגו\"י וסירב - כדי שלא לפגוע ברב קוק. נספה בשואה. קיבל מה\"אור שמח\" את כתב היד של \"משך חכמה\", והוציאו לאור.","bk":[["שערי שמים","מפרשי רמב\"ם"]]},{"i":19439,"n":"ז\"ק, מנחם נחום מפלאצק","f":"ישראל הקדוש מרוז'נוי","dt":"תנ","b":"חתן ר יצחק מפוזנא הגדול. רב בפילא-תמב, פלוצק(=פלאצק). הסכים על \"נחלת בנימין\" אמשטרדם תמב. אחיו - ר שלום מבירז."},{"i":19440,"n":"ז\"ק, מרדכי מזולקוא","f":"חיים בן מרדכי בן מאי","b":"דיין בזולקוא בזמן ר נפתלי הרץ הורביץ."},{"i":19441,"n":"ז\"ק, מרדכי מלבוב","f":"מאיר ז\"ק","b":"מרבני לבוב-ת\"ל"},{"i":19442,"n":"ז\"ק, מרדכי מלובלין","k":"ר' מרדכי ז\"ק הקדוש","dt":"שצו - י אב","b":"רב בלובלין. נהרג עק\"ה. בנו - ר משה מונגרוב ומינסק."},{"i":19443,"n":"ז\"ק, משה מביאלה","f":"שמואל ליב ז\"ק","b":"דומ\"צ בביאלא-תר\"ע"},{"i":19444,"n":"ז\"ק, משה מוולוזין","f":"מנחם נחום","k":"בעל בינה לעתים","b":"מחכמי וולוזין."},{"i":19445,"n":"ז\"ק, משה מוונגרוב ומינסק","f":"מרדכי הקדוש מלבוב","dt":"תנו","b":"בן אחיו של ר מאיר מלבוב ולובלין. רב בוונגרוב, מינסק ויסד שם ישיבה ור ליבל בעל התוספות על מקומו אחריו. חתנו - ר יצחק בן משה כץ-נכד בעל הש\"ך. הסכים על \"נחלת עזריאל\" פפד\"א תמה, הגדת אמשטרדם תנה. נזכר בהקדמת חתנו ל\"גבורת אנשים\". חתם שמו - 'משה בהקדוש ר מרדכי הי\"ד'. (ראה גם סגל, משה ממינסק וזברז)."},{"i":19446,"n":"ז\"ק, משלם זלמן מפוקרוי","f":"חיים","dt":"תקס - יג אדר","dp":"וילנא","b":"נכד ר שלום אב\"ד בירז' והגליל, ונינו של הקדוש ר ישראל. חתן ר יוסף משה שמחה רפפורט. רב וראש ישיבה בפוקרוי(=פאקראי)-ליטא, פרש מהרבנות ועבר לוילנא. בניו - ר אשר-נפטר בחיי אביו, ר ישראל."},{"i":19447,"n":"ז\"ק, נפתלי הרץ מאוסטרהא","f":"שמואל שמלקא מאוסטרהא","dt":"תנט - כג אייר","dp":"אוסטרהא","b":"מחכמי אוסטרהא. בנו - אברהם,"},{"i":19448,"n":"ז\"ק, צבי הירש זיסקינד מלבוב","f":"נתן","dt":"תב - א ניסן","dp":"לבוב","b":"דיין בלבוב. נזכר בשו\"ת מהר\"ם מלובלין - הסכים עם המהר\"ם בענין גט שהיה מחלוקת עליו יחד עם ר שמשון בוכנר ור יעקב בן אליקום הלפרין."},{"i":19449,"n":"ז\"ק, צבי הירש מליטא","f":"יצחק מפוסוואל בן חיי","dt":"תקמח","b":"נכד ר חיים ז\"ק מבירז. רב בפאלאצק, שקוד על מקום ר אהרן הורביץ שעבר להאזענפוט, ובנו - ר יצחק בעל \"פרי יצחק\" על מקומו אחריו."},{"i":19450,"n":"ז\"ק, ראובן מאוסטילא","f":"צבי דוד","k":"בעל כנסת ישראל"},{"i":19451,"n":"ז\"ק, שלום מבירז'","f":"ישראל הקדוש מרוז'נוי","dt":"תפה","b":"חתן ר משולם זלמן מירלש אב\"ד אה\"ו. רב בבירז והגליל-תעג עד תפה ובנו ר ישראל על מקומו אחריו. חתנו - ר דוד קצנלנבוגן מקידאן ואה\"ו. אחיו - ר מנחם נחום מפלאצק."},{"i":19452,"n":"ז\"ק, שמואל זנויל מאוסטרהא","f":"אברהם מאוסטהרא -הנכד","dt":"תסח - יב חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אחיו של ר שמואל שמלקא ז\"ק - רבה של אוסטרהא."},{"i":19453,"n":"ז\"ק, שמואל ליב מביאלא","f":"חיים ישראל","b":"תלמיד ר יוסף שאול נתנזון מלבוב, האדמור מגור בעל \"חדושי הרי\"ם. רב בוולדובקה-תרלח, שברשין, ביאלא-פלך שדליץ. בניו: ר יצחק שלמה יהושע, ר אפרים דב, ירוחם דוד. חתניו: ר משה מביאלא, ר חיים יחיאל ציטרינבוים."},{"i":19454,"n":"ז\"ק, שמואל שמלקא מאוסטרהא","f":"מאיר מלבוב","dt":"תמ-ז - י ניסן","dp":"אוסטרהא","b":"נכד ר אברהם-אב\"ד אוסטרהא. חתן ר חיים אב\"ד מקרמניץ. מגדולי דורו, רב באוסטרהא-תל. היה אחד מארבעת ראשי גליל ואהלין בועד ארבע ארצות (יחד עם ר צבי הירש מלויצק, ר וולף מלודמיר, ור יצחק מקרמניץ). בנה מכספו את הקלויז הגדולה שנחרבה בפרעות-תח - ומאז נקראה קלויז רבי שמלקיס קלויז, הוא ציוה לפני פטירתו לבל יקרב איש זר אשר לא מיוצאי חלציו לשבת על כסא אב\"ד ור\"מ בקלויז הגדולה - ואכן מאז היו כל האב\"ד והרמי\"ם בקלויז הגדולה מיוצאי חלציו. בניו: ר יצחק איזיק מפרמישלא, ר מאיר, ר נפתלי הירץ (ולפי ברוורמן-אנשי שם גם ר בנימין ממיר-אביו של ר גרשון תנחום ביליצקי). חתניו: ר משה מאיר רפפורט מלבוב, ר נפתלי הכהן בעל \"סמיכת חכמים\", בעל \"לקוטי יוסף\""},{"i":19455,"n":"ז\"ק, שמואל שמלקא מאוסטרהא","f":"יעקב שמחה בונם מאוסט","b":"מחכמי אוסטרהא, מאלופי הח\"ק ונזכר בפנקסים שם-תפה."},{"i":19456,"n":"ז\"ק, שמחה בונם מלבוב","f":"מאיר ז\"ק","b":"מגדולי לבוב-ת\"ל"},{"i":19457,"n":"ז\"ק, שמחה מקמינקא","f":"ישראל ז\"ק","b":"רב בקאמניקא-ת\"פ"},{"i":19458,"n":"ז\"ק, שמעון מפרמישלא","f":"גד","b":"רב בפרעמיסלא"},{"i":19459,"n":"ז\"ק, שמעון מרוזינאי","f":"ישראל הקדוש מרוזינאי","dt":"תנו","b":"רב ברוזינאי"},{"i":19460,"n":"זקהיים, אברהם מוילנא","f":"יוסף חלפן","k":"בעל יד חזקה","bt":"תקס","bp":"וילנא","dt":"תרלב - כ סיון","dp":"וילנא","b":"מחכמי וילנא - נחשף להשכלה כשנסע עם אמו לאשכנז לרפואתה, חברם של אד\"ם הכהן, יצחק איזיק בן יעקב ועוד. היה מתרגם של מונטיפיורי בזמן ביקורו בוילנא-1846. פרסם מאמרים ב\"דביר\" למ.א. גינצבורג - וילנא תרכב, וב\"אוצר השרשים הכללי\" ליצחק זיבנברגר - וארשא תרכב. חיבר גם \"עז ומשפט\" על תרי\"ג מצוות ואבד. הסכים על \"כוכבא דשביט\" לר חיים זליג סלונימסקי."},{"i":19461,"n":"זקהיים, אברהם מלונא ופ\"ת","f":"משה נתן מקובנא","k":"בעל נטעי איתן","bt":"תריח","bp":"מולדוצנו-פלך מינסק","dt":"תרצט","dp":"פתח תקוה","b":"תלמיד ישיבת וולוזין, וכולל קובנא. חתן ר הלל דוד הכהן טרוויש מוילקי בעל \"ונגש הכהן\". רב בקובנא, וידישוק, לייפון, ווליה(=ואליע, וואליא)-פלך גרודנא, לונא-פלך גרודנא, סימפרופול-קרים ועוד, נסמך ע\"י הנציב ור יצחק אלחנן. נתפרסם כצדיק גם בעיני הנוצרים. עלה לארץ-תרפה והתישב בפתח תקוה. עורך ב\"הפסגה\" לצד חותנו האב\"ד בווילקי. חיבר \"נטעי איתן\" (וארשא תרסא וחלקים נוספים בוילנא וירושלים), ספר \"התורה והמלאכה\" (ירושלים תרפח), \"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה, ועוד. בניו: ר קלמן, ד\"ר משה ירדני זקהיים - מנהל הגימנסיה העברית בוילקוביסק. לתולדותיו ב\"דעת קדושים\" לפרידלנד."},{"i":19462,"n":"זקהיים, בנימין מיקטרינסלב","f":"טודרוס משה מדרוזניק","bt":"תר","bp":"סלונים","b":"חתן משפחת פיקסמאן מרוזינאי. רב ביקטרניסלוב-תרס מעל 30 שנה. הסכים על ספרים רבים. הניח כתבים - בכת\"י."},{"i":19463,"n":"זקהיים, יהושע מירושלים","b":"מראשי בית היתומים דיסקין בירושלים-תרסח."},{"i":19464,"n":"זקהיים, יוסף (חלפן) מוילנא","f":"טוביה בן אריה ליב","dt":"תרח - כ אד\"ב","b":"גביר מחכמי וילנא. הקדיש ביכ\"ס בוילנא. חתן הגביר ר שבתי, ובזיוו\"ש חתן ר לוי רוקח. בניו: ר אברהם, ר יצחק לוי, חתנו ר אריה ליב גינצבורג מוילנא - נפטר כה אדר תרכה. לתולדות המשפחה נדפס \"דעת קדושים\" תרנה, בהשתדלות חתן נכדתו הגביר ר משה אריה ליב פרידלנסקי מפטרברוג."},{"i":19465,"n":"זקהיים, יצחק לוי","f":"יוסף חלפן","dt":"תרלח","dp":"רוסטוב","b":"אחיו של ר אברהם מוילנא."},{"i":19466,"n":"זקהיים, ישראל מקובנא","f":"משלם זלמן מפוקרוי","bt":"תקל","bp":"וילנא","dt":"תרכו","b":"תלמיד הגר\"א. הראשון ממשפחתו שנקרא זקהיים. חתן הגביר ר אברהם אבא סולוביציק מקובנא. היה מראשי הקהלה. נפטר קרוב לגיל 100. בנו - הגביר בן ציון מקובנא."},{"i":19467,"n":"זקהיים, מרדכי מפינסק","f":"אהרן","k":"מרדכי ראזינאיר","bt":"תקפה","bp":"קריניק או רוזונאי","dt":"תריט - כ תשרי","dp":"פינסק","b":"בן למשפחת ז\"ק מרוזנאי. תלמיד ר יעקב מאיר מיאלאווקה. רב בטשכנובצי(=צ'כנוביץ). רב בפינסק וקרלין-תרד על מקום ר אהרן בעל \"תוספות אהרן\". מתורתו בספרי חכמי דורו ובהם ב\"לקח נחמד\". נזכר ב\"המגיד\" שנה שניה. בניו: ר משה ור יהושע. מסופר עליו שפגש את ר עקיבא איגר במינסק ור עקיבא התפעל ממנו ונתן לו סמיכה. נספד ע\"י גדולי ישראל גם בדפוס ובהם ב\"שארית הברכה\" לר אשר הכהן משרשוב, \"שמן ששון\" לר יצחק ששון מהורדנא, ב\"חדושי מהרמ\"י\" לר משה יחזקאל גורדונצ'יק, ו\"שמע יעקב\" לר יעקב ברצ'ה. בנו - ר משה מפינסק וקובל."},{"i":19468,"n":"זקהיים, משה מקאוולא","f":"מרדכי מפינסק","bt":"תרב","dt":"תרסג","b":"רב בקובל(=קאוולא)-ווהלין-תרמז, וחתנו ר יום טוב ליפמן שיק על מקומו אחריו."},{"i":19469,"n":"זקהיים, נתנאל","dt":"תשג","b":"רב בסעליב"},{"i":19470,"n":"זקהיים, קלמן","f":"אברהם","b":"נכד ר הלל דוד טרוויש. פרסם מאמרים ב\"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה."},{"i":19471,"n":"זקליר, משה יצחק מקיטוב","b":"רב בקיטוב-תריט."},{"i":19472,"n":"זקן הכהן מאלגיר","bt":"תר","dt":"תרע - בערך","b":"רב בעין לבידא-אלגיר. ברשימת המסייעים ל\"בית שלמה\" ירושלים תרנב."},{"i":19473,"n":"זקן, יום טוב משלוניקי","dt":"שה - שבט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":19474,"n":"זקן, עקו ממרוקו","b":"מחכמי כפר שמלאלין-מרוקו-תרכט וחתם על מכתב לחכמי פאס עם ר שם טוב עובדיה."},{"i":19475,"n":"זקן, שלום","b":"נזכר בשטר עדות-תקמא."},{"i":19476,"n":"זקן, שמואל מפאס-מרוקו","k":"בעל גפן פוריה","bt":"תל","dt":"תצג-תק","dp":"פאס?","b":"רב בפאס-תע, תלמיד ר יהודה ן עטר, ר יהודה בן יוסף עוזיאל. חברם של ר שם טוב בן אמוזג, ר עמנואל סירירו. חיבר גם \"פרי עץ הגן\", \"פרי מגדים\" - ואבד."},{"i":19477,"n":"זקס יחיאל מיכל","bt":"1808","dt":"ה'תרכד 1864","bk":[["באר מיכל",""]]},{"i":19478,"n":"זקרי, נסים מבומבי","f":"אלישא","bt":"תרז או תריז","bp":"בגדד","b":"רב בקהלת \"כנסת אליהו\" בבומבי-הודו-תרס, בהשפעתו בנה הגביר אליהו ששון ביכ\"נ לקהלה. אחיו: ר עזרא בעל \"שירי רנה\", ר אליהו מבגדד."},{"i":19479,"n":"זקרי, עזרא מבגדד","k":"בעל שירי רינה","b":"מגדולי רבני בגדד-תרמ. ?? לא באוצר - הספר קיים ??"},{"i":19480,"n":"זקש - משפחה","b":"מצאצאי ר שניאור שהיה שר האוצר במדינת אונגרן ונהרג עק\"ה וצאצאיו נקראו זק\"ש - זרע קדושים שניאור."},{"i":19481,"n":"זקש מרדכי יהודה ליב בן שניאור זלמן זאב","bt":"1906","dt":"ה'תשכג 1963","bk":[["לקראת שבת",""]]},{"i":19482,"n":"זקש, אברהם טייץ זאסלבר","f":"שניאור הקדוש מהונגרי","b":"בנו של שר הכספים של הונגריה שנהרג עק\"ה. הגיע לוילנא והיה מראשי ועד ארבע ארצות. חתם שלישי על כתב רבנות ר שמואל רבה האחרון של וילנא-תקי. בנו - ר אורי - חברו של הגר\"א בקידאן."},{"i":19483,"n":"זקש, אברהם מאשכנז ואיטליה","f":"יחיאל","k":"אברהם זכסן","b":"גלה מאשכנז לאיטליה-ר' והתישב בפורטו-ליד וירונה ולימד שם תורה בזמן מהרי\"ק ומהר\"י מינץ ונזכר בשות מהר\"מ מינץ. בנו ר יחיאל זכסן קסטולצי, וחתנו ר יעקב לנדא בעל האגור המזכירו בספרו."},{"i":19484,"n":"זקש, אברהם שמחה מארה\"ב","f":"בן ציון וולף","k":"בעל דער היסטארישער מ","bt":"1878","bp":"זאגר-ליטא","dt":"1931","b":"הצטרף לתנועה המהפכנית ברוסיה, נאסר-1901. פרסם מאמרים בנושאי סציאליזם. למד בברלין כלכלה וחקלאות. היגר לארה\"ב-1908. חיבר גם \"פאליטישע עקאנאמיע\" נ\"י 1918. חיבר מסות על ר ישראל סלנטר, המגיד מקאלם, ועוד. מייסדי \"ייווא\"."},{"i":19485,"n":"זקש, אורי מוילנא וקובנא","f":"אברהם ז\"ק מוילנא","bp":"[קידאן]","b":"אביו הגיע מהונגריה לוילנא והיה מראשי ועד ארבע ארצות. חברו של הגר\"א - למדו יחד אצל ר משה מרגליות בעל \"פני משה\" בקידאן. מחכמי וילנא, רב מגיד בסלובודקא(=ויליאמפול) ובקובנא ונאמן הקהלה, חתם שלישי על כתב הרבנות של ר שמואל-אב\"ד אחרון בוילנא. בנו ר צמח מקידאן."},{"i":19486,"n":"זקש, אפרים אליעזר","f":"בן ציון","bt":"1858","bp":"יאלוק","dt":"1944","dp":"רחובות","b":"תלמיד ישיבת וילנא ונודע בשם \"העילוי מיאלוק\". היגר לארה\"ב והיה פעיל בתנועה הציונית. עלה לארץ-1908 והתישב ברחובות ועסק בפרדסנות, ויחד עם זאת היה בן תורה והקדיש זמנו ללימודים. דאג למתיישבים התימנים ברחובות וקראו לשכונתם ע\"ש \"שכונת אפרים\". חיבר בכת\"י מחקר גדול על ספרות ישראל והעמים."},{"i":19487,"n":"זקש, דב (ברנרד) מדרום אפריקה","f":"אבא","bt":"1905","bp":"קאמאי-ליטא","b":"היגר לדרום אפריקה והיה עורך ב\"ג'ואיש טיימס\", ופעיל במגבית המאוחדת בדרום אפריקה. חיבר ספר על יהדות באנגלית."},{"i":19488,"n":"זקש, דניאל זליג מטבריג","k":"בעל חמדת דניאל","b":"ר\"מ בטבריג,רב בבדבילישקי,עלה לא\"י-תרפ\"ד."},{"i":19489,"n":"זקש, דניאל מזאגר","b":"מרבני זאגר"},{"i":19490,"n":"זקש, דניאל מראדוילישוק","b":"רב בראדוילישוק על מקום ר יצחק הורביץ."},{"i":19491,"n":"זקש, חיים ישראל","f":"צמח","bt":"1867","bp":"יאנישוק-ליטא","dt":"1934","dp":"תל אביב","b":"תלמיד ישיבות ליטא. התקרב לציונות ועסק במסע תעמולה בתחום המושב למען הציונות. היה סניגור במשפט \"ה\"חדר\" בויטבסק. התישב בשאוולי. פרסם מאמרים ב\"אידישע שטימע\", וזכרונות על גירוש שאוולי (רשומות ה). עלה לארץ-1932"},{"i":19492,"n":"זקש, חיים ליב מאזדא וארה\"ב","f":"יהודה זקס","k":"בעל דברי חיים","bt":"תרמט","dt":"תשכז - כח טבת","b":"רב במילסלוביטש,הרוזאבא,אזדא,קליבלנד,עלה לכפר חסידים-תשכ\"ה"},{"i":19493,"n":"זקש, חיים מראסיין","b":"רב מראשי הציונים בראסיין. הספיד את הרצל בביהמ\"ד."},{"i":19494,"n":"זקש, יהודה","b":"רב בוואלק-תר\"נ"},{"i":19495,"n":"זקש, יהודה בן ציון מליטא","f":"משה הלוי","k":"בעל בכורי ציון וענבי","bt":"תרל","dt":"תרצב-ה","dp":"נאמוקשט","b":"תלמיד ישיבת וולוזין. רב בפרזראסלה-פלך סובאלק-תרעז, נאמוקשט(=נעמאקשט)-פלך קובנא על מקום אביו. מראשי המזרחי בליטא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"המגיד\" - סטמר תרפח-תרצט. נסמך מאת: ר אליעזר שמחה רבינוביץ, ר אלכסנדר משה לפידות."},{"i":19496,"n":"זקש, יהודה מניו יורק","b":"פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":19497,"n":"זקש, יואל דב מליסא","f":"מיכל מליפנא","bt":"תקל","dt":"תקצה","b":"מקובל מחכמי ליסא, רב בלאבשין(=לובשין)-ליד ליסא-תקע. היה חברו של ר עקיבא איגר, וכן אביו."},{"i":19498,"n":"זקש, יואל דוד","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":19499,"n":"זקש, יואל מאוסטרליץ וברלין","f":"יקותיאל מגלוגא","k":"בעל אבן הטועים","b":"חתן ר יחיאל מיכל חסיד רבה של ברלין. אב\"ד אוסטרליץ, דיין בברלין אצל הראב\"ד ר דוד פרנקל (ואת משכורתו מימן ר פייטל הפרנס - גיסו של ר דוד - שהיה קרוב משפחה לרבים מהקהילה ולכן נצרך דיין נוסף לדון אותם). הסכים על 'באר יעקב'-פיורדא תקכז אחרי ר אהרן בן משה מגזע צבי."},{"i":19500,"n":"זקש, יוסף חיים מסלובודקה","b":"ר\"מ ומנהל ישיבת \"אהל משה\" בסלובודקה-תרצג."},{"i":19501,"n":"זקש, יוסף מדרום אפריקה","f":"שאול דוד","bt":"1896","bp":"שאוולי","b":"היגר לדרום אפריקה. חיבר ספרים בנושאים יהודיים באנגלית."},{"i":19502,"n":"זקש, יחיאל מיכל","f":"נפתלי יהודה","bt":"תקסח","bp":"גלאגוי","dt":"תרכד - כג שבט","dp":"ברלין","b":"למד בברלין, ד\"ר לפילוסופיה, מנהל ביה\"ס לבנות בברלין, דרשן בפרג-תקצו, דרשן ודיין בברלין. ממתנגדי אספת הרפורמים בברוינשוייג. השתתף בתרגום כתבי הקדש לגרמנית - בהוצאת יו\"ט צונץ-1837. חיבר ספרים בחכמת ישראל בגרמנית. פרסם מאמרים בעברית וגרמנית ובהם על הפיוט והפייטנים הקדומים."},{"i":19503,"n":"זקש, ישראל מוילנא","f":"יצחק","dt":"תרטו - יד אדר","dp":"וילנא","b":"סו\"ד בוילנא ודיין על מקום ר אליהו הינדעס. חתם על ש\"ס וילנא-תקצה. בן אחותו של ר אבלי מוילנא."},{"i":19504,"n":"זקש, מיכל מליפנא","b":"מחכמי ליסא, רב בליפנא. חברו של ר עקיבא איגר. בנו - ר דב יואל מלאבשין."},{"i":19505,"n":"זקש, מנחם מנדל יוסף מארה\"ב","f":"יעקב מרדכי","bt":"תרנד","bp":"שידלובה-ליד קעלם","dt":"תשלד - יט טבת","b":"תלמיד ישיבת \"בית יצחק\" בסלובודקה, ראדין, פוניבז, הומל אצל ר ראובן דב דסלר. חתן החפץ חיים. ר\"מ בישיבת ראדין, וילנא, בזמן השואה עבר לארה\"ב-תשא, מראשי ועד ההצלה, יסד ישיבת \"חפץ חיים\" בניו יורק, ר\"מ בישיבת רבי יצחק אלחנן-תשו, עלה לארץ. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":19506,"n":"זקש, מרדכי יהודה ליב מירושלים","f":"שניאור זלמן זק\"ש","k":"בעל זמנים","bt":"תרסו","dt":"תשכג - ה אדר","b":"רב בזכרון משה בירושלים-תשי\"ב. חתן ר' יעקב משה חרלפ. פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפו, \"בית הכנסת\" - תל אביב תשו, \"ועד חכמים\" - ירושלים תרפג, \"קול תורה\" - ירושלים תרץ-תשז.","bk":[["מילי דמרדכי",""]]},{"i":19507,"n":"זקש, מרדכי מקוביזצא","f":"טוביה","k":"בעל קרית ארבע","bt":"תרטז","b":"תלמיד ר אלעזר מלוצין. רב באינטוריק-פלך וילנא-תרמד, קאביזצא-פלך צרניגוב. נסמך מאת: ר יצחק אלחנן מקובנא, ר אליקום שפירא מגרודנא, ר אלכסנדר משה לפידות. חיבר \"קרית ארבע\" - על הלכות לולב - בכת\"י."},{"i":19508,"n":"זקש, משה הלוי מנאמוקשט","f":"יעקב","k":"בעל דברי משה","bt":"תקפט","bp":"וילנא","dt":"תרסה","dp":"נאמוקשט","b":"גיסו של ר יקותיאל ליב עליאן. תלמיד ר ישראל סלנטר. ר\"מ בישיבת מאזייק, וולוזין, כונה \"העילוי מאושמיאנה\". רב בראסיין, פיליפובה, רב בנאמוקשט-תרל כ-20 שנה ובנו ר יהודה בן ציון על מקומו אחריו."},{"i":19509,"n":"זקש, משה מירושלים","f":"מרדכי","bp":"גרמניה","dt":"תרל - ו תמוז","dp":"ירושלים","b":"חתן ר צדוק הלוי (שע\"ש נקרא החצר \"ר צדוק'ס האש\"). תלמיד החת\"ס, ר מרדכי בנט. עלה לארץ והיה מגדולי חכמי ירושלים-תקצד, פעל לבנית בתי מחסה, ולעיסוק בחקלאות. בשליחות כולל הו\"ד ו\"בתי מחסה\"-תרכג. ראש משפחת זקש בירושלים."},{"i":19510,"n":"זקש, מתתיהו מקידאן","f":"צמח מקידאן הזקן","b":"נכד ר אורי-חברו של הגר\"א. רב בקידאן על מקום אביו, ובנו ר צמח - הנכד - על מקומו אחריו."},{"i":19511,"n":"זקש, נחמיה","f":"גרשון","bt":"1838","bp":"אופינה-ליטא","dt":"1903","dp":"וארשא","b":"תלמיד ישיבת סלנט, קאלם, אלקסוט. תלמיד ביהמ\"ד לרבנים בוילנא. מורה בוארשא. הו\"ל דברי ימי היהודים לגרץ באידיש. צנזור ממשלתי לספרים עבריים בוארשא."},{"i":19512,"n":"זקש, ניסן מאיר פיבל מירושלים","f":"מרדכי יהודה ליב","k":"בעל אור פני מלך"},{"i":19513,"n":"זקש, צבי","b":"מגדולי חכמי דורו-שע\"ב"},{"i":19514,"n":"זקש, צמח מקידאן - הזקן","f":"אורי בן אברהם","b":"סו\"ד בקידאן בזמן ר משה מרדכי קצנלנבוגן. בניו: ר ראובן מקידאן, ר מתתיהו (ויש אומרים - נכדו) ונכדו ר צמח - דיין בקידאן ואב\"ד בזאגר."},{"i":19515,"n":"זקש, צמח מקידאן - הנכד","f":"מתתיהו מקידאן","bt":"תקנו","bp":"קידאן","dt":"תרכג","dp":"זאגר","b":"נכד ר צמח מקידאן. דיין בקידאן על מקום אביו, ונדזיגולה, אב\"ד זאגר ישן-תקעה על מקום ר יצחק איזיק רבינוביץ. כתב שירים בעברית. בנו החוקר והסופר שניאור זקש."},{"i":19516,"n":"זקש, ראובן מקידאן","f":"צמח מקידאן","dt":"תריב - ד אד\"ב","dp":"קידאן","b":"רב בואלפע, קידאן על מקום ר אריה ליב הכהן. בניו - ר אליהו ואלפע מראסיין, ר דוד ואלפע מראסיין."},{"i":19517,"n":"זקש, שאול משקודוויל","b":"הקים ישיבה קטנה בשקודוויל-אחרי מלחה\"ע ה-I ועמד בראשה יחד עם ר אליהו בר קאטץ. הישיבה משכה את אנשי הישובים הסמוכים שבאו לבקש בה חתנים לבנותיהם."},{"i":19518,"n":"זקש, שלמה זלמן מבירז","f":"מאיר","k":"זעלמעלע פרומאק","bt":"תקעד","dt":"תרלו - ניסן","b":"רב בבירז על מקום ר שמעון מרקל שפירא(=קיידונר), ור אשר לוינזון על מקומו אחריו (באלבום ליטא מופיע - ר דוד בעל \"שירה לדוד\" על מקומו אחריו), לוקניק, קרטינגה."},{"i":19519,"n":"זקש, שלמה יהודה","f":"יעקב","bt":"1842","bp":"סארהיי-ליטא","dt":"1902","dp":"המבורג","b":"תלמיד ישיבת וולוזין. עסק במסחר והתעשר. הקים ביח\"ר לגפרורים והעסיק כ-1000 פועלים. מחובבי ציון וביקר בארץ עם ר שמואל מוהליבר. ציר בקונגרס הציוני, וחבר \"אוצר התישבות היהודים\"."},{"i":19520,"n":"זקש, שניאור זלמן","dt":"תשטו - ז ניסן","b":"מרבני ירושלים"},{"i":19521,"n":"זקש, שניאור מפאריס","f":"צמח","k":"בעל כנפי יונה","bt":"1816","bp":"קיידאן","dt":"1892","dp":"פאריס","b":"גדל בזאגר אצל אביו שהיה הרב שם. פנה להשכלה ועבר לברודי. פרסם מאמרים על חכמי ישראל ועל יהודי רוסיה, עסק בהוראה בראסיין, עבר לברלין ולמד באוניברסיטה. חיבר ספרים ומחקרים רבים. מחנך בבית הברון יוסף גינצבורג בפאריס (לבנו נפתלי ולנכדו דוד). יסד ספריה מדעית ובה כתבי יד חשובים. פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרך, \"כבוד הלבנון\" - פאריס תרכה - על עזיבת המלבי\"ם את פאריס לטובת לונטשיץ."},{"i":19522,"n":"זר, שמואל ל' מניו יורק","b":"פרסם מאמרים ב\"תלפיות\" - נ\"י תשד."},{"i":19523,"n":"זראפה, סעדיה","b":"מגדולי חכמי המערב במארוקו-ש\"צ"},{"i":19524,"n":"זרב מדרהאטשין","dt":"תקנג - כו טבת","b":"תלמיד ר פנחס מקוריץ במירופול."},{"i":19525,"n":"זרביב, אברהם מאלגיר","f":"יצחק בן פרג'","k":"בעל עץ חיים","bt":"תרל","bp":"קצמטינא","dp":"קצמטינא(=קונסטנטין)","b":"עסק בפילוסופיה יהודית, רב בסטיף-אלגיר, קצמטינא, עסק בפילוסופיה, חיבר \"עץ חיים\" פירוש לספר העיקרים' ,\"פחד יצחק\", ועוד. היה מהרבנים המשכילים. עורך העתקון \"אלחיכמא\" - קצמטינא 1912-1913."},{"i":19526,"n":"זרביב, יהודה מאלגיר","bt":"תרן - בערך","dt":"תשי - בערך","b":"מצאצאי ר מסעוד זגביב. רב בבטנא-אלגיר. החזיק בכתב היד של \"עט הזמיר\". סייע בהדפסת \"ימי אברהם\" ג'רבה תרצט."},{"i":19527,"n":"זרביב, יצחק חי נסים מאלגיר","f":"מכלוף","bt":"תרפא","bp":"עין בידא-אלגיר","dt":"תשנד","dp":"ירושלים","b":"רב האחרון של קצמטינא-תשיח - תשכא, עלה לארץ והתישב בירושלים וכיהן כרב בישובי אזור בית שמש. תשובה ממנו בשו\"ת ר א\"מ הלוי פינגרהוט."},{"i":19528,"n":"זרביב, יצחק מאלגיר","f":"רפאל","dt":"תרעד","b":"רב בעין בידא-אלגיר."},{"i":19529,"n":"זרביב, ישראל מקצמטינא","bt":"תמ","dt":"תקי","b":"תלמיד ר מסעוד זנביב. רב בקצמטינא. עצמותיו הועלו להר הזיתים-תשל או תשמג."},{"i":19530,"n":"זרביב, כליפא מאלגיר","bt":"תקם - בערך","dt":"תרי - בערך","b":"דיין בקצמטינא אצל ר נתן טוביאנה."},{"i":19531,"n":"זרביב, מסעוד מאלגיר","k":"בעל זרע אמת","dt":"תעז","dp":"קצמטינא - ירושלים","b":"רב בקצמטינא(=קצונטינא, קונסטנטין)-אלגיר, בן דורו של ר יהודה עייאש. דרשן, פרשן ומלמד תורה. נאסר ע\"י אנשי הביי (השליט) ואף קיבל עונש 400 מלקות. חיבר ספר \"זרע אמת\", ר חיים טולדנו חיבר הקדמה לספרו ובה מתאר כי הספר היה מקודש והשתמשו בו לעזרה ליולדות וכו', וכן היה מקום קברו מקודש. עצמותיו נקברו בהר הזיתים - תשל. בית הכנסת שלו נקרא \"דאר רבי מסעוד\" ומקום ישיבתו נשאר פנוי - ולא ישב אדם על מקומו."},{"i":19532,"n":"זרביב, שלום מאלגיר","bt":"תן","dt":"תקי - בערך","b":"תלמיד ר מסעוד זרביב. רב בקצמטינא. עצמותיו הועלו לארץ ונקבר בהר הזיתים-תשל."},{"i":19533,"n":"זרביב, שלמה מאלגיר","f":"כלפה","k":"בעל דברי חכמים","bt":"[תרך]","dt":"תץ - בערך","b":"רב בקצמטינא. תרגם לערבית יהודית חלק מספר יהושע, עם חבריו ר\"ד הכהן ור\"צ שקרון, ונדפס בשם \"דברי חכמים\" תונס תרעא. ?? לא באוצר ??"},{"i":19534,"n":"זרביב, שמואל מאלגיר וטירת הכרמ","f":"פנחס","bt":"תרעב","dt":"תשכג","b":"רב בגילמא-אלגיר, עלה לארץ וכיהן כרב בטירת הכרמל."},{"i":19535,"n":"זרביב, שמעון מקצמטינא","bt":"[תקם]","dt":"תרך - בערך","b":"רב ודיין בקצמטינא. מצאצאי ר מסעוד זגביב. מתלמידיו ר אברהם חלימי."},{"i":19536,"n":"זרדין, אברהם זלמן הכהן משוורזנ","f":"משה","bt":"תרל","b":"תלמיד ישיבת איישישוק, וילנא, כולל קובנא. מו\"צ בברויסק-תרסד, בארווקה(=באראווקא), שוורזנא(=שווערזנא, שוורזנץ)-פלך מוהילוב-תרסד. נסמך מאת: ר שלמה הכהן מוילנא, ר שמריהו נח שניאורסון מבוברויסק, ר שמואל משה שפירא מבוברויסק, רא\"ל ראשקעס מ וילנא, רי\"א מה-יפית מפרייל."},{"i":19537,"n":"זרוק, יוסף חיים מלוב","f":"שמעון","bp":"זליתן-לוב","dt":"תשמב","dp":"ירושלים","b":"סגי נהור מחכמי לוב בעל זכרון מופלא, עלה לירושלים ולימד בישיבת \"פורת יוסף\". עליו ב\"לכו חזו מפעלות צדיקים\" ירושלים תשנז."},{"i":19538,"n":"זרח ברפת מספרד","b":"רב בספרד. חיבר ספר איוב בחרוזים."},{"i":19539,"n":"זרח הטרוקי הקראי","f":"נתן","b":"מחכמי הקראים - שנות ה-ת'. פגש בליטא את ר יוסף שלמה רופא דילמדיגו שחיבר ספר \"אלים\" בעקבות המפגש, וכן כתב אליו את \"אגרת אחוז\". חיבר תפלות ופיוטים בסידור הקראים - חלקם על דרך הקבלה."},{"i":19540,"n":"זרח המגיהי ממצרים","b":"רב במצרים-סוף שנות ה-ש'."},{"i":19541,"n":"זרח מוילנא","f":"שמואל","dt":"תקפו - כב שבט","dp":"וילנא","b":"מצאצאי ר משה איוויער וגדל אצלו. מחכמי כפר ליד וילנא, והצניע את גדולתו. נקבר לצד ר יהודה לימא."},{"i":19542,"n":"זרח מרכניץ","f":"מאיר קום קדיש","k":"בעל אוצר החיים","b":"מו\"צ ברעכניץ(=רכניץ)-תקפ."},{"i":19543,"n":"זרח ן, מנחם","f":"אהרן מנבארה-ספרד","k":"בעל צדה לדרך","bp":"נבארה-ספרד","dt":"קלד-מה - תמוז","dp":"ספרד","b":"מגדולי ההלכה בדורו, בן למשפחה ממגורשי צרפת שהגיעו לנבארה-ספרד - סו (1306). חתן ר בנימין עביץ מאשתיליא (אסטליה)-ספרד. כל משפחתו נהרגו עק\"ה ע\"י הצרפתים בנאברה, והוא ניצל והגיע לטולידו. תלמיד ר יהושע ן שועיב, רב באלקעה-ספרד-קי על מקום ר יוסף ן אלעיש-קי. תלמיד ר יהודה בן הרא\"ש. רב בטולידו במלחמה סבל מאוד עם כל קהילת טולידו-קכח וניצל ע\"י דון שמואל אברבנל מאישביליא (שהשתמד לפני פרעות קנא)."},{"i":19544,"n":"זרח, יחיאל","k":"בעל מעין מבית ה'"},{"i":19545,"n":"זרח, עובדיה משלוניקי","b":"מחכמי שלוניקי-תקם. חתם על שטר בוררות בין בניו של ר יצחק מולכו לגבאי הקהל."},{"i":19546,"n":"זרחוביץ, אברהם מוידז","bt":"תרנא","dt":"תרצב - יד ניסן","b":"רב בוידז. פרסם מאמרים ב\"קבוצי אפרים\" - יאסי-בוקרשט תרעד."},{"i":19547,"n":"זרחי, אשר ליפמן מקובנא ונ\"י","f":"שמואל הלל","k":"בעל אשל האזרחי","bt":"תרכב","bp":"קובנא","dt":"תרצב - כ סיון","b":"תלמיד ישיבת קובנא, וולוזין. חתן ר שמואל ברוך פישמן מראדזילאווא-פלך לומזה. רב בניו יורק-תרנג, דה מוין-אייווא, לואיסויל-קנטקי-תרסג. נסמך מאת: ר יצחק אלחנן מקובנא, ר יצחק מאיר מסלובודקא, ר חיים סגל מיאנוב, ר יעקב יוסף מניו יורק. פרסם חדושי תורה ב\"המאסף\" וכתב ערכים באנציקלופדיה \"אוצר ישראל\". מזכיר אסיפת רבנים בסינסינטי ופרסם מאמר על כך ב\"בית ועד לחכמים\" - נ\"י תרסג, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג, חיבר ערכים ב\"אוצר ישראל\". ?? לא באוצר ??"},{"i":19548,"n":"זרחי, ישראל אידל מאנטאקליא","f":"יהודה ליב ממילאט","dt":"תרכב - כח תמוז","b":"גיסו של הגביר ר משה שיינוק מוילנא. מו\"צ באנטאקליא-תרמ על מקום ר יעקב הרץ בן יוסף."},{"i":19549,"n":"זרחי, ישראל מירושלים","f":"שמעון זאב","k":"בעל עיטורי ירושלים","b":"סופר בירושלים."},{"i":19550,"n":"זרחי, שמעון מליטא וירושלים","f":"אברהם","k":"בעל נחלת שמעון","r":"רב דטבריג ועוד","bt":"תקמח","bp":"ז'זמיר-ליטא","dt":"תרכ - ט אלול","dp":"ירושלים","b":"מצאצאי-דור תשיעי הפייטן ר אליהו הזרחי שנהרג עק\"ה-תח, מצאצאי \"באר הגולה\", למד עם ר משה בן הגר\"א. ראב\"ד ביעקובשטאט(=יאקובשטט)-לטביה-תקצב, בירז'-תר, טאווריג(=טוירנן), בשנת תריז עלה לירושלים והיה ממיסדי וראשי ישיבת \"עץ חיים\". חיבר \"נחלת שמעון\" וילנא תרנז. בנו - ר תנחום בעל \"זכרון תנחום\", חתניו - ר שמואל מרדכי רשקס - רב בשניפישוק, ר איזיק רבינוביץ מטלז (ואשתו מרים - בתו של ר שמעון - הו\"ל ספר אביה \"נחלת שמעון\"). מתורתו ב\"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["נחלת שמעון – שו\"ת",""]]},{"i":19551,"n":"זרחי, תנחום מטאווריג","f":"שמעון מטאווריג וירוש","k":"בעל זכרון תנחום","b":"מחכמי ירושלים."},{"i":19552,"n":"זרחי-זופוביץ, יוחנן מטבריה","f":"חיים יהודה","bt":"תרלד","bp":"איישישוק","dt":"תשז - כא כסלו","dp":"טבריה","b":"רב במיאדל, סימנא(=סימנה)-ליטא, ספיזישוק, ראדוילישוק-תרפד, פעיל בתנועת ה\"מזרחי\" והיה ציר בקונגרס הציוני. כמה מבנותיו עלו לארץ בעלייה השלישית. עלה לארץ-תרצז וכיהן כרב ראשי בטבריה, והיה מקורב לאנדי הקיבוצים בעמק הירדן. תכנן לעזוב את הרבנות ולעבור לקיבוץ טירת צבי - אך לא הספיק."},{"i":19553,"n":"זרחיה היוני מקושטא","k":"בעל ספר הישר","b":"רב בביצנץ(=קושטא)-קנ."},{"i":19554,"n":"זרחיה הלוי מלוניל-פרובנס","f":"יצחק גירונדי","k":"הרז\"ה - בעל המאור","bt":"ד'תתפה","bp":"ספרד","dt":"ד'תתקמו","b":"עבר לצרפת, למד בפרובינצא, אצל חכמי נרבונה, ואחר כך לוניל, בספרו \"המאור\" הוא משיג על הרי\"ף, בלשן, פייטן, משורר, הרמב\"ן בספר המלחמות משיב על השגותיו"},{"i":19555,"n":"זרחיה מצפת ואזמיר","k":"ר' זרחיה מליריאה","b":"חכם שלם, רב בצפת, עבר לאזמיר-שצה."},{"i":19556,"n":"זריהן, אברהם ממראקש","dt":"תרס - טז ניסן","b":"מרבני מראקש, חכם שלם"},{"i":19557,"n":"זריהן, חיים מאלגיר","f":"שלמה","k":"בעל דרך החיים","bt":"תרם","dt":"תשי - בערך","b":"מדפיס מחכמי תלמסאן. הו\"ל וערך \"דרך החיים\", שיר ידידות - תלמסאן תרצב, \"בן אדמה\", ועוד. הדפיס כרוזים וחוברות."},{"i":19558,"n":"זריהן, יעקב חי מטבריה","f":"ברוך חביב","k":"בעל אהל יעקב","r":"רב קהילת הספרדים בטבריה","bt":"תרכט","bp":"טבריה","dt":"תשיג - כא אב","b":"חתן ר בנימין חמוי בעל \"אמתחת בנימין\". ראב\"ד בטבריה-תרפט על מקום ר אליהו ילוז. פרסם מאמרים ב\"הירח\" - ג'רבה תשח, \"כתר תורה\" - גרבה תרצח, \"מקבציאל\" - גרבה תרצה, \"הפוסק\" - תל אביב תש-תשיד.","bk":[["בכורי יעקב [שו\"ת]",""],["אהל יעקב - על התורה",""],["חלק יעקב - דרושים",""],["שופריה דיעקב - על התורה",""],["שושנת העמקים - מים עמוקים",""],["ביכורי יעקב",""]]},{"i":19559,"n":"זריהן, משה ממראקש","b":"אב\"ד במראקש-תשו, (כ-40 שנה)."},{"i":19560,"n":"זריהן, שמעון ממרוקו","b":"רב ודיין בסאפי-מרוקו - [תש]. חתן ר יהודה ן מויאל בעל \"שבט יהודה\"."},{"i":19561,"n":"זריצקי, דוד","b":"פרסם מאמרים ב\"בית המדרש\" - מונטרה תש.."},{"i":19562,"n":"זריצקי, יעקב יהושע מבלדונה","f":"יוסף מאיר","bt":"תרלב","b":"רב בבלודנה-פלך גרודנא-תרס."},{"i":19563,"n":"זרם, דניאל משלוניקי","dt":"שפא - ד טבת","dp":"שלוניקי","b":"מחכמי שלוניקי-שף."},{"i":19564,"n":"זרסקי, שמואל זנויל","k":"בעל אנשי שם"},{"i":19565,"n":"זרע יצחק - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה מאת ר יצחק רוסו ממונאסטיר."},{"i":19566,"n":"זרצקי, ישעיה","dt":"תשג","b":"רב בלודען"},{"i":19567,"n":"זרקא, יהודה מרודוס","f":"אברהם","k":"בעל לחם יהודה","b":"משורר מחכמי רודוס-שנות ה-ר'. חיבר \"לחם יהודה\" קושטא שך."},{"i":19568,"n":"זרקא, יוסף","f":"יהודה","k":"בעל רב פעלים","b":"חיבר \"רב פעלים\" על הדקדוק - בכת\"י. (אינו רבו של בעל \"שער אריה\")."},{"i":19569,"n":"זרקא, יוסף מפורטוגל ואיטליה","f":"שרגא","b":"רופא, מקובל מחכמי פורטוגל, גלה לאגרינגתי-איטליה - עוד לפני גירוש-רנז. חיבר פירוש לתפלות - הועתק ע\"י ר שמואל בן אברהם-רפט, פירוש לתורה, ועוד."},{"i":19570,"n":"זרקא, יוסף מתונס","b":"רב בטוניס-תקכ-תקמ, בזמן שהיה שם החיד\"א."},{"i":19571,"n":"זרקא, יצחק מקושטא","b":"רב בקושטא-תרעב. כרוז ממנו בעניני כשרות."},{"i":19572,"n":"זרקא, משה מירושלים","b":"רב בירושלים, חתם-תקסה עם ר יעקב משה עייאש ור חנניה מיכאל אריה."},{"i":19573,"n":"זרקא, שלום חי מתונס - ב","f":"ישועה","b":"מחכמי תונס. נכד ר יוסף זרקא בעל \"פרפראות לחכמה\" מתונס, והו\"ל ספר זקנו. נזכר ב\"שלמי תודה\" לר שלמה דאנה, ודרוש ממנו בספר תלמידו \"יצחק ירנן\" לר יצחק בן ישועה הכהן. הו\"ל גם \"מעשה נסים\" לר נסים הכהן מתונס."},{"i":19574,"n":"זרקא, שלום מתונס - א","dt":"תרלב - לפני","b":"דיין מחכמי תונס. אביו של ר שלמה זרקא בעל \"זבחי תרועה\". נזכר ב\"פרי קדש\". חתם-תרל עם ר אברהם חג'אג', ור סעדאני נטף, על תשובה לג'רבא. והסכים על ספר הפיוטים עם רבים מחכמי תונס."},{"i":19575,"n":"זרקא, שלמה מתונס - א","k":"בעל כסא שלמה","dt":"תקצו - לפני","b":"רב בתונס, דיין אצל מהר\"י טייב, מתשובותיו בספרי חכמי תונס."},{"i":19576,"n":"זרקא, שלמה מתונס ואלגיר","f":"שלום","k":"בעל זבחי תרועה","bp":"תונס","dt":"תרלו","dp":"גילמא-מחוז קצמטינא-אלגיר","b":"רב בתונס, עבר לאלג'יר וכיהן כרב בסוק-אראץ, ווהארן, קצמטינא. היה מתומכי ר משה סבעון במחלוקת אודות ר אברהם אנקאווא וספרו \"זבחים שלמים\". תרגם ספרים לערבית יהודית, וערך עם ר יהודה דרמון את \"רנה וישועה\", \"שי למורא\", ועוד. חתם עם רבני עירו על שאלה לר א חזן - \"תעלומות לב\".חיבר \"זברחי תרועה\", \"גרם המעלות\", ועוד."},{"i":19577,"n":"זרקא, שמואל מאלגיר","bt":"רץ - בערך","dt":"שן - בערך","b":"רב ומשורר באלגיר. התכתב עם ר אברהם גבישון והחליפו שירים ביניהם ונזכר ב\"עומר השכחה\"."},{"i":19578,"n":"זרקובסקי, יודל מגוסטינין","b":"פרסם מאמרים ב\"תלפיות\" - שנחאי תשו."},{"i":19579,"n":"זרקובסקי, צבי הירש","b":"עורך \"תלפיות\" - שנחאי תשו."},{"i":19580,"n":"ז\"ש, זאב וולף מבריסק","f":"שלמה זלמן","b":"מחכמי בריסק."},{"i":19581,"n":"ז\"ש, יהודה","f":"שלמה זלמן","bt":"תקסט","dt":"תרב - כח אייר","dp":"וילנא","b":"נכד ר משה קלצקי. חתן ר שלמה עליון. חתנו ר דוד בן יהודה הורביץ מוילנא."},{"i":19582,"n":"ז\"ש, יעקב אברהם מקראקא ולייפני","f":"ראה: אברהם מקראקא ול"},{"i":19583,"n":"זשאלאנדזש, חיים יואל מוארשא","b":"מעורכי \"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו."},{"i":19584,"n":"זשאלטאק, יעקב","b":"פרסם מאמרים ב\"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא."},{"i":19585,"n":"זשורוול, אליהו ליב מנארדטש","bt":"תרז","b":"רב בנארדטש-תרל\"ח"},{"i":19586,"n":"זשילקובקה, שמעון זאב","dt":"תשג","b":"מחשובי רבני פולין"},{"i":19587,"n":"זשמיר, שניאור זלמן","b":"רב חסידי חב\"ד בקובנה"}];
